const QUESTIONS = [
 {id:'q1',module:'m2',topic:'Gordon growth model',type:'Numerical',difficulty:'Core',title:'Value a stable dividend-paying share',stem:'A company has just paid a dividend of $2.00 per share. Dividends are expected to grow at 5% per year indefinitely, and shareholders require a 11% return. What is the estimated value per share under the Gordon growth model?',options:[{key:'A',text:'$33.33'},{key:'B',text:'$35.00'},{key:'C',text:'$38.89'}],correct:'B',explain:{intuition:'A share is worth the present value of future dividends. With steady perpetual growth, the next dividend is capitalized by the spread between the required return and long-run growth.',steps:['The dividend just paid is D0 = $2.00. Grow it one year to obtain D1 = 2.00 × 1.05 = $2.10.','Compute the capitalization spread: r − g = 11% − 5% = 6%.','Apply P0 = D1 / (r − g) = $2.10 / 0.06 = $35.00.'],formula:'P0 = D1 / (r − g), where D1 = D0 × (1 + g) and r > g.',rationales:[{key:'A',text:'$33.33 uses the current dividend of $2.00 instead of the next dividend of $2.10. The model discounts expected future distributions, so the dividend must be advanced one period.'},{key:'B',text:'Correct. The next dividend is $2.10 and the required-return-minus-growth spread is 6%, giving $35.00.'},{key:'C',text:'$38.89 would result from using a smaller spread of about 5.4%, inconsistent with the stated 11% required return and 5% growth.'}],trap:'Using D0 rather than D1 is a classic timing error. Also check that r is greater than g; otherwise the stable-growth formula is not economically valid.',memory:'Next dividend on top; required return minus growth on the bottom.',transfer:'If D0 were $1.50, growth 4%, and required return 9%, what would the Gordon value be?',transferAnswer:'D1 = $1.56; spread = 5%; value = $31.20.'}},
 {id:'q2',module:'m2',topic:'Implied required return',type:'Numerical',difficulty:'Core',title:'Solve for the required return',stem:'A share trades at $50.00. Its expected next-year dividend is $2.50 and its long-run dividend growth rate is 3%. Assuming the Gordon growth model applies, what required return is implied by the price?',options:[{key:'A',text:'5.0%'},{key:'B',text:'8.0%'},{key:'C',text:'10.0%'}],correct:'B',explain:{intuition:'The market price and dividend forecast can be rearranged to reveal the return required to justify that price under a stable-growth assumption.',steps:['Start with P0 = D1 / (r − g).','Rearrange to r = D1 / P0 + g.','Dividend yield = 2.50 / 50 = 5%. Add growth of 3%: implied return = 8%.'],formula:'r = (D1 / P0) + g',rationales:[{key:'A',text:'5% is only the forward dividend yield. It omits the 3% expected growth component.'},{key:'B',text:'Correct: 5% dividend yield plus 3% growth equals an 8% required return.'},{key:'C',text:'10% overstates the return implied by the provided dividend yield and growth rate.'}],trap:'Do not confuse dividend yield with total required return in a growth model.',memory:'Gordon return = forward yield + sustainable growth.',transfer:'If price is $40, D1 is $2, and g is 2%, implied r is 7%.'}},
 {id:'q3',module:'m3',topic:'FCFF from net income',type:'Numerical',difficulty:'Core',title:'Bridge net income to FCFF',stem:'A company reports net income of $80 million, depreciation of $12 million, interest expense of $10 million, a 25% tax rate, capital expenditure of $22 million, and an increase in working capital of $5 million. Estimate FCFF using the net-income bridge.',options:[{key:'A',text:'$65.0 million'},{key:'B',text:'$72.5 million'},{key:'C',text:'$82.5 million'}],correct:'B',explain:{intuition:'FCFF belongs to both debt and equity capital providers, so add back after-tax interest to net income, restore non-cash charges, and deduct investment needed to operate and grow.',steps:['Add back depreciation: $80 + $12 = $92 million.','Add back after-tax interest: $10 × (1 − 25%) = $7.5 million; subtotal = $99.5 million.','Subtract capital expenditure and working-capital investment: $99.5 − $22 − $5 = $72.5 million.'],formula:'FCFF = NI + non-cash charges + interest × (1 − tax rate) − capital expenditure − increase in operating working capital',rationales:[{key:'A',text:'This is too low; it likely subtracts the full interest expense or overstates investment outflows.'},{key:'B',text:'Correct. FCFF is $80 + $12 + $7.5 − $22 − $5 = $72.5 million.'},{key:'C',text:'This overstates FCFF by failing to deduct all investment outflows or by adding back pre-tax interest.'}],trap:'Use after-tax interest when starting from net income; do not confuse the change in working capital with its ending balance.',memory:'Net income → add non-cash items and after-tax interest → subtract reinvestment.',transfer:'If capex rises by $3 million with everything else unchanged, FCFF falls to $69.5 million.'}},
 {id:'q4',module:'m3',topic:'FCFE from FCFF',type:'Numerical',difficulty:'Core',title:'Convert FCFF to FCFE',stem:'A company generates FCFF of $150 million. After-tax interest expense is $12 million and net borrowing for the year is $8 million. Estimate FCFE.',options:[{key:'A',text:'$130 million'},{key:'B',text:'$146 million'},{key:'C',text:'$170 million'}],correct:'B',explain:{intuition:'Start with cash available to all providers, remove the cash flow belonging to debt holders, then add net debt financing that is available to equity holders.',steps:['Start with FCFF of $150 million.','Subtract after-tax interest of $12 million: $138 million.','Add net borrowing of $8 million: FCFE = $146 million.'],formula:'FCFE = FCFF − interest × (1 − tax rate) + net borrowing',rationales:[{key:'A',text:'$130 million can arise from subtracting interest and net borrowing rather than adding net borrowing.'},{key:'B',text:'Correct: $150 − $12 + $8 = $146 million.'},{key:'C',text:'$170 million adds interest or borrowing with the wrong sign and overstates the amount available to equity.'}],trap:'Net borrowing is debt issued minus debt repaid. Positive net borrowing increases FCFE; debt repayment can reduce it.',memory:'Move from all capital providers to equity: subtract after-tax interest, add net borrowing.',transfer:'If the company repaid $5 million more debt than it issued, net borrowing would be −$5 million and FCFE would be $133 million.'}},
 {id:'q5',module:'m4',topic:'Justified leading P/E',type:'Numerical',difficulty:'Intermediate',title:'Calculate a justified leading P/E',stem:'A mature company has a sustainable payout ratio of 40%, a required return on equity of 10%, and perpetual growth of 4%. Under stable assumptions, what is its justified leading P/E?',options:[{key:'A',text:'6.0×'},{key:'B',text:'6.67×'},{key:'C',text:'10.0×'}],correct:'B',explain:{intuition:'A stable-growth P/E rises with the fraction of earnings distributed and falls as the required return rises relative to growth.',steps:['Use the leading P/E relationship: payout ratio / (r − g).','The spread is 10% − 4% = 6%.','0.40 / 0.06 = 6.6667, or about 6.67×.'],formula:'Justified leading P/E = payout ratio / (r − g)',rationales:[{key:'A',text:'6.0× incorrectly uses a 6.67% spread or another inconsistent input.'},{key:'B',text:'Correct: 40% / 6% = 6.67×.'},{key:'C',text:'10× would require a different payout or a smaller required-return-growth spread.'}],trap:'This is a leading P/E, so be careful not to mix next-period earnings with a trailing denominator.',memory:'For stable leading P/E: payout divided by the return-growth spread.',transfer:'If payout is 50%, r is 9%, and g is 3%, justified leading P/E is 8.33×.'}},
 {id:'q6',module:'m4',topic:'Price-to-book and ROE',type:'Numerical',difficulty:'Intermediate',title:'Relate P/B to ROE',stem:'Assume a stable-growth setting with ROE of 15%, required return on equity of 10%, and growth of 4%. Using the fundamental relationship, what is the justified P/B?',options:[{key:'A',text:'1.50×'},{key:'B',text:'1.83×'},{key:'C',text:'2.50×'}],correct:'B',explain:{intuition:'Book value is more valuable when the company earns more on equity than shareholders require. The excess return (ROE − r) interacts with growth and the required-return-growth spread.',steps:['For stable assumptions, P/B = (ROE − g) / (r − g).','Numerator: 15% − 4% = 11%. Denominator: 10% − 4% = 6%.','11% / 6% = 1.8333, approximately 1.83×.'],formula:'Justified P/B = (ROE − g) / (r − g), under the stated stable-growth assumptions.',rationales:[{key:'A',text:'1.50× is ROE divided by the required return and ignores the growth terms in this relationship.'},{key:'B',text:'Correct: (15% − 4%) / (10% − 4%) = 1.83×.'},{key:'C',text:'2.50× is ROE / (r − g) and mixes an inconsistent numerator with the denominator.'}],trap:'Know which P/B formula assumptions are being used; do not substitute a P/E or ROE ratio by memory.',memory:'P/B rises when sustainable ROE supports returns above the cost of equity.',transfer:'If ROE is 12%, r 9%, and g 3%, P/B = (12−3)/(9−3) = 1.50×.'}},
 {id:'q7',module:'m4',topic:'Enterprise-value multiples',type:'Numerical',difficulty:'Core',title:'Compute EV/EBITDA',stem:'A company has enterprise value of $1.2 billion and annual EBITDA of $150 million. What is its EV/EBITDA multiple?',options:[{key:'A',text:'6.0×'},{key:'B',text:'8.0×'},{key:'C',text:'12.5×'}],correct:'B',explain:{intuition:'The multiple tells you how many dollars of enterprise value investors assign to each dollar of EBITDA. Put both quantities in the same currency units.',steps:['Convert $1.2 billion to $1,200 million.','Divide enterprise value by EBITDA: $1,200 million / $150 million = 8.0×.','Interpret it as enterprise value equal to eight times annual EBITDA.'],formula:'EV/EBITDA = enterprise value ÷ EBITDA',rationales:[{key:'A',text:'6× would correspond to EV of $900 million at the stated EBITDA.'},{key:'B',text:'Correct: $1,200m / $150m = 8×.'},{key:'C',text:'12.5× reverses or mismatches the amounts/units; the ratio should be value divided by EBITDA.'}],trap:'Do not divide equity market capitalization by EBITDA and label it EV/EBITDA. EV and EBITDA must align across capital providers.',memory:'EV numerator, operating denominator; normalize units first.',transfer:'If EV rises to $1.35 billion while EBITDA remains $150 million, the multiple becomes 9.0×.'}},
 {id:'q8',module:'m5',topic:'Residual income',type:'Numerical',difficulty:'Core',title:'Calculate residual income',stem:'A company reports net income of $18 million. Beginning common shareholders’ equity is $120 million and the required return on equity is 10%. What is residual income for the period?',options:[{key:'A',text:'$6 million'},{key:'B',text:'$12 million'},{key:'C',text:'$18 million'}],correct:'A',explain:{intuition:'Accounting profit is not the same as economic profit. Equity capital has an opportunity cost even though that cost is not recorded as an expense on the income statement.',steps:['Calculate the equity charge: 10% × $120m = $12m.','Subtract the equity charge from net income: $18m − $12m = $6m.','Positive residual income means earnings exceeded the required return on beginning equity.'],formula:'Residual income = net income − (required return on equity × beginning book value of equity)',rationales:[{key:'A',text:'Correct: $18m minus the $12m equity charge equals $6m.'},{key:'B',text:'$12m is the equity charge, not residual income.'},{key:'C',text:'$18m is net income before charging for the shareholders’ required return.'}],trap:'Use beginning book value for the period’s equity charge in the standard formulation.',memory:'Residual income = reported earnings minus the investor’s opportunity cost.',transfer:'If NI were $10m, beginning equity $80m, and r 9%, residual income would be $2.8m.'}},
 {id:'q9',module:'m5',topic:'Clean-surplus accounting',type:'Conceptual',difficulty:'Intermediate',title:'Recognize the clean-surplus relationship',stem:'Which relationship describes clean-surplus accounting for common shareholders’ equity, in its basic form?',options:[{key:'A',text:'Ending book value = beginning book value + net income − dividends'},{key:'B',text:'Ending book value = beginning book value + dividends − net income'},{key:'C',text:'Ending book value = market value + net income'}],correct:'A',explain:{intuition:'Clean surplus connects changes in book equity to earnings and transactions with common shareholders. It matters because residual-income models rely on a coherent relationship between earnings, dividends, and book value.',steps:['Start with beginning book value of equity.','Add the period’s net income because it increases retained equity.','Subtract dividends paid to common shareholders because distributions reduce equity.','Items that affect equity outside net income may require special reconciliation.'],formula:'BVE(end) = BVE(begin) + NI − dividends',rationales:[{key:'A',text:'Correct. This is the basic clean-surplus relation.'},{key:'B',text:'This reverses the signs: earnings generally increase retained equity and dividends reduce it.'},{key:'C',text:'Market value is not the balance-sheet roll-forward variable; book equity changes through accounting earnings and shareholder transactions.'}],trap:'Other comprehensive income and certain direct-to-equity items can make the simple relation incomplete in practice.',memory:'Earnings stay in equity; dividends leave equity.',transfer:'If beginning equity is $100m, NI $15m, and dividends $4m, ending equity under the simple relation is $111m.'}},
 {id:'q10',module:'m6',topic:'Earnings normalization',type:'Conceptual',difficulty:'Intermediate',title:'Normalize an owner-specific expense',stem:'A private company’s reported earnings include an unusually large legal settlement that is documented as non-recurring and unrelated to normal operations. What is the most appropriate valuation treatment?',options:[{key:'A',text:'Automatically add back every legal expense, recurring or not'},{key:'B',text:'Consider adding back the documented non-recurring settlement when estimating maintainable earnings'},{key:'C',text:'Ignore the item because private-company earnings cannot be normalized'}],correct:'B',explain:{intuition:'Valuation should reflect maintainable economic performance, not an unexamined accounting snapshot. A one-off expense may reduce reported earnings without representing the future cost of operating the business.',steps:['Establish the nature, amount, and documentation of the settlement.','Assess whether it is genuinely non-recurring and unrelated to normal operations.','If the evidence supports that conclusion, adjust maintainable earnings and disclose the judgment.','Do not add back costs that the business is likely to incur again.'],formula:'Normalized earnings = reported earnings + supported non-recurring expenses − supported non-recurring gains ± justified owner/related-party adjustments',rationales:[{key:'A',text:'Incorrect. A recurring legal/compliance cost is part of maintainable operating performance and should not be removed merely because it is a legal expense.'},{key:'B',text:'Correct. The one-off adjustment is supported if facts establish it is non-recurring and not necessary to ongoing operations.'},{key:'C',text:'Incorrect. Normalization is a central consideration in private-company valuation, but each adjustment needs evidence.'}],trap:'“One-time” labels from management are not proof; check evidence and replacement costs.',memory:'Normalize to repeatable economics—not to the highest plausible earnings.',transfer:'If the owner’s compensation is below market, a normalized earnings estimate may need to subtract the additional cost of hiring a market-rate replacement.'}},
 {id:'q11',module:'m6',topic:'Control and marketability discounts',type:'Conceptual',difficulty:'Intermediate',title:'Distinguish two private-company discounts',stem:'An investor owns a minority interest that cannot readily be sold because there is no active market. The investor also lacks the ability to direct operating or financing decisions. Which statement is most accurate?',options:[{key:'A',text:'Lack of marketability relates to saleability; lack of control relates to decision-making rights'},{key:'B',text:'Both discounts measure exactly the same risk and must always be identical'},{key:'C',text:'Lack of control applies only to debt securities'}],correct:'A',explain:{intuition:'Liquidity and control are different attributes. An interest can be difficult to sell, and it can also offer little ability to influence the company. The valuation adjustment must match the rights and facts of the specific interest.',steps:['Identify whether the interest is difficult to convert to cash or sell at fair value: marketability.','Identify whether the holder can influence distributions, strategy, leadership, or a sale: control.','Avoid double-counting a risk already reflected elsewhere in the valuation.'],formula:'Conceptual distinction: marketability = liquidity/saleability; control = decision-making power.',rationales:[{key:'A',text:'Correct. The concepts may both be relevant but represent distinct attributes.'},{key:'B',text:'Incorrect. Their economic effects and appropriate magnitude are fact-specific, not automatically equal.'},{key:'C',text:'Incorrect. Control considerations also apply to ownership interests in private companies.'}],trap:'Do not apply a generic discount percentage without a defensible basis and a clear valuation premise.',memory:'Marketability asks “Can I sell it easily?”; control asks “Can I direct it?”',transfer:'A controlling interest in an illiquid private company may have meaningful control rights and still face a marketability concern.'}},
 {id:'q12',module:'m2',topic:'Sustainable growth',type:'Numerical',difficulty:'Core',title:'Calculate sustainable growth',stem:'A company earns an ROE of 16% and retains 40% of earnings. Assuming stable financing and that incremental equity reinvestment earns the stated ROE, what is the sustainable growth rate?',options:[{key:'A',text:'6.4%'},{key:'B',text:'9.6%'},{key:'C',text:'16.0%'}],correct:'A',explain:{intuition:'Growth funded by retained earnings depends on both how much profit the firm earns on equity and how much of that profit it keeps to reinvest.',steps:['Retention ratio b = 40%.','ROE = 16%.','Sustainable growth g = ROE × b = 16% × 40% = 6.4%.'],formula:'g = ROE × retention ratio = ROE × (1 − payout ratio)',rationales:[{key:'A',text:'Correct: 16% × 0.40 = 6.4%.'},{key:'B',text:'9.6% multiplies ROE by the 60% payout ratio, not the retention ratio.'},{key:'C',text:'16% is ROE, not the growth rate. Some earnings are distributed rather than reinvested.'}],trap:'Do not confuse payout ratio with retention ratio; they sum to one in the simple formulation.',memory:'Growth needs both return on reinvested equity and the amount retained.',transfer:'With ROE 12% and retention 25%, sustainable growth is 3%.'}},
 {id:'q13',module:'m3',topic:'Terminal value',type:'Numerical',difficulty:'Intermediate',title:'Calculate stable-growth terminal value',stem:'A firm expects FCFF of $40 million in Year 5. FCFF is expected to grow at 3% annually after Year 5, and WACC is 8%. Using a stable-growth FCFF model, what is terminal value at the end of Year 4?',options:[{key:'A',text:'$800 million'},{key:'B',text:'$824 million'},{key:'C',text:'$1,030 million'}],correct:'A',explain:{intuition:'Terminal value at the end of Year 4 capitalizes the cash flow expected one period later. The numerator is next-period FCFF, and the denominator is WACC minus perpetual growth.',steps:['The terminal value date is the end of Year 4, so the next-period cash flow is FCFF5 = $40 million.','The stated 3% growth applies after Year 5; it does not change the given Year 5 cash flow for this terminal date.','TV4 = FCFF5 / (WACC − g) = $40m / (8% − 3%) = $800 million.'],formula:'TVn = FCFF(n+1) / (WACC − g)',rationales:[{key:'A',text:'Correct. The stated Year 5 cash flow is the next cash flow for a terminal value at the end of Year 4: $40m / (8% − 3%) = $800m.'},{key:'B',text:'Incorrect. $824m would use $41.2m as the numerator, which would place the terminal value one period later than the stated terminal date.'},{key:'C',text:'Incorrect. $1,030m does not apply the 5% capitalization spread correctly.'}],trap:'Align the terminal date and numerator. If the terminal value date changes, so does the relevant next-period cash flow.',memory:'Terminal value date + one period = cash flow in numerator.',transfer:'If FCFF in Year 5 were $50m and WACC 9%, g 4%, TV at end-Year 4 would be $1,000m.'}},
 {id:'q14',module:'m4',topic:'Justified P/B',type:'Numerical',difficulty:'Intermediate',title:'Item set: price-to-book from fundamentals',stem:'Northstar Components has a stable ROE of 14%, an equity required return of 9%, and long-run growth of 4%. Assume the stable-growth P/B relationship applies. What is justified P/B?',vignetteId:'northstar',options:[{key:'A',text:'1.40×'},{key:'B',text:'2.00×'},{key:'C',text:'2.80×'}],correct:'B',explain:{intuition:'The multiple is linked to how much return the business earns on its book equity, relative to the required return, alongside growth assumptions.',steps:['P/B = (ROE − g) / (r − g).','Numerator: 14% − 4% = 10%; denominator: 9% − 4% = 5%.','10% / 5% = 2.00×.'],formula:'P/B = (ROE − g) / (r − g)',rationales:[{key:'A',text:'1.40× does not reflect the stated 5% spread and 10% numerator.'},{key:'B',text:'Correct: 10% / 5% = 2.00×.'},{key:'C',text:'2.80× equals ROE divided by the spread, which is not the stated relationship.'}],trap:'Be consistent about stable-growth assumptions and the selected P/B formula.',memory:'Use ROE minus growth above; required return minus growth below.',transfer:'If ROE is 13%, r 10%, g 4%, justified P/B is 1.50×.'}},
 {id:'q15',module:'m4',topic:'Justified leading P/E',type:'Numerical',difficulty:'Intermediate',title:'Item set: justified leading P/E',stem:'Using Northstar Components’ payout ratio of 40%, required return of 9%, and perpetual growth of 4%, estimate the justified leading P/E.',vignetteId:'northstar',options:[{key:'A',text:'8.00×'},{key:'B',text:'10.00×'},{key:'C',text:'13.33×'}],correct:'A',explain:{intuition:'The stable leading P/E reflects the share of earnings paid out relative to the spread between required return and growth.',steps:['Payout ratio = 40%.','Required-return-growth spread = 9% − 4% = 5%.','Leading P/E = 0.40 / 0.05 = 8.00×.'],formula:'Justified leading P/E = payout ratio / (r − g)',rationales:[{key:'A',text:'Correct: 40% divided by 5% equals 8×.'},{key:'B',text:'10× would require a 4% spread at the stated payout.'},{key:'C',text:'13.33× uses a spread of 3%, inconsistent with the stated return and growth.'}],trap:'Use the payout ratio for P/E and keep return and growth in the same percentage units.',memory:'Payout divided by spread.',transfer:'With payout 30%, r 9%, and g 3%, justified leading P/E is 5×.'}},
 {id:'q16',module:'m4',topic:'EV/EBITDA and capital structure',type:'Conceptual',difficulty:'Intermediate',title:'Item set: interpret EV/EBITDA',stem:'Northstar trades at an EV/EBITDA multiple of 8×, while a close peer trades at 6×. Before concluding Northstar is overvalued, which is the best next step?',vignetteId:'northstar',options:[{key:'A',text:'Conclude it is overvalued because its multiple is higher'},{key:'B',text:'Compare growth, profitability, risk, accounting and capital intensity, then test whether the premium is justified'},{key:'C',text:'Use the peer’s multiple without any adjustments because EBITDA is capital-structure neutral'}],correct:'B',explain:{intuition:'Multiples condense valuation into a ratio, but they do not remove differences in business economics. A higher multiple can be rational when expected growth or quality is higher, or unjustified when risk and cash reinvestment are overlooked.',steps:['Check whether EV and EBITDA are defined consistently for both firms.','Compare growth, margins, risk, accounting policies, leases, working capital, and capital expenditures.','Assess whether any observed premium is supported by fundamentals and test sensitivity.'],formula:'Implied EV = selected EV/EBITDA multiple × comparable EBITDA',rationales:[{key:'A',text:'A higher multiple alone is not enough to infer overvaluation; fundamentals and comparability matter.'},{key:'B',text:'Correct. Establish comparability and explain the premium before drawing a conclusion.'},{key:'C',text:'Capital-structure neutrality does not make EBITDA a cash flow or eliminate operating, accounting, and growth differences.'}],trap:'EBITDA excludes taxes, capital expenditure, and working capital, so it is not free cash flow.',memory:'A comparable multiple is a starting point; comparability is the work.',transfer:'A company with higher growth but much higher capital needs might not deserve the same EV/EBITDA premium as a capital-light peer.'}}
,
{id:'q17',module:'m3',topic:'FCFF from net income',sourceLabel:'Curriculum',type:'Numerical',difficulty:'Core',title:'Supplemental: build FCFF from earnings',vignetteId:'ridgeway-cashflow',vignetteTitle:'Ridgeway Components',vignetteSummary:'A fictional industrial supplier is being valued from operating cash flow and financing data.',stem:'Ridgeway reports net income of $120 million, depreciation and other non-cash charges of $18 million, interest expense of $10 million, a tax rate of 30%, capital expenditure of $32 million, and an increase in operating working capital of $6 million. Estimate FCFF.',options:[{key:'A',text:'$95 million'},{key:'B',text:'$107 million'},{key:'C',text:'$113 million'}],correct:'B',explain:{intuition:'FCFF is available to both debt and equity capital providers. Starting from net income, add back non-cash charges and after-tax interest, then deduct operating investment.',steps:['Add back non-cash charges: $120m + $18m = $138m.','Add back interest after tax: $10m × (1 − 30%) = $7m.','Deduct capital expenditure and working-capital investment: $138m + $7m − $32m − $6m = $107m.'],formula:'FCFF = NI + NCC + Interest × (1 − T) − FCInv − WCInv',rationales:[{key:'A',text:'This is too low; it typically results from deducting too much interest or investment.'},{key:'B',text:'Correct: $120m + $18m + $7m − $32m − $6m = $107m.'},{key:'C',text:'This overstates cash flow by $6m, the required working-capital investment.'}],trap:'Use after-tax interest, not pre-tax interest, when the bridge starts with net income.',memory:'Net income + non-cash charges + after-tax interest − reinvestment.',transfer:'If working-capital investment increased to $9m, FCFF would fall to $104m.'}},
{id:'q18',module:'m3',topic:'FCFE and net borrowing',sourceLabel:'Curriculum',type:'Numerical',difficulty:'Core',title:'Supplemental: convert FCFF into FCFE',vignetteId:'ridgeway-cashflow',vignetteTitle:'Ridgeway Components',vignetteSummary:'A fictional industrial supplier is being valued from operating cash flow and financing data.',stem:'For Ridgeway, assume FCFF is $107 million, after-tax interest is $7 million, and debt principal repaid exceeds new debt issued by $12 million. What is FCFE?',options:[{key:'A',text:'$88 million'},{key:'B',text:'$102 million'},{key:'C',text:'$126 million'}],correct:'A',explain:{intuition:'FCFE is the cash flow left for common equity after debt-holder costs and net financing flows are included.',steps:['Start with FCFF of $107m.','Subtract after-tax interest of $7m: $100m.','Net borrowing is −$12m because repayments exceed new issuance: FCFE = $100m − $12m = $88m.'],formula:'FCFE = FCFF − Interest × (1 − T) + Net borrowing',rationales:[{key:'A',text:'Correct: $107m − $7m + (−$12m) = $88m.'},{key:'B',text:'This subtracts interest but misses the net debt repayment.'},{key:'C',text:'This gives debt repayment the wrong sign and overstates the cash available to equity.'}],trap:'Net borrowing is debt issued minus debt repaid. A net repayment is negative.',memory:'Debt issuance can increase FCFE; debt repayment can reduce it.',transfer:'If Ridgeway instead issued $4m more debt than it repaid, FCFE would be $104m.'}},
{id:'q19',module:'m3',topic:'Selecting FCFF or FCFE',sourceLabel:'Curriculum',type:'Conceptual',difficulty:'Intermediate',title:'Supplemental: value a business with changing leverage',vignetteId:'ridgeway-cashflow',vignetteTitle:'Ridgeway Components',vignetteSummary:'A fictional industrial supplier is being valued from operating cash flow and financing data.',stem:'Ridgeway plans a major debt repayment followed by a new acquisition financed with debt. Its capital structure is expected to change materially during the forecast. Which approach is generally the cleaner starting point for valuing operations?',options:[{key:'A',text:'FCFE discounted at a fixed cost of equity, regardless of financing changes'},{key:'B',text:'Dividend discount valuation, because dividends are cash paid to shareholders'},{key:'C',text:'FCFF discounted at WACC consistent with the valuation assumptions, then bridge enterprise value to equity value'}],correct:'C',explain:{intuition:'FCFE is directly affected by borrowing and repayment choices. When leverage changes substantially, FCFF helps separate operating value from financing effects.',steps:['Forecast operating cash flows available to all capital providers.','Discount FCFF using a WACC consistent with the assumed or target capital structure.','Subtract debt-like claims and add non-operating assets as appropriate to derive equity value.'],formula:'Enterprise value = PV(FCFF discounted at WACC); Equity value = EV + non-operating assets − debt-like claims',rationales:[{key:'A',text:'Changing leverage affects FCFE and can also alter the required return on equity.'},{key:'B',text:'Dividends can differ from the company’s capacity to distribute cash and may not reflect the control value.'},{key:'C',text:'Correct. FCFF separates operating performance from financing flows, provided the discount-rate assumptions are coherent.'}],trap:'The choice is not absolute: a FCFE model can work if financing is explicitly forecast. The main risk is inconsistent financing assumptions.',memory:'Unstable leverage often makes FCFF a clearer operating-value framework.',transfer:'If debt issuance, repayment, and target leverage can be forecast reliably, a FCFE model may also be defensible.'}},
{id:'q20',module:'m2',topic:'Gordon growth assumptions',sourceLabel:'Curriculum',type:'Conceptual',difficulty:'Core',title:'Supplemental: identify an invalid Gordon model',stem:'A share is being valued with a constant-growth dividend model. The required return is 7%, while the analyst assumes dividends grow at 8% forever. What is the most accurate conclusion?',options:[{key:'A',text:'The stable-growth model is not valid under these assumptions because growth is not below the required return'},{key:'B',text:'The share value is zero because the discount rate is positive'},{key:'C',text:'The model is valid if the latest dividend is used instead of the next dividend'}],correct:'A',explain:{intuition:'The Gordon formula capitalizes an infinite stream only when the required return exceeds the perpetual growth rate. If the denominator is zero or negative, the assumptions do not produce a meaningful finite value.',steps:['The capitalization spread is r − g = 7% − 8% = −1%.','Because r is not greater than g, the stable-growth infinite-series condition fails.','Revisit the perpetual growth assumption or use a multistage forecast with a defensible stable terminal period.'],formula:'P0 = D1 / (r − g) requires r > g',rationales:[{key:'A',text:'Correct. A long-run growth assumption above the required return breaks the constant-growth model.'},{key:'B',text:'A positive discount rate does not make value zero; the problem is the relationship between r and g.'},{key:'C',text:'Using D0 instead of D1 would introduce a timing error and would not fix the invalid spread.'}],trap:'Do not fix an impossible perpetual-growth assumption by switching the dividend date.',memory:'For a finite Gordon value, the required return must exceed long-run growth.',transfer:'If r is 9% and stable growth is 4%, the model can be considered, subject to realistic dividend and risk assumptions.'}},
{id:'q21',module:'m2',topic:'Multistage dividend valuation',sourceLabel:'Curriculum',type:'Conceptual',difficulty:'Intermediate',title:'Supplemental: value a temporary special-dividend pattern',stem:'A retailer expects to sell a distribution centre and pay three unusually large special dividends over the following three years. After that, ordinary dividends should resume a stable growth pattern. Which modelling choice best reflects the stated cash-flow pattern?',options:[{key:'A',text:'Use the constant-growth Gordon model for every year without changes'},{key:'B',text:'Explicitly forecast the special dividends and the later stable period in a multistage dividend model or spreadsheet'},{key:'C',text:'Ignore the special dividends because they are not recurring'}],correct:'B',explain:{intuition:'Valuation should follow the timing and amount of expected shareholder distributions. A fixed set of irregular payouts is not naturally represented by one perpetual growth rate.',steps:['Forecast each expected special dividend in the period it is paid.','Forecast ordinary dividends after the special-payment period.','Discount each dividend and any terminal value to the valuation date.'],formula:'P0 = Σ[Dt / (1 + r)^t] + terminal value discounted to today',rationales:[{key:'A',text:'A constant-growth model does not represent a one-off asset sale and a distinct sequence of special payments.'},{key:'B',text:'Correct. An explicit multistage schedule can handle the exact amounts and timing before using a stable terminal assumption.'},{key:'C',text:'Expected non-recurring distributions still belong in value if the proceeds will be paid to shareholders.'}],trap:'Non-recurring does not mean irrelevant; timing and the source of the distribution matter.',memory:'Forecast known irregular cash flows explicitly; use a stable model only for the later steady state.',transfer:'A one-time litigation settlement distributed to shareholders should also be modelled in the period expected.'}},
{id:'q22',module:'m2',topic:'Sustainable growth',sourceLabel:'Curriculum',type:'Numerical',difficulty:'Core',title:'Supplemental: link ROE to retention',stem:'A company has a sustainable ROE of 18% and retains 30% of its earnings. Under stable assumptions, what is its sustainable growth rate?',options:[{key:'A',text:'5.4%'},{key:'B',text:'12.6%'},{key:'C',text:'18.0%'}],correct:'A',explain:{intuition:'Sustainable growth depends on the return earned on retained equity and the share of earnings reinvested rather than paid out.',steps:['Retention ratio is 30%, or 0.30.','Multiply ROE by retention: 18% × 0.30 = 5.4%.','The result assumes stable profitability, leverage, and reinvestment economics.'],formula:'g = ROE × retention ratio = ROE × (1 − payout ratio)',rationales:[{key:'A',text:'Correct: 18% × 30% = 5.4%.'},{key:'B',text:'12.6% multiplies ROE by the 70% payout ratio rather than the retention ratio.'},{key:'C',text:'ROE is not the same as growth; some profits are distributed.'}],trap:'Convert payout into retention before calculating growth.',memory:'Growth = return on reinvested equity × proportion retained.',transfer:'If ROE is 12% and retention is 50%, sustainable growth is 6%.'}},
{id:'q23',module:'m4',topic:'Cyclical P/E and the Molodovsky effect',sourceLabel:'Curriculum',type:'Conceptual',difficulty:'Intermediate',title:'Supplemental: interpret a cyclical company’s P/E',vignetteId:'cycle-multiples',vignetteTitle:'Cyclical Valuation Check',vignetteSummary:'A cyclical producer is assessed across a business cycle; earnings move sharply while the share price adjusts with changing expectations.',stem:'A cyclical producer is near the bottom of its earnings cycle. Its share price has fallen, but reported earnings have fallen even more sharply. Which P/E interpretation is most defensible?',options:[{key:'A',text:'A high P/E proves the shares are overvalued'},{key:'B',text:'A high P/E may reflect temporarily depressed earnings, so normalized through-cycle earnings should be examined'},{key:'C',text:'A high P/E proves its cost of equity is lower than all peers'}],correct:'B',explain:{intuition:'The P/E denominator is earnings, which can be unusually low at the bottom of a cycle. The multiple may rise even without a proportional rise in market value.',steps:['Identify where the company is in the business cycle.','Compare current earnings with normalized or through-cycle earnings.','Reassess the multiple using comparable companies and consistent earnings bases before judging mispricing.'],formula:'P/E = share price ÷ earnings per share',rationales:[{key:'A',text:'A high P/E is not sufficient evidence of overvaluation when earnings are cyclically depressed.'},{key:'B',text:'Correct. Temporarily weak earnings can mechanically inflate P/E, the countercyclical pattern often called the Molodovsky effect.'},{key:'C',text:'P/E reflects growth, risk, payout, accounting and cyclical earnings, not only the cost of equity.'}],trap:'High P/E can occur at the trough; low P/E can occur at the peak when earnings are temporarily elevated.',memory:'Normalize cyclical earnings before comparing multiples.',transfer:'For a commodity producer, compare the current multiple using both spot earnings and a sensible mid-cycle margin assumption.'}},
{id:'q24',module:'m4',topic:'EV/EBITDA comparability',sourceLabel:'Curriculum',type:'Conceptual',difficulty:'Intermediate',title:'Supplemental: assess an EV/EBITDA premium',vignetteId:'cycle-multiples',vignetteTitle:'Cyclical Valuation Check',vignetteSummary:'A cyclical producer is assessed across a business cycle; earnings move sharply while the share price adjusts with changing expectations.',stem:'A company trades at 10× EV/EBITDA and its closest peer trades at 7×. Before calling the first company overvalued, what should the analyst do?',options:[{key:'A',text:'Accept the peer multiple without adjustment because EBITDA is equivalent to free cash flow'},{key:'B',text:'Compare only the companies’ dividend yields'},{key:'C',text:'Assess differences in growth, risk, margins, accounting, capital intensity and working-capital needs before deciding whether the premium is justified'}],correct:'C',explain:{intuition:'Multiples simplify comparison but do not remove differences between businesses. EBITDA omits taxes, capital spending and working-capital investment.',steps:['Ensure enterprise value and EBITDA are defined consistently.','Compare growth, profitability, business risk, accounting, leases and reinvestment needs.','Decide whether the higher multiple is supported and test the conclusion under alternative assumptions.'],formula:'Implied EV = chosen EV/EBITDA multiple × EBITDA',rationales:[{key:'A',text:'EBITDA is not free cash flow and can materially overstate cash available when capex or working capital is high.'},{key:'B',text:'Dividend yield reflects payout policy and does not by itself explain an enterprise-value multiple.'},{key:'C',text:'Correct. A premium is meaningful only after checking the operating and accounting fundamentals that drive comparability.'}],trap:'Enterprise-value multiples are not immune to differences in accounting or capital intensity.',memory:'Compare like with like, then explain any premium or discount.',transfer:'A capital-intensive company may deserve a lower EV/EBITDA multiple than an asset-light peer with similar EBITDA growth.'}},
{id:'q25',module:'m5',topic:'Residual income',sourceLabel:'Curriculum',type:'Numerical',difficulty:'Core',title:'Supplemental: calculate economic profit to equity',vignetteId:'residual-income-review',vignetteTitle:'Residual Income Review',vignetteSummary:'A fictional company is evaluated using book equity, accounting earnings and the cost of equity capital.',stem:'A company reports net income of $32 million. Beginning common shareholders’ equity is $250 million and the required return on equity is 9%. What is residual income for the year?',options:[{key:'A',text:'$9.5 million'},{key:'B',text:'$22.5 million'},{key:'C',text:'$32.0 million'}],correct:'A',explain:{intuition:'Residual income subtracts the opportunity cost of shareholders’ beginning book equity from accounting net income.',steps:['Equity capital charge = $250m × 9% = $22.5m.','Residual income = $32m − $22.5m = $9.5m.','Positive residual income means earnings exceeded the required return on the equity base.'],formula:'RI = NI − (cost of equity × beginning book value of equity)',rationales:[{key:'A',text:'Correct. Net income exceeds the equity charge by $9.5m.'},{key:'B',text:'$22.5m is the capital charge, not residual income.'},{key:'C',text:'Net income alone does not account for the opportunity cost of equity.'}],trap:'Use the beginning equity balance for the standard period capital charge.',memory:'Residual income is accounting profit after charging for equity capital.',transfer:'If beginning equity were $300m at a 9% required return, the charge would be $27m and RI would be $5m.'}},
{id:'q26',module:'m5',topic:'Residual income and equity value',sourceLabel:'Curriculum',type:'Numerical',difficulty:'Core',title:'Supplemental: derive equity value from residual income',vignetteId:'residual-income-review',vignetteTitle:'Residual Income Review',vignetteSummary:'A fictional company is evaluated using book equity, accounting earnings and the cost of equity capital.',stem:'A company has current book value of common equity of $80 per share. The present value of expected future residual income is estimated at $18 per share. What equity value follows from the residual-income framework?',options:[{key:'A',text:'$62 per share'},{key:'B',text:'$98 per share'},{key:'C',text:'$144 per share'}],correct:'B',explain:{intuition:'The residual-income framework starts with current book value and adds the present value of future earnings in excess of the equity capital charge.',steps:['Begin with current book value per share of $80.','Add present value of expected future residual income of $18.','Estimated value = $80 + $18 = $98 per share.'],formula:'V0 = BVE0 + PV(future residual income)',rationales:[{key:'A',text:'Subtracting residual income would reverse the valuation relationship.'},{key:'B',text:'Correct: book value plus the present value of residual income equals $98.'},{key:'C',text:'This adds unrelated amounts and does not follow the residual-income framework.'}],trap:'This formula requires consistent accounting assumptions and attention to clean-surplus issues.',memory:'Residual-income value = book value today + PV of future excess earnings.',transfer:'If future residual income had a negative present value of $6 per share, value would be $74.'}},
{id:'q27',module:'m5',topic:'Clean-surplus accounting',sourceLabel:'Curriculum',type:'Conceptual',difficulty:'Intermediate',title:'Supplemental: spot a clean-surplus issue',vignetteId:'residual-income-review',vignetteTitle:'Residual Income Review',vignetteSummary:'A fictional company is evaluated using book equity, accounting earnings and the cost of equity capital.',stem:'A company’s book equity increases because of a gain recorded directly in other comprehensive income, outside net income. Why does this matter to a residual-income valuation?',options:[{key:'A',text:'It proves the share price must rise by the same percentage'},{key:'B',text:'It has no effect because residual-income models do not use book equity'},{key:'C',text:'The simple clean-surplus roll-forward may not hold without reconciling equity changes that bypass net income'}],correct:'C',explain:{intuition:'Residual-income models connect book value, net income and distributions. Items that change equity outside net income require reconciliation so the accounting roll-forward remains coherent.',steps:['The simplified relation is ending book equity = beginning equity + net income − dividends.','An OCI item changes equity without appearing in net income.','Reconcile that item or adjust the model inputs before relying on the residual-income forecast.'],formula:'Basic clean surplus: BVE(end) = BVE(begin) + NI − dividends; additional direct-to-equity items require reconciliation.',rationales:[{key:'A',text:'A direct-to-equity accounting entry does not mechanically determine a market-price change.'},{key:'B',text:'Book equity is the starting point in the residual-income framework.'},{key:'C',text:'Correct. Equity changes outside net income can violate the simple clean-surplus relation and affect model consistency.'}],trap:'Check comprehensive income and direct-to-equity transactions instead of assuming every equity change passed through net income.',memory:'Residual income depends on a coherent bridge between earnings and book equity.',transfer:'A prior-period adjustment directly to retained earnings also deserves scrutiny.'}},
{id:'q28',module:'m6',topic:'Private-company earnings normalization',sourceLabel:'Curriculum',type:'Numerical',difficulty:'Intermediate',title:'Supplemental: normalize below-market owner compensation',stem:'A private company reports earnings of $750,000 after paying its owner-manager $90,000. A market-rate replacement manager would cost $160,000, with all else unchanged. What is normalized earnings before any other adjustments?',options:[{key:'A',text:'$680,000'},{key:'B',text:'$750,000'},{key:'C',text:'$820,000'}],correct:'A',explain:{intuition:'Normalized earnings should reflect the cost of operating the company under market conditions, not a below-market cost that depends on the current owner.',steps:['The reported salary is $90,000.','The market replacement salary is $160,000, or $70,000 higher.','Subtract the additional ongoing expense from reported earnings: $750,000 − $70,000 = $680,000.'],formula:'Normalized earnings = reported earnings − incremental expense needed to reflect market-rate operations',rationales:[{key:'A',text:'Correct. A replacement manager costs $70,000 more, so maintainable earnings fall to $680,000.'},{key:'B',text:'Reported earnings retain the benefit of below-market owner compensation.'},{key:'C',text:'Adding the salary difference would move earnings in the wrong direction.'}],trap:'Not every owner expense is an add-back. If a replacement cost is higher, normalized earnings may decrease.',memory:'Normalize the economics the buyer will actually inherit.',transfer:'If the owner’s compensation exceeds market by $40,000 and no replacement cost offsets it, a justified adjustment may increase normalized earnings by $40,000.'}},
{id:'q29',module:'m3',topic:'Model selection and dividend policy',sourceLabel:'Curriculum',type:'Conceptual',difficulty:'Intermediate',title:'Supplemental: value capacity to distribute cash',stem:'An acquisition candidate pays irregular dividends that are much lower than its forecast capacity to generate equity cash flow. The buyer expects to obtain control and change payout policy. Which valuation input is most directly useful?',options:[{key:'A',text:'Only historical dividends, because payout policy cannot change after a transaction'},{key:'B',text:'Forecast free cash flow to equity, with financing and control assumptions made explicit'},{key:'C',text:'The latest book value, without any forecast of future earnings or cash flows'}],correct:'B',explain:{intuition:'Dividends are a board-level distribution choice; they may not represent the business’s economic capacity to deliver cash to shareholders. Control can also change the distribution policy.',steps:['Forecast operating and financing cash flows under the buyer’s control assumptions.','Estimate FCFE available to common equity after reinvestment and net borrowing.','Discount FCFE at the required return on equity or use a consistent enterprise-value approach where appropriate.'],formula:'FCFE = FCFF − after-tax interest + net borrowing',rationales:[{key:'A',text:'Historical payout can understate the economic cash available to a controlling investor.'},{key:'B',text:'Correct. Forecast FCFE can capture the company’s equity cash-generation capacity and explicit financing assumptions.'},{key:'C',text:'Book value alone omits expected future cash flows and profitability.'}],trap:'Control changes the relevant premise, but do not assume all cash can be extracted without considering operations, covenants, taxes and financing.',memory:'Value economic cash capacity, not simply the current dividend decision.',transfer:'For a minority investor in a stable dividend payer, a DDM may still be appropriate.'}},
{id:'q30',module:'m3',topic:'Stable-growth terminal value',sourceLabel:'Curriculum',type:'Numerical',difficulty:'Intermediate',title:'Supplemental: set the terminal-value date correctly',stem:'A valuation uses the end of Year 3 as the terminal date. FCFF expected in Year 4 is $24 million, WACC is 9%, and perpetual FCFF growth is 3%. What is terminal value at the end of Year 3?',options:[{key:'A',text:'$360 million'},{key:'B',text:'$400 million'},{key:'C',text:'$480 million'}],correct:'B',explain:{intuition:'Terminal value at the end of Year 3 uses the next period’s cash flow, Year 4, and capitalizes it by the WACC-growth spread.',steps:['Spread = 9% − 3% = 6%.','Use Year 4 FCFF of $24m because the terminal date is the end of Year 3.','TV3 = $24m / 0.06 = $400m.'],formula:'TVn = FCFF(n+1) / (WACC − g)',rationales:[{key:'A',text:'$360m would use a $21.6m numerator or another inconsistent input.'},{key:'B',text:'Correct. $24m divided by a 6% spread equals $400m.'},{key:'C',text:'$480m would require a 5% spread, not the 6% stated.'}],trap:'Keep terminal date, numerator period and discount rate aligned.',memory:'Terminal date n → numerator cash flow in period n+1.',transfer:'If WACC fell to 8% with growth unchanged, terminal value would rise to $480m.'}},
{id:'q31',module:'m4',topic:'Justified P/B',sourceLabel:'Curriculum',type:'Numerical',difficulty:'Intermediate',title:'Supplemental: calculate a justified price-to-book ratio',stem:'A mature company has ROE of 14%, required return on equity of 10%, and stable growth of 4%. Under the standard stable-growth relationship, what is justified P/B?',options:[{key:'A',text:'1.25×'},{key:'B',text:'1.67×'},{key:'C',text:'2.33×'}],correct:'B',explain:{intuition:'The justified P/B is linked to the spread between sustainable ROE and growth, relative to the spread between required return and growth.',steps:['Numerator = ROE − g = 14% − 4% = 10%.','Denominator = r − g = 10% − 4% = 6%.','P/B = 10% / 6% = 1.6667, approximately 1.67×.'],formula:'Justified P/B = (ROE − g) / (r − g), under stable assumptions',rationales:[{key:'A',text:'1.25× does not follow from the given numerator and denominator.'},{key:'B',text:'Correct. 10% divided by 6% is approximately 1.67×.'},{key:'C',text:'2.33× uses an inconsistent numerator or denominator.'}],trap:'Confirm that the chosen justified P/B formula matches its steady-state assumptions.',memory:'ROE minus growth above; required return minus growth below.',transfer:'If ROE were only 8% while r remained 10% and g 4%, the justified P/B would be below 1.'}},
{id:'q32',module:'m1',topic:'Required return using CAPM',sourceLabel:'Curriculum',type:'Numerical',difficulty:'Core',title:'Supplemental: calculate a CAPM required return',stem:'The risk-free rate is 3.5%, a stock beta is 1.2, and the expected market equity risk premium is 5.0%. What required return does CAPM imply?',options:[{key:'A',text:'8.5%'},{key:'B',text:'9.0%'},{key:'C',text:'9.5%'}],correct:'C',explain:{intuition:'CAPM adds compensation for systematic risk to the risk-free rate. Beta scales the market risk premium.',steps:['Equity risk premium contribution = 1.2 × 5.0% = 6.0%.','Add the risk-free rate: 3.5% + 6.0% = 9.5%.'],formula:'r = Rf + β × ERP',rationales:[{key:'A',text:'8.5% uses a smaller beta-premium contribution.'},{key:'B',text:'9.0% does not equal the stated risk-free rate plus the beta-adjusted premium.'},{key:'C',text:'Correct: 3.5% + 1.2 × 5.0% = 9.5%.'}],trap:'Multiply beta by the equity risk premium, then add the risk-free rate.',memory:'CAPM required return = risk-free rate + beta-adjusted ERP.',transfer:'If beta rose to 1.4 with other inputs unchanged, the required return would be 10.5%.'}},
{id:'q33',module:'m6',topic:'Sum-of-parts valuation',sourceLabel:'Curriculum',vignetteId:'diversified-group',vignetteTitle:'Meridian Holdings · Sum-of-the-parts analysis',vignetteSummary:'Meridian Holdings operates three businesses with different economics and is being valued by aggregating their standalone values.',type:'Numerical',difficulty:'Intermediate',title:'Supplemental: bridge sum-of-parts value to equity',stem:'A diversified company has three business units with estimated enterprise values of $280 million, $350 million and $270 million. It also has $190 million of debt, $25 million of debt-like pension obligations, and $45 million of non-operating cash. What is the sum-of-parts equity value before any holding-company discount?',options:[{key:'A',text:'$605 million'},{key:'B',text:'$730 million'},{key:'C',text:'$900 million'}],correct:'B',explain:{intuition:'A sum-of-parts valuation first aggregates the standalone enterprise values, then reconciles enterprise claims and non-operating assets to common equity.',steps:['Sum the units: $280m + $350m + $270m = $900m enterprise value.','Add non-operating cash of $45m.','Subtract debt of $190m and debt-like pension claims of $25m: $900m + $45m − $190m − $25m = $730m.'],formula:'Equity SOTP = Σ business-unit EV + non-operating assets − debt-like claims',rationales:[{key:'A',text:'This subtracts too much or omits the non-operating cash.'},{key:'B',text:'Correct. The standalone values net of debt-like claims, plus cash, imply $730m.'},{key:'C',text:'$900m is the sum of unit enterprise values before the equity bridge.'}],trap:'Do not subtract financing claims and forget non-operating assets, or double-count items already included in business-unit values.',memory:'Sum unit EVs, add excess assets, subtract debt-like claims.',transfer:'If the holding company has another $20m of surplus cash, equity value would rise to $750m before discounts.'}},
{id:'q34',module:'m1',topic:'Intrinsic value and perceived mispricing',sourceLabel:'SSEI',type:'Conceptual',difficulty:'Intermediate',title:'Supplemental: separate valuation error from market mispricing',stem:'An analyst estimates intrinsic value at $82 per share, the analyst’s estimate of true intrinsic value is $78, and the market price is $70. Which decomposition correctly distinguishes estimation error from true market mispricing?',options:[{key:'A',text:'Valuation error is $8 and true mispricing is $4'},{key:'B',text:'Both valuation error and true mispricing are $12'},{key:'C',text:'The $12 perceived mispricing equals a $4 valuation error plus $8 of true mispricing'}],correct:'C',explain:{intuition:'The observed difference between an analyst estimate and market price can arise from a valuation-estimation error and an actual gap between true value and price.',steps:['Perceived mispricing = analyst estimate − market price = $82 − $70 = $12.','Estimation error = analyst estimate − true value = $82 − $78 = $4.','True mispricing = true value − market price = $78 − $70 = $8; $4 + $8 = $12.'],formula:'Ve − P = (Ve − V) + (V − P)',rationales:[{key:'A',text:'The amounts are reversed: the estimation error is $4 and true mispricing is $8.'},{key:'B',text:'Each component cannot equal the full $12 difference when they sum to that difference.'},{key:'C',text:'Correct. The perceived gap consists of $4 of estimation error and $8 of true mispricing.'}],trap:'Perceived mispricing is not automatically true mispricing; the analyst’s value estimate may be wrong.',memory:'Estimate minus price = estimate error + true value minus price.',transfer:'If the market price rose to $78, true mispricing would be zero even though the analyst estimate remained $82.'}},
{id:'q35',module:'m1',sourceLabel:'Curriculum',topic:'Definitions of value',type:'Conceptual',difficulty:'Core',title:'Supplemental: select the relevant definition of value',stem:'A public-equity analyst estimates a share’s value from forecast distributions and risk. A corporate buyer separately believes the same share is worth more to it because of cost synergies. Which distinction is most accurate?',options:[{key:'A',text:'The analyst is estimating intrinsic value; the buyer may have a higher investment value'},{key:'B',text:'Both estimates must equal the current market price'},{key:'C',text:'The buyer’s synergy value is always fair market value'}],correct:'A',explain:{intuition:'The purpose and perspective of the valuation determine the relevant value concept.',steps:['Intrinsic value reflects the asset’s investment characteristics under an analyst’s assumptions.','Investment value reflects value to a specific investor, including investor-specific synergies.','Fair market value uses an assumed transaction between informed, willing parties without compulsion.'],formula:'Keep valuation premise, perspective and assumptions explicit.',rationales:[{key:'A',text:'Correct. Investor-specific synergies can make investment value differ from intrinsic or fair market value.'},{key:'B',text:'Valuation exists partly because a reasoned estimate can differ from market price.'},{key:'C',text:'Synergy value to a specific buyer is not automatically fair market value.'}],trap:'Do not treat intrinsic value, fair market value and investment value as interchangeable.',memory:'Intrinsic = asset-focused estimate; investment = buyer-specific value; fair market = transaction premise.',transfer:'A tax valuation or owner buy-sell agreement may require a different definition of value than a public-stock analysis.'}},
{id:'q36',module:'m1',sourceLabel:'Curriculum',topic:'Sum-of-the-parts valuation',type:'Numerical',difficulty:'Intermediate',title:'Supplemental: calculate sum-of-the-parts equity value',vignetteId:'diversified-group',vignetteTitle:'Meridian Holdings · Sum-of-the-parts analysis',vignetteSummary:'Meridian Holdings operates three businesses with different economics and is being valued by aggregating their standalone values.',stem:'The three operating units have enterprise values of $350 million, $210 million and $160 million. The parent has $20 million of excess cash, $85 million of debt and $15 million of debt-like pension obligations. Before any holding-company discount, what is equity value?',options:[{key:'A',text:'$620 million'},{key:'B',text:'$640 million'},{key:'C',text:'$720 million'}],correct:'B',explain:{intuition:'SOTP first aggregates operating-unit enterprise values, then reconciles assets and claims at the parent level.',steps:['Operating enterprise value = $350m + $210m + $160m = $720m.','Add excess cash: $720m + $20m = $740m.','Subtract debt and debt-like pension claims: $740m − $85m − $15m = $640m.'],formula:'SOTP equity value = sum of unit EVs + non-operating assets − debt-like claims',rationales:[{key:'A',text:'$620m fails to net the items correctly.'},{key:'B',text:'Correct: $720m + $20m − $85m − $15m = $640m.'},{key:'C',text:'$720m is the sum of operating EVs before the parent-level equity bridge.'}],trap:'Do not subtract debt twice if it has already been allocated within unit values.',memory:'Aggregate operating value first; then add assets and subtract claims.',transfer:'A conglomerate discount, if justified, is a separate adjustment after a defensible SOTP estimate.'}},
{id:'q37',module:'m2',sourceLabel:'Curriculum',topic:'Implied dividend growth',type:'Numerical',difficulty:'Intermediate',title:'Supplemental: solve for market-implied growth',stem:'A share trades at $44. The most recent dividend was $2.00 per share, and the required return is 9%. Assuming the Gordon growth model is appropriate, what perpetual dividend growth rate is implied by the price?',options:[{key:'A',text:'3.5%'},{key:'B',text:'4.3%'},{key:'C',text:'5.0%'}],correct:'B',explain:{intuition:'A valuation model can be rearranged to infer the fundamental assumption embedded in a market price.',steps:['Start from P0 = D0(1+g)/(r−g).','Substitute: 44 = 2(1+g)/(0.09−g).','Solve: 44(0.09−g)=2(1+g), so 3.96−44g=2+2g and g=1.96/46=4.26%, approximately 4.3%.'],formula:'P0 = D0(1+g)/(r−g), requiring r > g',rationales:[{key:'A',text:'3.5% produces a lower modeled value than the given price under the other assumptions.'},{key:'B',text:'Correct. The implied growth rate is about 4.26%.'},{key:'C',text:'5.0% is higher than the rate implied by solving the stated equation.'}],trap:'Use the next dividend and keep growth inside both D1 and the capitalization spread when solving algebraically.',memory:'Market price can be reverse-engineered into an implied growth rate or required return.',transfer:'Compare implied growth with historical performance, industry growth and a defensible long-run economic anchor.'}},
{id:'q38',module:'m2',sourceLabel:'Curriculum',topic:'H-model',type:'Numerical',difficulty:'Intermediate',title:'Supplemental: value a gradual dividend-growth fade',stem:'Use the H-model approximation to value a share with D0 = $1.80, initial growth gs = 12%, stable growth gl = 4%, a five-year transition, and required return r = 10%.',options:[{key:'A',text:'$31.20'},{key:'B',text:'$37.20'},{key:'C',text:'$45.00'}],correct:'B',explain:{intuition:'The H-model approximates a gradual linear decline in growth from an initially high rate to a stable rate.',steps:['H is half the transition period: 5/2 = 2.5.','Apply P0 = D0 × [1 + gl + H(gs−gl)]/(r−gl).','Numerator = 1.80 × [1.04 + 2.5(0.12−0.04)] = 1.80 × 1.24 = $2.232.','Denominator = 0.10−0.04 = 0.06; value = $2.232/0.06 = $37.20.'],formula:'P0 ≈ D0[1 + gl + H(gs−gl)]/(r−gl)',rationales:[{key:'A',text:'$31.20 omits part of the above-stable growth contribution.'},{key:'B',text:'Correct. The H-model estimate is $37.20 per share.'},{key:'C',text:'$45.00 overstates value relative to the formula’s numerator and 6% spread.'}],trap:'H is half the transition length and the formula uses D0 as written; do not use the next dividend twice.',memory:'Use H for a gradual fade, then capitalize with r minus stable growth.',transfer:'A three-stage model is preferable if the growth path is not approximately linear.'}},
{id:'q39',module:'m2',sourceLabel:'Curriculum',topic:'Share repurchases and payout',type:'Conceptual',difficulty:'Intermediate',title:'Supplemental: include repurchases in payout analysis',stem:'A company’s dividend per share is nearly unchanged, but it regularly repurchases shares and its shares outstanding decline. An analyst uses dividend growth alone to infer total shareholder payout. What is the key concern?',options:[{key:'A',text:'Dividend-only analysis may miss repurchases that also return capital to shareholders'},{key:'B',text:'Repurchases always reduce total shareholder return to zero'},{key:'C',text:'Repurchases have no effect on per-share metrics'}],correct:'A',explain:{intuition:'Dividend policy is only one way companies distribute cash. Repurchases can affect total payout and share counts.',steps:['Identify dividends paid to shareholders.','Add share repurchases when analyzing total distributions, considering any offsetting new issuance.','Forecast earnings per share and dividends consistently with future shares outstanding and payout policy.'],formula:'Total payout analysis considers dividends and net share repurchases.',rationales:[{key:'A',text:'Correct. Repurchases can be material even when dividend per share is stable.'},{key:'B',text:'Repurchases do not mechanically eliminate shareholder return.'},{key:'C',text:'A lower share count can affect per-share metrics and ownership percentages.'}],trap:'Do not confuse company cash distribution with the amount reported as dividend per share.',memory:'Track dividends, repurchases and shares outstanding together.',transfer:'Stable dividends plus net repurchases can imply a different total payout trend than dividend growth alone.'}},
{id:'q40',module:'m3',sourceLabel:'Curriculum',topic:'FCFF from EBITDA',type:'Numerical',difficulty:'Core',title:'Supplemental: derive FCFF from EBITDA',stem:'A business reports EBITDA of $150 million, depreciation and amortization of $20 million, a tax rate of 25%, capital expenditure of $32 million, and an increase in operating working capital of $6 million. Estimate FCFF assuming no other adjustments.',options:[{key:'A',text:'$79.5 million'},{key:'B',text:'$97.5 million'},{key:'C',text:'$112.0 million'}],correct:'A',explain:{intuition:'EBITDA is not free cash flow. Adjust it for operating taxes and reinvestment in fixed assets and working capital.',steps:['EBIT = EBITDA − D&A = $150m − $20m = $130m.','NOPAT = EBIT(1−T) = $130m × 75% = $97.5m.','Add back D&A and subtract reinvestment: FCFF = $97.5m + $20m − $32m − $6m = $79.5m.'],formula:'FCFF = EBIT(1−T) + D&A − capex − increase in operating working capital',rationales:[{key:'A',text:'Correct. FCFF is $79.5m after taxes and reinvestment.'},{key:'B',text:'$97.5m is NOPAT before adding back D&A and subtracting capex and working capital.'},{key:'C',text:'This fails to account for the full reinvestment requirement.'}],trap:'EBITDA excludes taxes, capital expenditures and working capital; it is not cash available to investors.',memory:'NOPAT + non-cash charges − investment.',transfer:'Higher capex reduces FCFF even when EBITDA is unchanged.'}},
{id:'q41',module:'m3',sourceLabel:'Curriculum',topic:'Terminal value timing',type:'Numerical',difficulty:'Intermediate',title:'Supplemental: align terminal value and next-period cash flow',stem:'The terminal value date is the end of Year 3. FCFF in Year 4 is forecast at $24 million, WACC is 9%, and perpetual growth is 3%. What is terminal value at the end of Year 3?',options:[{key:'A',text:'$360 million'},{key:'B',text:'$400 million'},{key:'C',text:'$480 million'}],correct:'B',explain:{intuition:'A terminal value at time n capitalizes cash flow in time n+1.',steps:['Capitalization spread = WACC − g = 9% − 3% = 6%.','Use Year 4 FCFF because the terminal date is the end of Year 3.','TV3 = $24m / 0.06 = $400m.'],formula:'TVn = FCFF(n+1)/(WACC−g)',rationales:[{key:'A',text:'$360m does not use the stated Year 4 cash flow with a 6% spread.'},{key:'B',text:'Correct. $24m divided by 6% equals $400m.'},{key:'C',text:'$480m would result from a different spread or cash flow.'}],trap:'Terminal-date alignment is a frequent source of off-by-one errors.',memory:'At terminal date n, capitalize period n+1 cash flow.',transfer:'If WACC drops and growth is unchanged, terminal value rises.'}},
{id:'q42',module:'m3',sourceLabel:'Curriculum',topic:'FCFE from FCFF',type:'Numerical',difficulty:'Core',title:'Supplemental: include net debt repayment in FCFE',stem:'A company has FCFF of $88 million, after-tax interest expense of $9 million, and debt repayments exceed new borrowing by $5 million. What is FCFE?',options:[{key:'A',text:'$74 million'},{key:'B',text:'$84 million'},{key:'C',text:'$102 million'}],correct:'A',explain:{intuition:'FCFE reflects financing flows after interest and net borrowing are accounted for.',steps:['Start with FCFF of $88m.','Subtract after-tax interest of $9m: $79m.','Net borrowing is −$5m; FCFE = $79m − $5m = $74m.'],formula:'FCFE = FCFF − after-tax interest + net borrowing',rationales:[{key:'A',text:'Correct. Net repayment is negative borrowing, so $88m−$9m−$5m=$74m.'},{key:'B',text:'This subtracts interest but omits the net debt repayment.'},{key:'C',text:'This adds financing flows with an incorrect sign.'}],trap:'Net borrowing means debt issued minus debt repaid.',memory:'Repayments exceeding issuance reduce FCFE.',transfer:'Net issuance of $5m instead would give FCFE of $84m.'}},
{id:'q43',module:'m3',sourceLabel:'Curriculum',topic:'Enterprise value to equity value',type:'Numerical',difficulty:'Intermediate',title:'Supplemental: bridge enterprise value to equity value',stem:'A company has enterprise value of $980 million, excess cash of $35 million, debt of $245 million, preferred stock of $10 million and non-controlling interests of $20 million. Estimate common-equity value.',options:[{key:'A',text:'$700 million'},{key:'B',text:'$740 million'},{key:'C',text:'$770 million'}],correct:'B',explain:{intuition:'Enterprise value represents the operating business for all capital providers; equity value is found after reconciling other assets and claims.',steps:['Add excess cash: $980m + $35m = $1,015m.','Subtract debt, preferred stock and non-controlling interests: $1,015m − $245m − $10m − $20m = $740m.'],formula:'Common equity value = EV + non-operating assets − debt-like and senior claims',rationales:[{key:'A',text:'$700m subtracts too much or fails to add excess cash correctly.'},{key:'B',text:'Correct. The bridge implies $740m of common-equity value.'},{key:'C',text:'$770m does not fully reconcile the senior and non-controlling claims.'}],trap:'Use consistent definitions of EV, debt, cash and non-controlling interests.',memory:'Start with EV, add assets and subtract senior claims.',transfer:'If cash is operating cash required by the business, do not automatically treat it all as excess.'}},
{id:'q44',module:'m3',sourceLabel:'Curriculum',topic:'Sensitivity analysis and ESG',type:'Conceptual',difficulty:'Intermediate',title:'Supplemental: reflect a material ESG risk in cash-flow valuation',stem:'A company faces a credible future environmental rule that will require recurring compliance spending and increase closure-related capital expenditure. How should an analyst reflect the risk in an FCFF model?',options:[{key:'A',text:'Add an arbitrary ESG discount to value without changing model assumptions'},{key:'B',text:'Ignore it until the expense appears in historical statements'},{key:'C',text:'Model expected operating costs and capital spending through explicit scenarios and appropriate risk assumptions'}],correct:'C',explain:{intuition:'Material ESG factors belong in valuation when they change expected economics or risk; they should be tied to cash-flow or discount-rate assumptions.',steps:['Estimate the timing and magnitude of compliance costs and capital spending.','Build scenarios for regulatory timing, required spending and operational response.','Test valuation sensitivity and avoid counting the same risk in both cash flows and discount rate.'],formula:'Valuation changes through expected cash flows, discount rates or both—but avoid double-counting.',rationales:[{key:'A',text:'An arbitrary discount is not transparent and can duplicate risks already reflected in the model.'},{key:'B',text:'Forward-looking valuation should consider material expected future costs.'},{key:'C',text:'Correct. Translate the factor into defensible cash-flow assumptions and scenario sensitivity.'}],trap:'ESG is not a standalone valuation adjustment; identify the causal economic channel.',memory:'Explain how the risk changes cash flow, required return or both.',transfer:'A potential labor shortage may affect capacity, wages, delivery reliability and forecast margins.'}},
{id:'q45',module:'m4',sourceLabel:'Curriculum',topic:'Price-to-sales',type:'Numerical',difficulty:'Core',title:'Supplemental: link P/S to P/E and net margin',vignetteId:'harbor-multiples',vignetteTitle:'Harbor Consumer Products · Multiple selection and accounting quality',vignetteSummary:'Harbor is a fictional consumer-products business. Analysts are comparing profit-based and sales-based multiples, with attention to accounting quality and peer comparability.',stem:'A company’s share price is $80 and sales per share are $25. Its net profit margin is 8%. Using consistent per-share definitions, what is the P/S ratio?',options:[{key:'A',text:'2.5×'},{key:'B',text:'3.2×'},{key:'C',text:'4.0×'}],correct:'B',explain:{intuition:'P/S can be related to P/E through the earnings margin when both ratios use consistent per-share definitions.',steps:['EPS = sales per share × net margin = $25 × 8% = $2.00.','P/E = $80 / $2.00 = 40×.','P/S = price / sales per share = $80 / $25 = 3.2×, equivalent to 40× × 8%.'],formula:'P/S = P/E × net profit margin, under consistent definitions',rationales:[{key:'A',text:'2.5× does not match the stated share price and sales per share.'},{key:'B',text:'Correct. $80 / $25 = 3.2×.'},{key:'C',text:'4.0× would require a different price or sales figure.'}],trap:'A high P/S can reflect high margins or high expectations, not simply high sales growth.',memory:'P/S depends on P/E and margin earned on each sales dollar.',transfer:'If net margin falls while P/E remains unchanged, justified P/S falls.'}},
{id:'q46',module:'m4',sourceLabel:'Curriculum',topic:'Harmonic mean of multiples',type:'Numerical',difficulty:'Intermediate',title:'Supplemental: calculate the harmonic mean multiple',vignetteId:'harbor-multiples',vignetteTitle:'Harbor Consumer Products · Multiple selection and accounting quality',vignetteSummary:'Harbor is a fictional consumer-products business. Analysts are comparing profit-based and sales-based multiples, with attention to accounting quality and peer comparability.',stem:'Three comparable companies trade at P/E multiples of 10×, 20× and 40×. If the question specifically calls for their unweighted harmonic mean, which estimate is closest?',options:[{key:'A',text:'17.1×'},{key:'B',text:'23.3×'},{key:'C',text:'30.0×'}],correct:'A',explain:{intuition:'The harmonic mean averages ratios through their reciprocals and can reduce the influence of large multiples in certain averaging problems.',steps:['Compute reciprocal sum: 1/10 + 1/20 + 1/40 = 0.175.','Harmonic mean = number of observations / reciprocal sum = 3 / 0.175 = 17.1429.','Round to approximately 17.1×.'],formula:'HM = n / Σ(1/xi)',rationales:[{key:'A',text:'Correct. The harmonic mean is approximately 17.1×.'},{key:'B',text:'23.3× is the arithmetic mean of 10×, 20× and 40×.'},{key:'C',text:'30× is not the unweighted harmonic mean.'}],trap:'Use the averaging method specified and understand its weighting interpretation.',memory:'For a harmonic mean, average reciprocals and invert.',transfer:'Do not use a harmonic mean mechanically when comparability or weighting assumptions do not fit.'}},
{id:'q47',module:'m4',sourceLabel:'Curriculum',topic:'EV/EBITDA and enterprise value',type:'Numerical',difficulty:'Intermediate',title:'Supplemental: reconcile EV and common-equity claims',vignetteId:'harbor-multiples',vignetteTitle:'Harbor Consumer Products · Multiple selection and accounting quality',vignetteSummary:'Harbor is a fictional consumer-products business. Analysts are comparing profit-based and sales-based multiples, with attention to accounting quality and peer comparability.',stem:'A peer-based EV/EBITDA analysis implies enterprise value of $900 million. The company has $30 million of excess cash, $170 million of debt, $10 million of preferred stock and $20 million of non-controlling interests. What is common-equity value?',options:[{key:'A',text:'$700 million'},{key:'B',text:'$730 million'},{key:'C',text:'$750 million'}],correct:'B',explain:{intuition:'EV must be reconciled to the claims and non-operating assets before deriving value for common shareholders.',steps:['Add excess cash: $900m + $30m = $930m.','Subtract debt, preferred stock and non-controlling interests: $930m − $170m − $10m − $20m = $730m.'],formula:'Equity value = EV + excess cash − debt − preferred stock − non-controlling interests',rationales:[{key:'A',text:'$700m omits the excess-cash add-back or subtracts a claim twice.'},{key:'B',text:'Correct. Common-equity value is $730m.'},{key:'C',text:'$750m fails to subtract all senior and non-controlling claims.'}],trap:'Confirm exactly which claims are included in the selected definition of EV.',memory:'Value the operating business first, then reconcile to common equity.',transfer:'If lease liabilities are included in EV, handle them consistently in the peer denominator and equity bridge.'}}
,
{id:'q48',module:'m4',sourceLabel:'Curriculum',topic:'Revenue recognition and multiples',type:'Conceptual',difficulty:'Intermediate',title:'Supplemental: assess bill-and-hold revenue',vignetteId:'harbor-multiples',vignetteTitle:'Harbor Consumer Products · Multiple selection and accounting quality',vignetteSummary:'Harbor is a fictional consumer-products business. Analysts are comparing profit-based and sales-based multiples, with attention to accounting quality and peer comparability.',stem:'A company records sales when goods are billed but held in its warehouse for later delivery. The analyst finds that customer acceptance and delivery conditions may not yet be satisfied. What is the most appropriate response before using P/S comparables?',options:[{key:'A',text:'Accept the reported sales because P/S does not use earnings'},{key:'B',text:'Investigate recognition criteria and normalize the sales denominator if the reported recognition is not appropriate'},{key:'C',text:'Switch to EV/EBITDA, which is unaffected by revenue recognition'}],correct:'B',explain:{intuition:'Sales-based valuation still depends on accounting quality. If revenue timing is aggressive, the denominator and subsequent margins can be distorted.',steps:['Review contractual terms and applicable recognition criteria.','Determine whether control has transferred and the recorded revenue is supportable.','If warranted, adjust sales and related expenses consistently before peer comparison.'],formula:'A sales multiple is comparable only when the sales measure is comparable.',rationales:[{key:'A',text:'P/S still uses sales and can be materially distorted by premature recognition.'},{key:'B',text:'Correct. Validate and normalize the denominator before relying on the multiple.'},{key:'C',text:'EBITDA can also be distorted by revenue-recognition choices.'}],trap:'Changing the multiple does not remove an underlying accounting-quality problem.',memory:'Validate the denominator before comparing any multiple.',transfer:'Principal-versus-agent classification can also change reported sales without a matching change in economic profit.'}},
{id:'q49',module:'m5',sourceLabel:'Curriculum',topic:'Economic value added',type:'Numerical',difficulty:'Core',title:'Supplemental: calculate economic value added',stem:'A company generates NOPAT of $48 million. Its invested capital is $500 million and WACC is 8%. What is EVA?',options:[{key:'A',text:'$8 million'},{key:'B',text:'$40 million'},{key:'C',text:'$48 million'}],correct:'A',explain:{intuition:'EVA subtracts the capital charge on all invested capital from after-tax operating profit.',steps:['Capital charge = $500m × 8% = $40m.','EVA = NOPAT − capital charge = $48m − $40m = $8m.'],formula:'EVA = NOPAT − (WACC × invested capital)',rationales:[{key:'A',text:'Correct. Operating profit after tax exceeds the capital charge by $8m.'},{key:'B',text:'$40m is the capital charge, not EVA.'},{key:'C',text:'$48m is NOPAT before charging for invested capital.'}],trap:'Residual income based on equity capital and EVA based on total invested capital use different capital bases and rates.',memory:'Economic profit = after-tax operating income less the opportunity cost of all capital.',transfer:'EVA can be negative despite positive NOPAT if the capital charge is larger.'}},
{id:'q50',module:'m5',sourceLabel:'Curriculum',topic:'Residual income and ROE',type:'Conceptual',difficulty:'Core',title:'Supplemental: interpret ROE equal to the cost of equity',stem:'A company’s sustainable ROE is equal to shareholders’ required return. Under a clean and internally consistent residual-income framework, what is the implication for justified value relative to book value?',options:[{key:'A',text:'Justified value is below book value because residual income is positive'},{key:'B',text:'Justified value equals book value because expected residual income is zero'},{key:'C',text:'Justified value must exceed book value if earnings are positive'}],correct:'B',explain:{intuition:'The residual-income model values equity as book value plus the present value of future residual income; earning exactly the cost of equity creates no excess return.',steps:['Residual income = net income − (required return × beginning book equity).','If ROE equals the required return, the equity charge equals earnings under steady assumptions.','Expected residual income is zero, so value equals book value under the stated framework.'],formula:'V0 = B0 + PV(future RI)',rationales:[{key:'A',text:'Zero residual income does not produce a negative premium to book value.'},{key:'B',text:'Correct. No expected excess return means no residual-income premium or discount under the stated assumptions.'},{key:'C',text:'Positive accounting earnings are not enough; they must exceed the required return on equity.'}],trap:'Positive net income does not necessarily create economic value.',memory:'ROE = r means RI = 0; ROE above r supports positive RI.',transfer:'If ROE is persistently below the cost of equity, value can fall below book value.'}},
{id:'q51',module:'m5',sourceLabel:'Curriculum',topic:'Clean-surplus accounting',type:'Conceptual',difficulty:'Intermediate',title:'Supplemental: reconcile a direct-to-equity gain',stem:'A company records an unrealized gain in other comprehensive income that increases book equity but bypasses net income. How should an analyst using a residual-income model respond?',options:[{key:'A',text:'Ignore the item because only net income can change book equity'},{key:'B',text:'Increase forecast net income by the same amount automatically'},{key:'C',text:'Reconcile the direct-to-equity change and assess its effect on book value and clean-surplus assumptions'}],correct:'C',explain:{intuition:'The basic residual-income framework links earnings and dividends to changes in book equity; items that bypass income need reconciliation.',steps:['Start with the simple relation: ending BVE = beginning BVE + NI − dividends.','Identify the item that changes equity outside net income.','Reconcile or adjust book-value and income inputs consistently before valuation.'],formula:'Clean-surplus relation is a simplifying assumption; direct-to-equity items require reconciliation.',rationales:[{key:'A',text:'Other comprehensive income can change shareholders’ equity.'},{key:'B',text:'An adjustment should reflect accounting facts; automatic treatment can misstate earnings.'},{key:'C',text:'Correct. Reconciliation protects the consistency of book value and residual-income forecasts.'}],trap:'Do not force a direct-to-equity item into net income without a justified accounting adjustment.',memory:'Track every material path by which equity changes.',transfer:'Prior-period adjustments and some foreign-currency or pension items may also require attention.'}},
{id:'q52',module:'m5',sourceLabel:'Curriculum',topic:'Intangibles and residual income',type:'Conceptual',difficulty:'Intermediate',title:'Supplemental: interpret unrecognized intangible investment',stem:'A software company expenses substantial internally generated product-development costs. The spending depresses current earnings, but the resulting product may generate benefits for several years. What is the key residual-income valuation concern?',options:[{key:'A',text:'Reported earnings and book equity may not fully reflect the economic investment and its future benefits; any adjustment must be evidence-based and consistent'},{key:'B',text:'All development spending should automatically be capitalized regardless of the accounting rules or evidence'},{key:'C',text:'Intangible assets never matter to residual income because only cash flow is used'}],correct:'A',explain:{intuition:'Residual-income models use accounting earnings and book value, so intangible-investment accounting can affect both the starting equity base and future residual income.',steps:['Understand how the costs were recognized and what future benefits are expected.','Assess whether the analysis requires a justified adjustment to earnings or book value.','Apply any adjustment consistently across periods and avoid overstating uncertain assets.'],formula:'V0 = B0 + PV(future RI); accounting inputs influence both B0 and future RI.',rationales:[{key:'A',text:'Correct. The model can be affected by omitted or differently recognized intangible investment.'},{key:'B',text:'Capitalization cannot be assumed automatically; it must follow the accounting framework and a defensible valuation adjustment.'},{key:'C',text:'Residual income uses accounting data, so book-value and income recognition matter.'}],trap:'Do not adjust merely to make reported earnings look smoother; articulate the economic rationale.',memory:'Residual-income analysis is only as sound as book value and earnings quality.',transfer:'Similar scrutiny applies to impairment, one-off charges and aggressive estimates.'}},
{id:'q53',module:'m6',sourceLabel:'Curriculum',topic:'Private-company earnings normalization',type:'Numerical',difficulty:'Intermediate',title:'Supplemental: normalize owner-manager compensation',vignetteId:'private-company-review',vignetteTitle:'Private Company Review · Normalization and valuation methods',vignetteSummary:'A private-company valuation involves owner-specific compensation, limited liquidity, a guideline-company multiple and a possible excess-earnings approach.',stem:'A private company reports earnings of $750,000 after paying its owner-manager $90,000. A market-rate replacement manager would cost $160,000. Ignoring tax effects and other adjustments, what are normalized earnings?',options:[{key:'A',text:'$680,000'},{key:'B',text:'$750,000'},{key:'C',text:'$820,000'}],correct:'A',explain:{intuition:'Normalized earnings reflect the cost a buyer must bear to operate the business after the current owner exits.',steps:['Market compensation exceeds reported owner compensation by $160,000 − $90,000 = $70,000.','The ongoing expense rises by $70,000.','Normalized earnings = $750,000 − $70,000 = $680,000.'],formula:'Normalized earnings = reported earnings − incremental cost to replace below-market owner compensation',rationales:[{key:'A',text:'Correct. Earnings fall by the $70,000 incremental salary cost.'},{key:'B',text:'Reported earnings retain the benefit of under-market owner compensation.'},{key:'C',text:'Adding back the difference is the wrong direction when replacement cost is higher.'}],trap:'An owner-related adjustment can increase or decrease earnings; do not assume every adjustment is an add-back.',memory:'Normalize to maintainable, market-based operations.',transfer:'If owner compensation is above market and no offsetting costs are needed, a supported adjustment could increase earnings.'}},
{id:'q54',module:'m6',sourceLabel:'Curriculum',topic:'Control and marketability discounts',type:'Numerical',difficulty:'Intermediate',title:'Supplemental: combine two valuation discounts',vignetteId:'private-company-review',vignetteTitle:'Private Company Review · Normalization and valuation methods',vignetteSummary:'A private-company valuation involves owner-specific compensation, limited liquidity, a guideline-company multiple and a possible excess-earnings approach.',stem:'A non-controlling private-company interest is subject to a 15% lack-of-control discount and a 20% lack-of-marketability discount. If the method applies these sequentially, what is the combined discount?',options:[{key:'A',text:'32%'},{key:'B',text:'35%'},{key:'C',text:'5%'}],correct:'A',explain:{intuition:'Sequential discounts apply to the value remaining after the first adjustment, so they are not simply added.',steps:['After a 15% discount, 85% of value remains.','After the second 20% discount, 80% of that remainder remains.','Remaining value = 0.85 × 0.80 = 0.68; combined discount = 1 − 0.68 = 32%.'],formula:'Combined discount = 1 − (1 − DLOC)(1 − DLOM)',rationales:[{key:'A',text:'Correct. Sequential discounts produce a combined discount of 32%.'},{key:'B',text:'35% is the arithmetic sum and ignores sequential application.'},{key:'C',text:'5% is the difference between the two discounts, not their combined effect.'}],trap:'Use the approach the valuation method specifies; do not add discounts mechanically.',memory:'Multiply retained fractions, then subtract from 100%.',transfer:'A 10% control discount followed by a 15% marketability discount gives 23.5% combined.'}},
{id:'q55',module:'m6',sourceLabel:'Curriculum',topic:'Private-company required return',type:'Conceptual',difficulty:'Intermediate',title:'Supplemental: estimate a defensible private-company discount rate',stem:'A private company has concentrated customers, dependence on its founder, and limited disclosure. The analyst uses public comparable companies as a starting point for required return. What is the best practice?',options:[{key:'A',text:'Use the lowest peer beta because private companies have no traded share price'},{key:'B',text:'Use public comparables without reviewing leverage, size, company-specific risk or operating differences'},{key:'C',text:'Use comparable risk data as a starting point, adjust thoughtfully for financing and relevant risk differences, and avoid double-counting risk already in cash flows'}],correct:'C',explain:{intuition:'Private-company rates require judgment because market prices and company-specific data are less directly observable.',steps:['Identify public companies with relevant operating and business risk.','Consider capital structure differences, beta comparability, size, and customer-concentration or key-person risks.','Check whether added risk premiums duplicate conservative cash-flow scenarios or other discount-rate adjustments.'],formula:'Required return should match the risk of the cash flows being discounted.',rationales:[{key:'A',text:'Lack of a traded price does not justify choosing the lowest beta.'},{key:'B',text:'Unadjusted comparables may not represent the target’s financing or business risk.'},{key:'C',text:'Correct. Use market evidence, adjust transparently and avoid double-counting.'}],trap:'Do not stack multiple poorly supported premiums onto an already conservative forecast.',memory:'Match discount rate to cash-flow risk; explain each adjustment.',transfer:'Scenario-weighted cash flows can be more transparent than embedding every uncertainty in a single rate.'}},
{id:'q56',module:'m6',sourceLabel:'Curriculum',topic:'Guideline public company method',type:'Numerical',difficulty:'Intermediate',title:'Supplemental: use a guideline-company multiple',vignetteId:'private-company-review',vignetteTitle:'Private Company Review · Normalization and valuation methods',vignetteSummary:'A private-company valuation involves owner-specific compensation, limited liquidity, a guideline-company multiple and a possible excess-earnings approach.',stem:'A private target has maintainable EBITDA of $12 million. A selected guideline-company multiple is 7.5×. The target has $25 million of debt and $5 million of excess cash. Estimate common-equity value before private-company discounts.',options:[{key:'A',text:'$65 million'},{key:'B',text:'$70 million'},{key:'C',text:'$90 million'}],correct:'B',explain:{intuition:'A guideline public-company multiple estimates enterprise value; financing claims and excess assets are reconciled afterward.',steps:['Enterprise value = 7.5 × $12m = $90m.','Add excess cash and subtract debt: $90m + $5m − $25m = $70m.','Any private-company discounts require a separate defensible basis.'],formula:'EV = selected multiple × maintainable EBITDA; Equity = EV + excess cash − debt-like claims',rationales:[{key:'A',text:'$65m does not reconcile the stated enterprise value, cash and debt.'},{key:'B',text:'Correct. Common-equity value before discounts is $70m.'},{key:'C',text:'$90m is enterprise value before subtracting debt and adding cash.'}],trap:'Do not apply an EV multiple to equity earnings or skip the equity bridge.',memory:'EV multiple first; equity bridge second.',transfer:'If the selected multiple falls to 7.0×, EV falls to $84m and equity value to $64m.'}},
{id:'q57',module:'m6',sourceLabel:'Curriculum',topic:'Excess earnings method',type:'Numerical',difficulty:'Intermediate',title:'Supplemental: estimate intangible value using excess earnings',vignetteId:'private-company-review',vignetteTitle:'Private Company Review · Normalization and valuation methods',vignetteSummary:'A private-company valuation involves owner-specific compensation, limited liquidity, a guideline-company multiple and a possible excess-earnings approach.',stem:'A business has tangible operating assets valued at $8 million. Maintainable earnings are $1.5 million, and the required annual return on tangible assets is 10%. Excess earnings are capitalized at 14%. Under a simplified excess-earnings method, what is the indicated combined value of tangible assets plus the capitalized intangible component?',options:[{key:'A',text:'$8.0 million'},{key:'B',text:'$10.0 million'},{key:'C',text:'$13.0 million'}],correct:'C',explain:{intuition:'The simplified excess-earnings approach assigns a required return to tangible assets, then capitalizes the residual earnings as an indication of intangible value.',steps:['Required return on tangible assets = $8m × 10% = $0.8m.','Excess earnings = $1.5m − $0.8m = $0.7m.','Capitalized intangible component = $0.7m / 14% = $5.0m.','Combined indicated asset value = $8m + $5m = $13m, before other claims or adjustments.'],formula:'Intangible value ≈ (maintainable earnings − return on tangible assets)/capitalization rate',rationales:[{key:'A',text:'$8m includes only the tangible-asset value.'},{key:'B',text:'$10m understates the capitalized excess-earnings component.'},{key:'C',text:'Correct. Tangible value of $8m plus $5m of capitalized excess earnings equals $13m.'}],trap:'Real applications require careful earnings allocation, rates, taxes and ownership-claim analysis.',memory:'Charge tangible assets first; capitalize residual earnings.',transfer:'If the required return on tangible assets rises, excess earnings and indicated intangible value fall.'}},
{id:'q58',module:'m6',sourceLabel:'Curriculum',topic:'Scenario analysis and private-company cash flows',type:'Conceptual',difficulty:'Intermediate',title:'Supplemental: handle uncertainty in private-company forecasts',stem:'A private company depends on one large customer and the founder’s technical expertise. Forecasts vary materially depending on whether the customer renews its contract and whether the founder stays. What is the most defensible analytical treatment?',options:[{key:'A',text:'Use a single optimistic forecast because the private company has no observable share price'},{key:'B',text:'Construct explicit operating scenarios and assess customer-concentration and key-person effects on cash flows and risk'},{key:'C',text:'Apply the same generic illiquidity discount to cash flow and to the discount rate'}],correct:'B',explain:{intuition:'Private-company valuation often has wider uncertainty in the forecast itself. Explicit scenarios make the economic implications more transparent.',steps:['Build scenarios for contract renewal, customer replacement, founder transition and margin effects.','Probability-weight outcomes where probabilities are supportable, or present a range if not.','Match required return to remaining risk and avoid charging the same uncertainty twice.'],formula:'Expected cash flow = Σ scenario probability × scenario cash flow, where probabilities are defensible.',rationales:[{key:'A',text:'An optimistic single path hides material downside risk and concentration.'},{key:'B',text:'Correct. Scenarios translate key private-company risks into explicit economic effects.'},{key:'C',text:'Duplicating illiquidity or company-specific risk in multiple places can distort value.'}],trap:'Do not confuse lack of marketability with operating risk, and do not double-count either.',memory:'Model operational uncertainty transparently; adjust the discount rate for remaining risks.',transfer:'The same discipline applies to a start-up with uncertain commercialization or a business with a concentrated supplier.'}},
{id:'q59',module:'m4',sourceLabel:'Curriculum',topic:'Justified leading P/E',type:'Numerical',difficulty:'Core',title:'Supplemental: calculate a justified leading P/E',stem:'A stable company has a payout ratio of 35%, required return of 9.5% and perpetual growth of 4%. Under stable-growth assumptions, what is its justified leading P/E?',options:[{key:'A',text:'5.00×'},{key:'B',text:'6.36×'},{key:'C',text:'7.50×'}],correct:'B',explain:{intuition:'The justified leading P/E relates payout policy to the spread between required return and perpetual growth.',steps:['Required-return-growth spread = 9.5% − 4.0% = 5.5%.','Leading P/E = payout ratio / spread = 0.35 / 0.055 = 6.3636.','The justified leading P/E is approximately 6.36×.'],formula:'Justified leading P/E = payout ratio/(r−g)',rationales:[{key:'A',text:'5× is too low given the stated payout and 5.5% spread.'},{key:'B',text:'Correct. 35% divided by 5.5% is about 6.36×.'},{key:'C',text:'7.5× would require a different payout or smaller spread.'}],trap:'Use the leading multiple relationship consistently with next-period earnings and stable assumptions.',memory:'Payout ratio on top, required return minus growth below.',transfer:'A higher sustainable payout, all else equal, increases justified leading P/E.'}},
{id:'q60',module:'m5',sourceLabel:'Curriculum',topic:'Selecting a valuation model',type:'Conceptual',difficulty:'Intermediate',title:'Supplemental: choose a model for a financial institution',stem:'A financial institution’s reported dividends are constrained by capital regulation and its near-term free cash flow is volatile. The analyst can reasonably forecast accounting profitability and book equity, and financial-report quality is acceptable after adjustments. Which approach may be particularly useful?',options:[{key:'A',text:'Residual-income valuation, with careful attention to book value, accounting and clean-surplus assumptions'},{key:'B',text:'EV/EBITDA without further review because all financial firms have comparable EBITDA'},{key:'C',text:'A constant-growth dividend model using the current dividend regardless of regulatory constraints'}],correct:'A',explain:{intuition:'Residual-income models can be useful when dividends do not reflect the capacity to create equity value and cash flows are difficult to interpret, provided book equity and accounting are suitable.',steps:['Assess whether book equity is meaningful and can be forecast.','Estimate earnings above the equity capital charge.','Reconcile clean-surplus items and test persistence assumptions for excess returns.'],formula:'V0 = BVE0 + PV(future residual income)',rationales:[{key:'A',text:'Correct. The model can reduce reliance on dividends or distant cash-flow terminal value, but accounting quality is essential.'},{key:'B',text:'EV/EBITDA is often inappropriate or not directly comparable for financial institutions.'},{key:'C',text:'A dividend model should reflect regulatory constraints and realistic payout forecasts.'}],trap:'Model choice depends on business economics, reporting quality and valuation purpose.',memory:'Select a model whose inputs map to the company’s economics.',transfer:'If accounting book value is unreliable, the residual-income model’s advantage may disappear.'}}


];


const STUDY_NOTES = [
{id:'note-value-gap',source:'SSEI',sourceRef:'Handwritten notes · pp. 1–3',module:'m1',title:'Intrinsic value, market price, and perceived mispricing',body:'Intrinsic value is an analyst estimate of what an asset is worth based on the expected economic benefits and the assumptions used. Market price is the observed trading price. They can differ, but the difference is not automatically exploitable: the analyst may also be wrong. If Ve is the analyst’s estimate, V is true intrinsic value, and P is market price, then Ve − P = (Ve − V) + (V − P). The first term is valuation-estimation error; the second is true mispricing. A correct thesis can still fail if price does not converge within the client’s investment horizon.'},
{id:'note-value-premises',source:'SSEI',sourceRef:'Handwritten notes · pp. 4–7',module:'m1',title:'Intrinsic, fair-market, and investment value',body:'Intrinsic value is based on an analysis of the asset’s economic characteristics. Fair market value describes an exchange between willing, informed, able buyers and sellers under an assumed transaction premise. Investment value is value to a particular buyer, reflecting that buyer’s circumstances or potential synergies, so it may differ from intrinsic value. State whether the company is valued as a going concern or on a liquidation basis: the latter may require recognizing the proceeds and costs of selling assets separately rather than assuming ongoing operations.'},
{id:'note-process',source:'SSEI',sourceRef:'Handwritten notes · pp. 8–10',module:'m1',title:'The valuation process and its applications',body:'A useful valuation workflow is: understand the business; forecast financial performance; select a model appropriate to the company and purpose; feed consistent assumptions into the model; and communicate the conclusion and its limitations. Applications include stock selection, inferring market expectations from price, evaluating mergers or other corporate events, assessing business strategy, private-company valuation, share-based compensation, portfolio decisions, and communication with analysts or stakeholders. Valuation is a decision tool, not an end in itself.'},
{id:'note-strategy',source:'SSEI',sourceRef:'Handwritten notes · pp. 10–15',module:'m1',title:'Understand the business before forecasting it',body:'Connect the financial forecast to the business model and competitive context. Porter’s five forces highlight the threat of entry, threat of substitutes, rivalry, supplier power, and buyer power; stronger competitive pressure usually makes sustained above-average profitability harder to defend. Generic strategies include differentiation, cost leadership, and focus. Examine management, ownership, industry position, intangible and physical resources, legal issues, and execution. Avoid mechanically extrapolating past performance: mean reversion and competitive responses can pull unusually good or poor results toward normal levels.'},
{id:'note-report-quality',source:'SSEI',sourceRef:'Handwritten notes · p. 16',module:'m1',title:'Financial-report quality: warning signs',body:'Look for aggressive revenue recognition, capitalizing expenses that should be expensed, classifying operating costs or income inconsistently, optimistic useful-life or salvage-value estimates, delayed impairment recognition, aggressive pension assumptions, large valuation-allowance changes, and material off-balance-sheet financing. These signals do not prove manipulation on their own; they identify areas to investigate. Reconcile accounting statements, footnotes, management commentary, and cash-flow outcomes before treating reported earnings as sustainable.'},
{id:'note-model-choice',source:'SSEI',sourceRef:'Handwritten notes · pp. 17–19',module:'m1',title:'Choose a valuation model that fits the company',body:'Absolute models estimate value from fundamental benefits: dividend discount models, free-cash-flow models, residual-income models, and asset-based methods. Relative valuation compares the company with peers or a reference market using multiples. DDM is most useful when distributions are meaningful and can be forecast; FCFF/FCFE models are useful when cash flow capacity is more informative than current dividends; residual income starts from book value and can help when cash flows are volatile or dividends do not reflect earnings capacity, but it depends on reliable accounting data. Choose the method based on company characteristics, information quality, and the purpose of valuation.'},
{id:'note-relative',source:'SSEI',sourceRef:'Handwritten notes · pp. 20–21',module:'m4',title:'Absolute versus relative valuation',body:'Absolute valuation estimates a standalone value from expected economic benefits and risk. Relative valuation asks how the market values comparable assets. Common multiples include P/E for earnings, P/S for sales, P/B for book equity, price-to-cash-flow, and EV/EBITDA for operating earnings before interest, tax, depreciation, and amortization. Peer comparisons need consistent definitions and adjustments for growth, risk, profitability, accounting, capital intensity, leverage, and cycle position. A stock can be cheap relative to peers and still be expensive relative to fundamentals, or vice versa.'},
{id:'note-fcf',source:'Curriculum',sourceRef:'Supplemental Equity practice themes · printed pp. 265–438',module:'m3',title:'FCFF versus FCFE and the equity-value bridge',body:'FCFF is cash available to debt and equity capital providers; when discounted at WACC it gives enterprise value. FCFE is cash available to common equity after financing flows; when discounted at the required return on equity it gives equity value. A common bridge is FCFF = net income + non-cash charges + interest after tax − fixed-capital investment − working-capital investment. FCFE = FCFF − interest after tax + net borrowing. To move from enterprise value to equity value, add relevant non-operating assets and subtract debt-like claims. Match each cash flow to its discount rate and do not double-count financing.'},
{id:'note-dividends-growth',source:'Curriculum',sourceRef:'Supplemental Equity practice themes · printed pp. 265–438',module:'m2',title:'Dividend models, growth, and terminal value',body:'For the Gordon growth model, P0 = D1/(r − g), where D1 is next period’s dividend and the perpetual-growth assumption requires r > g. Under stable assumptions, sustainable growth is often estimated as ROE × retention ratio. Use an explicit multistage model when growth changes over time or the firm expects special distributions. Terminal value uses the next period’s cash flow at the chosen terminal date, capitalized by the discount rate minus perpetual growth. Date alignment is as important as arithmetic.'},
{id:'note-required-return',source:'Curriculum',sourceRef:'Supplemental Equity practice themes · printed pp. 265–438',module:'m1',title:'Required return and equity risk premium',body:'CAPM estimates the required return as the risk-free rate plus beta times the expected equity risk premium. Gordon-growth and other forward-looking methods can also be used to estimate market risk premiums, but outputs depend on dividend yield, growth and yield assumptions. In historical estimates, understand whether the arithmetic or geometric mean matches the intended use, the time horizon, the bond benchmark, survivorship bias, and any special firm characteristics such as size or thin trading. Avoid adding overlapping risk premia twice.'},
{id:'note-cyclical-multiples',source:'Curriculum',sourceRef:'Supplemental Equity practice themes · printed pp. 265–438',module:'m4',title:'Cyclical P/E, justified multiples, and peer comparison',body:'The P/E denominator is affected by the business cycle. When earnings are depressed at a cyclical trough, P/E may look high; at a peak, unusually strong earnings can make P/E look low. Normalize earnings before drawing conclusions. Justified P/E depends on payout, required return, and growth. Justified P/B is related to ROE, required return, and growth under the model’s stable assumptions. EV/EBITDA helps compare firms with different financing mixes, but EBITDA is not free cash flow because it omits taxes, capital expenditures, and working capital.'},
{id:'note-residual-income',source:'Curriculum',sourceRef:'Supplemental Equity practice themes · printed pp. 265–438',module:'m5',title:'Residual income and clean surplus',body:'Residual income is accounting net income minus the equity capital charge: RI = NI − (required return on equity × beginning book value of equity). The residual-income value framework expresses equity value as current book value plus the present value of expected future residual income. The basic clean-surplus relation is ending book equity = beginning book equity + net income − dividends. Items that change equity outside net income, accounting adjustments, and non-recurring items need attention. Residual income can reduce dependence on distant terminal cash flows, but is sensitive to the quality of accounting inputs and persistence assumptions.'},
{id:'note-private-company',source:'Curriculum',sourceRef:'Supplemental Equity practice themes · printed pp. 265–438',module:'m6',title:'Private-company valuation, control, and marketability',body:'Normalize earnings for substantiated non-recurring items, owner-specific costs, related-party transactions, and non-operating activities. If an owner’s compensation is below market, replacing the owner may increase ongoing expense and reduce normalized earnings; not every adjustment is an add-back. Lack of control is about decision rights; lack of marketability is about the ability to sell an interest. Use discounts or premiums only when the valuation premise and evidence support them. For a diversified business, sum-of-parts valuation values units separately and then reconciles debt-like claims, excess cash, and other non-operating assets.'}
];


const EXAMPLE_EXHIBIT_NOTES = [
{id:'illus-lm1-market-reaction',source:'Curriculum',sourceRef:'Examples & exhibits synthesis · LM1, printed pp. 8–10',module:'m1',title:'Illustration review: market reaction versus intrinsic value',body:'The curriculum’s market-reaction case illustrates how a sharp share-price move can reflect revised forecasts, a prior mispricing being corrected, or a combination. To evaluate competing explanations, reverse-engineer the growth assumptions implied by prices before and after the announcement, then compare them with historical growth, industry demand and durability of the news. A catalyst can matter because price may not converge to value within an investor’s horizon. This note summarizes the analytical lesson rather than reproducing the case exhibit.'},
{id:'illus-lm1-industry',source:'Curriculum',sourceRef:'Example synthesis · LM1, printed pp. 13–14',module:'m1',title:'Illustration review: peer financials and industry economics',body:'An industry comparison is useful only after the analyst understands the drivers that affect all peers. For oilfield services, exploration and production activity is linked to energy prices, supply conditions, capital spending and economic growth. Profit margin can signal cost position, but pricing power also affects margin. Revenue per employee can help assess labor productivity. Do not interpret one ratio without the operational context.'},
{id:'illus-lm1-accounting',source:'Curriculum',sourceRef:'Example synthesis · LM1, printed pp. 17–22',module:'m1',title:'Illustration review: earnings-quality warning signs',body:'The module’s cases illustrate why reported earnings should be challenged when accounting choices are unusually aggressive. Investigate revenue recognition, capitalization of routine costs, estimate changes, one-off gains, reserve assumptions and the relationship between accrual earnings and cash flow. A red flag is a prompt to investigate, not proof of misconduct. State any adjustment, evidence and valuation consequence explicitly.'},
{id:'illus-lm1-methods',source:'Curriculum',sourceRef:'Example synthesis · LM1, printed pp. 23–36',module:'m1',title:'Illustration review: absolute, relative and sum-of-parts valuation',body:'One company may legitimately be valued with more than one approach. Absolute methods value fundamental benefits; relative methods benchmark comparable assets; sum-of-the-parts methods value distinct business lines before reconciling holding-company costs, debt, cash and other claims. If the market values the combined company below a defensible sum of parts, investigate complexity, capital allocation, cross-subsidies and governance before applying a conglomerate discount.'},
{id:'illus-lm2-present-value',source:'Curriculum',sourceRef:'Example synthesis · LM2, printed pp. 51–62',module:'m2',title:'Illustration review: present value and holding-period setup',body:'Dividend and present-value examples turn on cash-flow timing. A single-period model values the next distribution plus expected sale price at the end of the holding period, discounted one period. A multiyear model discounts each expected dividend and terminal price. Write down the valuation date, payment dates and required return before calculating; period errors can materially change the result.'},
{id:'illus-lm2-gordon',source:'Curriculum',sourceRef:'Example synthesis · LM2, printed pp. 62–77',module:'m2',title:'Illustration review: Gordon growth, implied growth and return',body:'Gordon-growth illustrations show that price depends on next-period dividends and the spread between required return and sustainable growth. Solving the model backward can estimate the growth or return implied by the market price. Sensitivity becomes extreme as the spread narrows. If perpetual growth equals or exceeds the required return, the stable-growth model is invalid under those assumptions.'},
{id:'illus-lm2-multistage',source:'Curriculum',sourceRef:'Example synthesis · LM2, printed pp. 77–93',module:'m2',title:'Illustration review: multistage dividends and terminal assumptions',body:'A multistage model forecasts dividends during unusual growth and then transitions to a stable phase. The H-model approximates a gradual linear decline from a high rate to a stable rate; a three-stage model can separate high, transition and stable periods. Terminal value may use a stable DDM or a justified multiple. Keep the terminal date, next-period dividend, growth assumption and discount rate aligned.'},
{id:'illus-lm2-growth',source:'Curriculum',sourceRef:'Example synthesis · LM2, printed pp. 94–100',module:'m2',title:'Illustration review: ROE, retention and growth',body:'Growth examples connect profitability and reinvestment. Under stable assumptions, sustainable growth is ROE multiplied by the retention ratio; a fuller PRAT-style analysis links profit margin, asset turnover, leverage and retention. High growth does not automatically add value: return on incremental investment and required return are critical. Model payout, buybacks and shares outstanding consistently.'},
{id:'illus-lm3-fcf-bridge',source:'Curriculum',sourceRef:'Example and exhibit synthesis · LM3, printed pp. 127–149',module:'m3',title:'Illustration review: FCFF and FCFE bridges',body:'Worked cash-flow cases demonstrate the importance of the starting point. When starting from net income, restore non-cash expenses and after-tax interest to reach FCFF, then subtract capital investment and working-capital investment. FCFE is FCFF less after-tax interest plus net borrowing. CFO-based approaches must check how interest, dividends, taxes and working capital were classified. Do not mix FCFF with the cost of equity or FCFE with WACC.'},
{id:'illus-lm3-forecast',source:'Curriculum',sourceRef:'Example synthesis · LM3, printed pp. 151–173',module:'m3',title:'Illustration review: forecasting cash flow and growth transitions',body:'Forecasting illustrations move from statements to operating drivers: revenue, margins, taxes, depreciation, capital expenditure and working capital. Forecasts should explain why assumptions change. Use explicit stages when growth is high, uncertain or declining, then apply a stable terminal assumption only when justified. Sensitivity analysis should vary the inputs that drive value, including margins, reinvestment, discount rates and terminal growth.'},
{id:'illus-lm3-esg-assets',source:'Curriculum',sourceRef:'Example synthesis · LM3, printed pp. 174–177',module:'m3',title:'Illustration review: ESG and non-operating assets',body:'Material environmental, social and governance factors should affect valuation through economic channels such as revenue, operating cost, capital expenditure, liabilities, risk or discount rates; avoid an arbitrary ESG adjustment without a causal link. Identify non-operating assets and excess cash separately where appropriate so they are not omitted or counted twice in operating cash-flow valuation.'},
{id:'illus-lm4-pe',source:'Curriculum',sourceRef:'Example and exhibit synthesis · LM4, printed pp. 223–255',module:'m4',title:'Illustration review: P/E, peer groups and normalized earnings',body:'P/E examples distinguish trailing and leading earnings, justified multiples based on fundamentals, peer and industry comparisons, historical ranges and cross-market differences. For cyclicals, a low P/E can occur near peak earnings and a high P/E near depressed earnings, so normalized earnings may be more informative. A peer multiple is not a fair value by itself: compare growth, risk, payout, accounting quality and cycle position.'},
{id:'illus-lm4-other-multiples',source:'Curriculum',sourceRef:'Example and exhibit synthesis · LM4, printed pp. 257–290',module:'m4',title:'Illustration review: P/B, P/S, P/CF, yield and EV multiples',body:'P/B is informative when book equity is meaningful and is related to sustainable ROE, growth and the cost of equity. P/S can help when earnings are weak but ignores margins. Price-to-cash-flow depends on the cash-flow definition. Dividend yield reflects payout as well as expected return. EV multiples require consistent enterprise-value adjustments and operating denominators; EBITDA excludes taxes, capex and working capital.'},
{id:'illus-lm4-accounting',source:'Curriculum',sourceRef:'Example and exhibit synthesis · LM4, printed pp. 267–305',module:'m4',title:'Illustration review: revenue recognition, harmonic mean and indicators',body:'Revenue-recognition illustrations show how delivery timing and principal-versus-agent presentation can distort the denominator of a sales multiple. Normalize accounting definitions before comparing peers. The harmonic mean can be appropriate for certain ratio-averaging problems, but its use depends on weighting assumptions. Triangulate valuation indicators rather than averaging them mechanically. Momentum indicators describe price trends, not intrinsic value.'},
{id:'illus-lm5-ri',source:'Curriculum',sourceRef:'Example and exhibit synthesis · LM5, printed pp. 338–361',module:'m5',title:'Illustration review: residual income and economic profitability',body:'Residual-income cases start with book equity and deduct the equity capital charge from net income. A general residual-income value adds the present value of future residual income to current book value. The persistence and fade of excess returns affect terminal value. Residual income can be useful when dividends are not informative or cash flows are volatile, but it depends on accounting book values and the clean-surplus relationship.'},
{id:'illus-lm5-accounting',source:'Curriculum',sourceRef:'Example and exhibit synthesis · LM5, printed pp. 362–377',module:'m5',title:'Illustration review: clean surplus and accounting adjustments',body:'Earnings, dividends and book equity must reconcile. Other comprehensive income, direct-to-equity transactions, write-offs and prior-period adjustments can bypass the simple clean-surplus roll-forward. Unrecognized intangibles can affect book value and reported returns; one-off items can distort residual income. Adjustments should be evidence-based and applied consistently across forecasts and valuation.'},
{id:'illus-lm6-normalization',source:'Curriculum',sourceRef:'Example synthesis · LM6, printed pp. 407–422',module:'m6',title:'Illustration review: normalize private-company earnings and cash flow',body:'Private-company examples emphasize evidence-based adjustments to owner compensation, related-party transactions, unusual expenses, non-operating activities and nonrecurring items. Below-market owner compensation may need to be replaced with a higher market cost, reducing normalized earnings; excess owner compensation can have the opposite effect. Validate recurrence, then forecast working capital, capital expenditure and maintainable cash flow.'},
{id:'illus-lm6-discounts',source:'Curriculum',sourceRef:'Example synthesis · LM6, printed pp. 422–434',module:'m6',title:'Illustration review: private-company discount rates and discounts',body:'Private-company return estimates examine size, concentration, financing, company-specific risk and limitations of data. Avoid double-counting risk already reflected in forecasts. Lack-of-control adjustments relate to decision rights; lack-of-marketability adjustments relate to liquidity. When multiple discounts are sequentially applied, multiply the retained fractions rather than mechanically adding percentages.'},
{id:'illus-lm6-methods',source:'Curriculum',sourceRef:'Example synthesis · LM6, printed pp. 434–463',module:'m6',title:'Illustration review: cash flow, excess earnings and guideline companies',body:'Income, asset and market approaches answer different valuation questions. Capitalized cash flow requires a maintainable cash-flow estimate and defensible capitalization rate. The excess-earnings method separates the required return on tangible assets from residual earnings attributed to intangible value. Guideline-company methods require comparable operating and financial characteristics and consistent multiples. Reconcile evidence rather than assuming any one method is universally superior.'}
];

const DEEP_STUDY_NOTES = [
{id:'deep-m1-1',source:'Curriculum',sourceRef:'LM1 · printed pp. 4–9',module:'m1',title:'Intrinsic value, price and the two-part mispricing gap',body:'Valuation is a purpose-driven estimate rather than a directly observable fact. For publicly traded equity, intrinsic value is typically the relevant concept, while market price is observable and may differ from the estimate. The difference between estimated value and market price contains two distinct elements: true mispricing (true intrinsic value minus price) and valuation-estimation error (the analyst’s estimate minus true value). Since true intrinsic value is unobservable, an analyst must test assumptions against evidence and market-implied expectations. Even a sound thesis can fail if price does not converge within the investor’s horizon; a catalyst may matter to timing.',memory:'Estimated value − price = true mispricing + estimation error.',examTrap:'A price/value gap is only perceived mispricing until estimation error is considered.'},
{id:'deep-m1-2',source:'Curriculum',sourceRef:'LM1 · printed pp. 4–7',module:'m1',title:'Choose the valuation premise before choosing a model',body:'Going-concern value assumes the business will continue operating and using its assets together. Liquidation value instead considers assets sold individually; timing and the distinction between orderly and forced liquidation can matter. Intrinsic value is generally the relevant frame for public-equity analysis, fair-market value may be relevant to ownership transfers or tax contexts, and investment value reflects a particular investor’s requirements or synergies. These definitions are not interchangeable: a model can be mathematically correct yet answer the wrong valuation question if the premise is wrong.',memory:'First decide: what value, to whom, for what purpose, under which premise?',examTrap:'A buyer-specific synergy value is not automatically fair-market value.'},
{id:'deep-m1-3',source:'Curriculum',sourceRef:'LM1 · printed pp. 10–16',module:'m1',title:'Translate industry analysis into forecast drivers',body:'Industry frameworks are useful when they identify drivers that affect future economics. The five competitive forces are intra-industry rivalry, threat of entry, threat of substitutes, supplier bargaining power, and buyer bargaining power. Cost leadership, differentiation and focus are strategy choices; whether they create value depends on execution and the resulting economics. Connect the framework to revenue, margins, reinvestment, risk and forecast persistence. Review historical reports across different points in time rather than extrapolating one recent period. Competitive success often invites responses, so unusually high or low profitability may revert toward normal levels.',memory:'Industry structure → competitive position → strategy execution → forecast economics.',examTrap:'Do not merely name a framework; explain which cash-flow or risk assumption it changes.'},
{id:'deep-m1-4',source:'Curriculum',sourceRef:'LM1 · printed pp. 17–39',module:'m1',title:'Financial-report quality, model choice and research communication',body:'Before selecting a model, check whether reported earnings, assets and cash flows are economically representative. Revenue timing, capitalization, estimate changes, unusual items and differences in accounting definitions may weaken comparability. A defensible valuation workflow then moves from understanding the business to forecasting performance, selecting a suitable model, converting forecasts into value and applying the conclusion. Absolute models estimate standalone value; relative models estimate value against a benchmark. Sensitivity analysis should show the effect of important assumptions. The final report should make facts, assumptions, judgments, risks and limitations traceable to the conclusion.',memory:'Understand → forecast → select → value → apply and communicate.',examTrap:'Precision in the model cannot rescue low-quality inputs or an unsuitable valuation purpose.'},
{id:'deep-m2-1',source:'Curriculum',sourceRef:'LM2 · printed pp. 51–61',module:'m2',title:'DDM timing: valuation date, dividend date and terminal price',body:'The dividend discount model values equity as the present value of expected shareholder distributions. In a one-period holding model, include the next dividend and the expected sale price at the end of the holding period, then discount both to the valuation date. In a multiyear model, discount each dividend and the terminal sale price at the correct period. Explicitly label D0 (just paid), D1 (next expected), the valuation date and terminal date before substitution. Most common timing errors arise from using D0 where D1 is required or discounting terminal value by the wrong number of periods.',memory:'Cash flows are dated first; discounted second.',examTrap:'Do not use a just-paid dividend as the next-period dividend without growing it when required.'},
{id:'deep-m2-2',source:'Curriculum',sourceRef:'LM2 · printed pp. 62–77',module:'m2',title:'Gordon growth, justified multiples and PVGO',body:'Under stable perpetual growth, value equals next-period dividends divided by the required-return-minus-growth spread. The model assumes a stable long-run state and becomes extremely sensitive as that spread narrows. The price can be rearranged to solve for an implied growth rate or required return, which allows an analyst to compare market expectations with independent evidence. Under related stable assumptions, justified P/E is connected to payout and the same capitalization spread. Present value of growth opportunities distinguishes value associated with future investment opportunities from value under a no-growth earnings premise. Interpret each calculation through its assumptions rather than treating the output as a fact.',memory:'Gordon: D1 on top; r − g below; require r > g.',examTrap:'When r approaches g, small assumption changes can create very large valuation changes.'},
{id:'deep-m2-3',source:'Curriculum',sourceRef:'LM2 · printed pp. 77–93',module:'m2',title:'Match the dividend model to the business growth path',body:'A single-stage model is suitable only when stable growth is a defensible description of the dividend stream. A two-stage model separates an explicit higher-growth period from a stable phase. The H-model is a practical approximation when growth fades gradually and approximately linearly toward the stable rate. A three-stage model can represent high growth, transition and maturity separately. Spreadsheet modelling is useful when dividend, payout or earnings trajectories require year-by-year detail. In all cases, terminal value represents post-forecast distributions at the terminal date; discount it back consistently and examine how much of total value depends on that terminal estimate.',memory:'Stable → Gordon; high then stable → two-stage; gradual fade → H-model; distinct phases → three-stage.',examTrap:'A terminal value is not a cash flow at time zero; discount it from the terminal date.'},
{id:'deep-m2-4',source:'Curriculum',sourceRef:'LM2 · printed pp. 94–103',module:'m2',title:'Sustainable growth, DuPont drivers and payout',body:'A sustainable growth estimate connects profitability to the proportion of earnings retained. Under stable assumptions, growth is ROE multiplied by the retention ratio. DuPont analysis helps explain ROE through profit margin, asset turnover and financial leverage; it makes clear that the same growth rate can result from very different operating and financing drivers. Growth must also be consistent with capital needs and the expected return on incremental investment. Dividends and repurchases both return capital to shareholders, while share issuance can offset repurchases. Dividend-per-share growth alone may therefore fail to describe total shareholder payout or changes in shares outstanding.',memory:'g = ROE × retention; decompose ROE before assuming it persists.',examTrap:'Do not confuse retention ratio with payout ratio or assume higher growth always creates value.'},
{id:'deep-m3-1',source:'Curriculum',sourceRef:'LM3 · printed pp. 127–149',module:'m3',title:'Keep FCFF, FCFE, discount rate and value type aligned',body:'FCFF represents cash available to the providers of debt and equity and, when discounted at WACC, produces enterprise value. FCFE is cash available to common equity after financing flows and is discounted at the required return on equity to produce equity value. The conversion between the two depends on after-tax interest and net borrowing. Net borrowing is debt issued less debt repaid, so a net repayment is negative. If enterprise value is produced first, add appropriate non-operating assets and subtract debt-like and senior claims to reach common-equity value. Capital structure assumptions must match the chosen forecast and discount rate.',memory:'FCFF ↔ WACC ↔ enterprise value; FCFE ↔ cost of equity ↔ equity value.',examTrap:'A correct cash-flow formula paired with the wrong discount rate is still an incorrect valuation.'},
{id:'deep-m3-2',source:'Curriculum',sourceRef:'LM3 · printed pp. 131–149',module:'m3',title:'Cash-flow bridges and non-cash adjustments',body:'When starting from net income, FCFF typically adds net non-cash charges and after-tax interest, then subtracts fixed-capital investment and working-capital investment. Starting from EBIT or EBITDA requires a different bridge: taxes, depreciation or amortization, capital expenditures, working capital, and financing items must be handled according to what the starting metric already includes. When starting from CFO, inspect the classification of interest, dividends, taxes and other items under the applicable reporting practice. Depreciation and some non-cash expenses are added back; non-cash income is subtracted. The correct adjustment depends on whether an item changed reported income without changing current cash.',memory:'Start from the line item; add back only what it already deducted without a cash outflow.',examTrap:'Do not mechanically apply the net-income bridge to EBITDA or cash flow from operations.'},
{id:'deep-m3-3',source:'Curriculum',sourceRef:'LM3 · printed pp. 151–173',module:'m3',title:'Forecast the operating engine, not just a terminal growth rate',body:'Forecast free cash flow through drivers that tie to the business: sales, operating margins, taxes, non-cash expenses, capital expenditure, and operating working capital. When the business is in a high-growth or transition phase, forecast those years explicitly before adopting a stable terminal assumption. A growth forecast that requires no reinvestment may be internally inconsistent. Sensitivity analysis should focus on assumptions with material valuation effects, including margins, reinvestment rates, discount rates, terminal growth, and the length of the high-growth period. Compare more than one coherent scenario when the business outlook is uncertain.',memory:'Operating story → drivers → free cash flow → discounting → sensitivity.',examTrap:'Growth requires resources; check that reinvestment assumptions can support the forecast.'},
{id:'deep-m3-4',source:'Curriculum',sourceRef:'LM3 · printed pp. 155–181',module:'m3',title:'Special FCF issues: payout, capital structure, ESG and non-operating assets',body:'Free cash flow and dividends need not match: dividends reflect board policy, while free cash flow measures cash-generation capacity under model assumptions. Complex capital structures may require explicit treatment of preferred shares, options or other claims. Consider analyst adjustments to CFO only when the economic rationale and accounting evidence support them. Material ESG factors belong in the model through identifiable effects on revenue, costs, investment, liabilities or risk; arbitrary adjustments can double-count uncertainty. Non-operating assets should be valued and added separately when they are not already captured in operating cash flows.',memory:'Separate operating cash generation, financing claims, distributions and non-operating assets.',examTrap:'Do not add the same asset or risk twice, or assume dividends must equal FCFE.'},
{id:'deep-m4-1',source:'Curriculum',sourceRef:'LM4 · printed pp. 223–255',module:'m4',title:'Multiples are a model in compressed form',body:'A multiple compares an equity-value numerator with an equity measure, or an enterprise-value numerator with a measure of operating performance available to capital providers. The denominator’s definition matters: trailing earnings, forward earnings and normalized earnings are not interchangeable. Justified multiples can be derived from fundamental assumptions; peer multiples describe how a benchmark is priced. A comparison is meaningful only when accounting policies, growth, risk, profitability, payout, cyclicality and capital structure are sufficiently comparable or adjusted. Historical and international comparisons also require attention to changes in rates, accounting and market composition.',memory:'Claim in numerator must match the economic claim in denominator.',examTrap:'A comparable multiple is not automatically justified value.'},
{id:'deep-m4-2',source:'Curriculum',sourceRef:'LM4 · printed pp. 238–289',module:'m4',title:'Interpret P/E, P/B, P/S and price-to-cash-flow through fundamentals',body:'P/E relates equity price to earnings; its justified level depends on growth, required return and payout, and the earnings base must be meaningful. P/B relates price to book equity and is most interpretable when accounting book value is economically informative; sustainable ROE relative to the cost of equity is central. P/S can be informative when earnings are weak but it omits margins, so similar sales can support very different equity values. Price-to-cash-flow depends on the specified cash-flow measure. Dividend yield reflects payout as well as expected return. Know exactly which fundamental driver can justify a higher or lower multiple.',memory:'Earnings, book equity, sales, cash flow and dividends answer different questions.',examTrap:'A sales multiple hides margin differences; a P/B comparison can mislead when book equity is not comparable.'},
{id:'deep-m4-3',source:'Curriculum',sourceRef:'LM4 · printed pp. 226–255, 283–305',module:'m4',title:'EV/EBITDA, cyclicality and terminal multiples',body:'EV/EBITDA is designed to compare operating value across financing mixes, but enterprise value must be reconciled consistently for cash, debt, leases, pensions and non-controlling interests. EBITDA is not free cash flow because it omits taxes, capital expenditure and working-capital needs. Cyclical earnings can distort P/E: at a peak, unusually high earnings can make P/E look low, while trough earnings can make it look high. Normalize the cycle before comparing multiples. A terminal multiple should reflect the economics expected at the terminal date, not an arbitrary current peer ratio.',memory:'Use EV multiples for operating measures, but do not mistake EBITDA for cash flow.',examTrap:'A low cyclical P/E can reflect peak earnings rather than undervaluation.'},
{id:'deep-m4-4',source:'Curriculum',sourceRef:'LM4 · printed pp. 291–307',module:'m4',title:'Averaging multiples and triangulating valuation indicators',body:'Multiple averaging is not a neutral mechanical step. The arithmetic mean can be pulled upward by large outliers; a harmonic mean may be suitable for certain ratio-averaging setups when its weighting interpretation fits. Check whether observations are truly comparable and whether loss-making or extreme observations should be treated separately. Momentum indicators help describe price trends, but they answer a different question from intrinsic valuation. A useful conclusion reconciles multiple indicators and explains why some receive more weight rather than reporting a mean with no economic rationale.',memory:'Compare first, normalize second, choose the averaging method third, reconcile last.',examTrap:'Do not select the harmonic mean simply because it is less affected by an outlier.'},
{id:'deep-m5-1',source:'Curriculum',sourceRef:'LM5 · printed pp. 338–350',module:'m5',title:'Residual income charges for the opportunity cost of equity',body:'Residual income is net income less the required return on beginning common equity. Positive accounting earnings do not necessarily create value: earnings must exceed the equity capital charge. The valuation relationship adds the present value of expected future residual income to current book value. If forecast ROE equals the required return, residual income is zero under coherent assumptions; persistent ROE above the required return supports positive residual income, while ROE below it can support value below book value. Forecasts should explain how profitability, book equity and the capital charge change over time.',memory:'RI = NI − (r × beginning book equity); value = book value + PV of future RI.',examTrap:'Do not use ending book value automatically for the standard period capital charge.'},
{id:'deep-m5-2',source:'Curriculum',sourceRef:'LM5 · printed pp. 351–361',module:'m5',title:'Persistence, stages and relationship to other valuation models',body:'A single-stage residual-income model assumes a stable pattern of residual income; a multistage model is more suitable when abnormal profitability fades or changes over time. The persistence of residual income is therefore a key driver of terminal value. Residual-income valuation can be useful when dividends do not reflect distribution capacity or when near-term free cash flow is volatile, provided accounting book value is useful. As with DDM and free-cash-flow models, model selection depends on business characteristics, the purpose of valuation and the reliability of inputs. Residual income is a different formulation of the same fundamental need to value future economic benefits.',memory:'Current book value anchors the model; future excess earnings explain the premium or discount.',examTrap:'Do not capitalize excess returns forever without a defensible persistence assumption.'},
{id:'deep-m5-3',source:'Curriculum',sourceRef:'LM5 · printed pp. 362–377',module:'m5',title:'Clean surplus and accounting distortions',body:'The clean-surplus relation links ending book equity to beginning book equity plus net income less dividends. Transactions recorded directly in equity, such as certain other-comprehensive-income items, can bypass net income and break the simple relation. Other concerns include unrecognized internally generated intangible assets, unusual items, impairment, aggressive estimates and differences across accounting systems. The analyst should determine how each issue affects both starting book value and future residual income. Adjustments should be consistent across periods and justified by economics, rather than applied simply to make the model look smoother.',memory:'Book value and earnings must reconcile, or the model needs explicit adjustments.',examTrap:'A direct-to-equity item should not be shifted into net income automatically.'},
{id:'deep-m5-4',source:'Curriculum',sourceRef:'LM5 · printed pp. 343–380',module:'m5',title:'When residual income is useful—and when it is fragile',body:'Residual income can be a useful cross-check for firms with meaningful book equity and distributions that do not reflect earning capacity. It may also reduce sensitivity to a distant terminal cash-flow estimate. However, book value and reported earnings can be affected by accounting treatment, especially for intangible investment and non-recurring items. It requires forecasts of earnings, book value and dividends to be internally consistent. Compare the conclusion with another suitable approach and investigate any large disagreement rather than treating one model as definitive.',memory:'Useful model, accounting-sensitive inputs: test book value and clean-surplus assumptions.',examTrap:'The residual-income formula does not remove accounting-quality risk; it makes that risk more visible.'},
{id:'deep-m6-1',source:'Curriculum',sourceRef:'LM6 · printed pp. 407–419',module:'m6',title:'Private-company context changes the evidence, not the basic economics',body:'Private-company valuation may be needed for transactions, owner transfers, tax or reporting, and planning. Compared with public firms, disclosure can be limited, ownership concentrated, interests illiquid, and operating results affected by owner-specific costs or related-party dealings. The analyst still values economic benefits, but needs to clarify the premise and intended use before choosing a model. Scrutinize customer concentration, dependence on key people, market position, working capital, capital spending and the quality of forecasts. Do not confuse the absence of a traded price with the absence of valuation discipline.',memory:'Same valuation logic; more work on data, normalization, risk and ownership rights.',examTrap:'Do not import public-company assumptions without checking what is comparable.'},
{id:'deep-m6-2',source:'Curriculum',sourceRef:'LM6 · printed pp. 414–422',module:'m6',title:'Normalize maintainable earnings before applying a multiple',body:'Normalization seeks an estimate of earnings and cash flow that a market participant can reasonably expect to maintain. Analyze owner compensation, related-party rent, nonrecurring items, non-operating income, unusual legal or restructuring expenses, and the business costs required after a change in ownership. An expense is not a valid add-back merely because it is unusual if a buyer must incur an equivalent expense going forward. Tie each adjustment to evidence and then forecast working capital, capital expenditures and other cash requirements, not only adjusted EBITDA.',memory:'Reported results → identify item → test recurrence/owner-specific nature → adjust with evidence.',examTrap:'Below-market owner salary can require a negative earnings adjustment to reflect replacement cost.'},
{id:'deep-m6-3',source:'Curriculum',sourceRef:'LM6 · printed pp. 422–434',module:'m6',title:'Private-company required returns and ownership discounts',body:'Required return reflects the risks of the forecast cash flows. Private-company considerations may include size, customer or supplier concentration, key-person dependence, financing risk and data limitations. Use market evidence where useful, but do not add multiple overlapping premiums for the same risk already reflected in cash-flow scenarios. Lack-of-control and lack-of-marketability adjustments address different ownership characteristics: decision rights versus ability to sell. A discount is not a universal percentage; justify whether it applies to the actual interest being valued and how the valuation method applies it.',memory:'Business risk in forecasts/rate; control is decision power; marketability is liquidity.',examTrap:'Do not add discounts or risk premia mechanically, or double-count uncertainty.'},
{id:'deep-m6-4',source:'Curriculum',sourceRef:'LM6 · printed pp. 434–463',module:'m6',title:'Reconcile income, market and excess-earnings approaches',body:'Income-based methods derive value from future economic benefits. Market-based approaches use observed multiples or transactions from sufficiently comparable businesses. Guideline public-company methods require care when private targets differ in size, growth, risk, margins and liquidity. The excess-earnings method estimates a required return on tangible assets and attributes residual maintainable earnings to intangible value under its assumptions. The final conclusion should reconcile methods and explain input quality, premise and limitations instead of averaging outputs blindly. Debt, excess cash and other claims must be reconciled to the value measure being reported.',memory:'Choose an approach for the facts, normalize inputs, reconcile claims, then reconcile indications.',examTrap:'Do not apply an EV multiple directly to equity earnings or confuse intangible value with total business value.'}
];

function allStudyNotes() {
  const sectionNotes=MODULES.flatMap(function(m){
    return m.topics.map(function(t){
      return {id:'module-'+m.id+'-'+String(t.title).toLowerCase().replace(/[^a-z0-9]+/g,'-'),source:'Curriculum',sourceRef:'Learning Module '+m.no+' · printed p. '+t.page,module:m.id,title:t.title,body:t.body};
    });
  });
  return STUDY_NOTES.concat(sectionNotes,EXAMPLE_EXHIBIT_NOTES,DEEP_STUDY_NOTES);
}



