function renderMapDiagram(map) {
  const rows=map.rows.map(function(row,i){
    const nodes=row.map(function(n,j){return '<div class="memory-node"><div class="memory-node-title">'+esc(n.title)+'</div><div class="memory-node-sub">'+esc(n.sub)+'</div></div>'+(j<row.length-1?'<span class="memory-branch" aria-hidden="true">↔</span>':'');}).join('');
    return '<div class="memory-map-row '+(row.length>1?'memory-map-fork':'')+'">'+nodes+'</div>'+(i<map.rows.length-1?'<div class="memory-down" aria-hidden="true">↓</div>':'');
  }).join('');
  return '<details class="visual-map-card"><summary class="visual-map-summary"><span class="visual-map-module">LM '+getModule(map.module).no+'</span><span class="visual-map-heading">'+esc(map.title)+'</span><span class="visual-map-strap">'+esc(map.strap)+'</span><span class="visual-map-chevron">＋</span></summary><div class="visual-map-body"><div class="memory-map-diagram">'+rows+'</div><div class="memory-takeaway"><strong>Memory hook</strong><span>'+esc(map.memory)+'</span></div><p class="map-takeaway-text">'+esc(map.takeaway)+'</p><button class="btn secondary small" data-action="study-module" data-module="'+esc(map.module)+'">Open LM '+getModule(map.module).no+' guide →</button></div></details>';
}
function renderGordonSensitivityGraph() {
  const w=720,h=300,pl=58,pr=22,pt=25,pb=46,gw=w-pl-pr,gh=h-pt-pb,yMax=85;
  const gx=g=>pl+((g-0.5)/(6.5-0.5))*gw, gy=v=>pt+gh-(v/yMax)*gh;
  const growths=[0.5,1,1.5,2,2.5,3,3.5,4,4.5,5,5.5,6,6.5];
  const series=[{r:9,cls:'series-a'},{r:11,cls:'series-b'},{r:13,cls:'series-c'}];
  const grid=[0,10,20,30,40,50,60,70,80].map(v=>'<line x1="'+pl+'" y1="'+gy(v)+'" x2="'+(w-pr)+'" y2="'+gy(v)+'" class="chart-grid"/><text x="'+(pl-10)+'" y="'+(gy(v)+4)+'" text-anchor="end" class="chart-label">'+v+'</text>').join('');
  const ticks=[1,2,3,4,5,6].map(v=>'<line x1="'+gx(v)+'" y1="'+(pt+gh)+'" x2="'+gx(v)+'" y2="'+(pt+gh+5)+'" class="chart-axis"/><text x="'+gx(v)+'" y="'+(pt+gh+22)+'" text-anchor="middle" class="chart-label">'+v+'%</text>').join('');
  const paths=series.map(s=>'<path class="chart-line '+s.cls+'" d="'+growths.map((g,i)=>(i?'L':'M')+gx(g).toFixed(1)+','+gy(2/(s.r/100-g/100)).toFixed(1)).join(' ')+'"/>').join('');
  const legend=series.map(s=>'<span class="chart-legend-item"><i class="legend-swatch '+s.cls+'"></i>r = '+s.r+'%</span>').join('');
  return '<article class="card learning-chart-card"><div class="card-header"><div><div class="eyebrow">ILLUSTRATIVE SENSITIVITY</div><h3 class="card-title">Gordon value rises sharply as r − g narrows</h3><div class="card-subtitle">Value per share when D1 = $2.00 and growth varies from 0.5% to 6.5%.</div></div><span class="badge muted">Illustration</span></div><svg class="learning-chart" viewBox="0 0 '+w+' '+h+'" role="img" aria-label="Gordon model share value against growth for required returns of 9, 11 and 13 percent"><text x="'+pl+'" y="14" class="chart-axis-title">Value per share ($)</text>'+grid+ticks+'<line x1="'+pl+'" y1="'+pt+'" x2="'+pl+'" y2="'+(pt+gh)+'" class="chart-axis"/><line x1="'+pl+'" y1="'+(pt+gh)+'" x2="'+(w-pr)+'" y2="'+(pt+gh)+'" class="chart-axis"/>'+paths+'</svg><div class="chart-legend">'+legend+'</div><p class="chart-explanation">The curves use the formula from the curriculum with illustrative inputs, not textbook exhibit data. As growth approaches the required return, the denominator shrinks, so estimates become highly sensitive. The Gordon model requires r greater than g.</p></article>';
}
function renderGrowthFadeGraph() {
  const w=720,h=260,pl=54,pr=22,pt=20,pb=46,gw=w-pl-pr,gh=h-pt-pb;
  const years=[0,1,2,3,4,5,6],rates=[12,10.4,8.8,7.2,5.6,4,4],x=y=>pl+(y/6)*gw,y=v=>pt+gh-((v-2)/(14-2))*gh;
  const grid=[2,4,6,8,10,12,14].map(v=>'<line x1="'+pl+'" y1="'+y(v)+'" x2="'+(w-pr)+'" y2="'+y(v)+'" class="chart-grid"/><text x="'+(pl-9)+'" y="'+(y(v)+4)+'" text-anchor="end" class="chart-label">'+v+'%</text>').join('');
  const ticks=years.map(v=>'<text x="'+x(v)+'" y="'+(pt+gh+22)+'" text-anchor="middle" class="chart-label">'+(v===0?'Now':'Y'+v)+'</text>').join('');
  const d=rates.map((v,i)=>(i?'L':'M')+x(years[i])+','+y(v)).join(' ');
  return '<article class="card learning-chart-card"><div class="card-header"><div><div class="eyebrow">ILLUSTRATIVE GROWTH PATH</div><h3 class="card-title">A high-growth phase can fade into maturity</h3><div class="card-subtitle">Illustrates a gradual transition from 12% to a stable 4% growth rate.</div></div><span class="badge muted">Illustration</span></div><svg class="learning-chart" viewBox="0 0 '+w+' '+h+'" role="img" aria-label="Illustrative growth rate declining from 12 percent to 4 percent and then remaining stable">'+grid+ticks+'<line x1="'+pl+'" y1="'+pt+'" x2="'+pl+'" y2="'+(pt+gh)+'" class="chart-axis"/><line x1="'+pl+'" y1="'+(pt+gh)+'" x2="'+(w-pr)+'" y2="'+(pt+gh)+'" class="chart-axis"/><path class="chart-line series-a" d="'+d+'"/>'+rates.map((v,i)=>'<circle class="chart-dot" cx="'+x(years[i])+'" cy="'+y(v)+'" r="4"/>').join('')+'</svg><p class="chart-explanation">This is an explanatory growth path, not a copied textbook graph. The model choice follows the expected path: a stable-growth model assumes maturity now; multistage models represent an explicit transition.</p></article>';
}

