function filteredQuestions() {
  let list=questions(); const p=profile(); const query=(ui.questionQuery||ui.query||'').trim().toLowerCase();
  if(query) list=list.filter(function(q){const set=getQuestionSet(q);return (q.title+' '+q.stem+' '+q.topic+' '+getModule(q.module).title+' '+set.title).toLowerCase().includes(query);});
  if(ui.filterModule&&ui.filterModule!=='all')list=list.filter(function(q){return q.module===ui.filterModule;});
  if(ui.filterType&&ui.filterType!=='all')list=list.filter(function(q){return q.type===ui.filterType;});
  if(ui.filterStatus&&ui.filterStatus!=='all')list=list.filter(function(q){return questionStatus(p,q)===ui.filterStatus;});
  if(ui.onlyWeak) list=list.filter(function(q){return questionStatus(p,q)==='incorrect';});
  return list;
}


function renderQuestionBank() {
  const all=questions(),filtered=filteredQuestions(),matchingIds=new Set(filtered.map(function(q){return q.id;})),p=profile();
  const everyGroup=groupQuestionsIntoItemSets(all);
  // A match opens the whole item set; sibling questions are never hidden by search or status filters.
  const groups=everyGroup.filter(function(g){return g.questions.some(function(q){return matchingIds.has(q.id);});});
  const visibleQuestionCount=groups.reduce(function(total,g){return total+g.questions.length;},0);
  const imported=all.filter(function(q){return q.bookImported||q.sourceBookQuestion;}),sourceMeta=state.shared.sourceMeta||{};
  const coverage=imported.length
    ? '<div class="curriculum-coverage-strip"><strong>Curriculum question coverage</strong><span>'+imported.length+' source candidates</span><span>'+(sourceMeta.expectedQuestionCount||222)+' expected in the supplied volume</span><span>'+everyGroup.filter(function(g){return g.questions.some(function(q){return q.bookImported||q.sourceBookQuestion;})&&!g.set.standalone;}).length+' source-defined item sets</span></div>'
    : '<div class="curriculum-coverage-strip muted-coverage"><strong>Curriculum question bank not indexed in this browser</strong><span>The public site does not embed the copyrighted curriculum text. Open Settings → Source Vault to index the supplied PDF locally; the exact passages and complete question inventory will then appear here.</span></div>';
  return sectionHeader('QUESTION BANK','Browse by curriculum item set','Every source-defined set retains the question range printed in the book. It shows the full shared passage in one container and all related questions in the other. Filtering selects a whole set and never hides its siblings.')+
  coverage+
  '<div class="toolbar"><input class="field" id="questionSearch" placeholder="Search item sets, topics or questions…" value="'+esc(ui.questionQuery||ui.query)+'"><select class="select" id="filterModule"><option value="all">All learning modules</option>'+MODULES.map(function(m){return '<option value="'+m.id+'" '+(ui.filterModule===m.id?'selected':'')+'>'+esc('LM '+m.no+' · '+m.title)+'</option>';}).join('')+'</select><select class="select" id="filterType"><option value="all">All question types</option>'+Array.from(new Set(all.map(function(q){return q.type;}))).map(function(t){return '<option value="'+esc(t)+'" '+(ui.filterType===t?'selected':'')+'>'+esc(t)+'</option>';}).join('')+'</select><select class="select" id="filterStatus"><option value="all">All statuses</option><option value="unattempted" '+(ui.filterStatus==='unattempted'?'selected':'')+'>Unattempted</option><option value="correct" '+(ui.filterStatus==='correct'?'selected':'')+'>Latest correct</option><option value="incorrect" '+(ui.filterStatus==='incorrect'?'selected':'')+'>Incorrect / needs review</option><option value="review" '+(ui.filterStatus==='review'?'selected':'')+'>Self-review / unscored</option></select><button class="btn secondary" data-action="reset-filters">Reset</button></div>'+
  '<div class="question-bank-summary"><span>'+groups.length+' item sets / standalone questions · '+visibleQuestionCount+' questions displayed · '+filtered.length+' questions match filters · '+all.length+' total available</span><span>Latest accuracy '+correctRate(p)+'%</span></div>'+
  (groups.length?'<div class="question-set-grid">'+groups.map(function(g,i){return renderItemSetGroupCard(g,i,!!(ui.questionQuery||ui.query||ui.filterModule!=='all'||ui.filterType!=='all'||ui.filterStatus!=='all'||ui.onlyWeak));}).join('')+'</div>':'<div class="card empty-state"><div class="empty-icon">⌕</div><h3>No item sets match these filters</h3><p>Clear the filters to return to the grouped question bank.</p><button class="btn secondary" data-action="reset-filters">Clear filters</button></div>');
}

