function renderPractice() {
  const q=getQuestion(ui.currentQuestion), p=profile(), prior=latestFor(p,q.id), selected=ui.selectedAnswer, shown=ui.answerShown, currentSet=getQuestionSet(q), setQuestions=questions().filter(function(item){return getQuestionSet(item).id===currentSet.id;});
  const isConstructed=!Array.isArray(q.options)||q.options.length===0;
  const needsSelfAssessment=isConstructed||!q.correct||(q.sourceBookQuestion&&q.verificationStatus!=='Verified by learner');
  const choiceHTML=isConstructed
    ? '<div class="field-group"><label class="label" for="constructedAnswer">Write your approach / answer</label><textarea class="textarea" id="constructedAnswer" style="min-height:145px" placeholder="Show formula selection, substitutions, calculations, assumptions, and interpretation.">'+esc(ui.constructedAnswer||'')+'</textarea><div class="card-subtitle" style="margin-top:7px">Constructed response · compare your work with the source solution before self-assessing.</div></div>'
    : '<div class="answer-options">'+q.options.map(function(o){let cls='answer-option';if(selected===o.key)cls+=' selected';if(shown&&!needsSelfAssessment&&o.key===q.correct)cls+=' correct';else if(shown&&!needsSelfAssessment&&selected===o.key&&o.key!==q.correct)cls+=' incorrect';return '<label class="'+cls+'"><input type="radio" name="answer" value="'+esc(o.key)+'" '+(selected===o.key?'checked':'')+' '+(shown?'disabled':'')+' style="margin-top:5px;accent-color:var(--accent)"><span class="option-letter">'+esc(o.key)+'</span><span>'+esc(o.text)+'</span></label>';}).join('')+'</div>';
  const ex=q.explain||{};let feedback='';
  if(shown&&needsSelfAssessment&&!ui.constructedAssessmentSaved){
    feedback='<div class="feedback-card"><h3>Review the source, then assess your understanding</h3><p>'+(q.correct?'A possible answer key was detected, but it is not used for automatic scoring until you verify the item.':'No reliable answer key was extracted. Do not infer the correct answer from the parser.')+'</p>'+
    (ui.constructedAnswer?'<div class="explanation-section"><h4>Your written response</h4><p>'+esc(ui.constructedAnswer)+'</p></div>':'')+
    (selected?'<div class="explanation-section"><h4>Your selected option</h4><p>'+esc(selected)+'</p></div>':'')+
    (q.correct?'<div class="explanation-section"><h4>Detected answer key · unverified</h4><p>'+esc(q.correct)+'</p></div>':'')+
    (q.sourceSolution?'<div class="explanation-section"><h4>Extracted solution text</h4><p>Printed page '+esc(q.sourcePage||'not supplied')+'. PDF extraction can omit layout or merge lines; compare this text with the original page.</p><div class="source-page-text">'+esc(q.sourceSolution)+'</div></div>':'<div class="callout">No matching solution text was confidently found. Review the solution pages manually before scoring this attempt.</div>')+
    '<div class="explanation-section"><h4>Self-assess after checking the source</h4><p>This is a learning record, not an automatic correctness score. Choose the option that best describes your understanding.</p><div class="field-group"><label class="label" for="constructedAssessment">Your assessment</label><select id="constructedAssessment" class="select"><option value="understood">Understood · answer and reasoning are sound</option><option value="partial">Partial · some gaps remain</option><option value="needs-review">Needs review · not yet understood</option></select></div><button class="btn" data-action="save-constructed-review" data-qid="'+esc(q.id)+'">Save self-review →</button></div></div>';
  } else if(shown) {
    const isScored=!needsSelfAssessment;
    feedback='<div class="feedback-card"><h3>'+(isScored?(selected===q.correct?'✓ Correct — build on the reasoning':'↻ Let’s close the gap'):'✓ Self-review saved')+'</h3>'+
    (isScored?'<p><strong>Correct answer: '+esc(q.correct)+'.</strong> '+esc((ex.rationales||[]).find(function(r){return r.key===q.correct;})?.text||'Review the explanation below.')+'</p>':'<p>Your response is saved as a self-review. This source item is excluded from automatic accuracy scoring until the answer key is verified.</p>')+
    (ex.intuition?'<div class="explanation-section"><h4>1 · From first principles</h4><p>'+esc(ex.intuition)+'</p></div>':'')+
    (ex.steps&&ex.steps.length?'<div class="explanation-section"><h4>2 · Step-by-step reasoning / source solution</h4><ol>'+ex.steps.map(function(s){return '<li>'+esc(s)+'</li>';}).join('')+'</ol></div>':'')+
    (q.sourceSolution?'<div class="explanation-section"><h4>Extracted source solution · check the original page</h4><div class="source-page-text">'+esc(q.sourceSolution)+'</div></div>':'')+
    (ex.formula?'<div class="explanation-section"><h4>3 · Formula and variables</h4><div class="formula-box">'+esc(ex.formula)+'</div></div>':'')+
    (ex.rationales&&ex.rationales.length?'<div class="explanation-section"><h4>4 · Answer-choice analysis</h4>'+ex.rationales.map(function(r){return '<p><strong>Option '+esc(r.key)+':</strong> '+esc(r.text)+'</p>';}).join('')+'</div>':'')+
    (ex.trap?'<div class="explanation-section"><h4>5 · Exam trap</h4><p>'+esc(ex.trap)+'</p></div>':'')+(ex.memory?'<div class="explanation-section"><h4>6 · Memory aid</h4><p>'+esc(ex.memory)+'</p></div>':'')+
    (ex.transfer?'<div class="explanation-section"><h4>7 · Transfer learning</h4><p>'+esc(ex.transfer)+'</p><details><summary style="cursor:pointer;color:var(--accent)">Reveal answer</summary><p>'+esc(ex.transferAnswer||'Use the same framework and substitute the new inputs.')+'</p></details></div>':'')+
    '<div class="explanation-section"><h4>Source and integrity</h4><p>'+(q.sourceBookQuestion?'Source reference: printed page '+esc(q.sourcePage||'not supplied')+'. Verification: '+esc(q.verificationStatus||'Needs explanation review')+'. Extracted source text is not itself an improved teaching explanation.':'Original in-app practice question; not an official CFA Institute answer key.')+'</p>'+(q.sourceBookQuestion&&q.verificationStatus!=='Verified by learner'?'<button class="btn secondary small" data-action="verify-source-question" data-qid="'+esc(q.id)+'">Mark reviewed after checking source</button>':'')+'</div>'+
    '<div style="display:flex;flex-wrap:wrap;gap:9px;margin-top:18px"><button class="btn" data-action="next-question">Next question →</button><button class="btn secondary" data-action="build-ai-prompt" data-qid="'+esc(q.id)+'">Create tutor prompt ↗</button></div></div>';
  }
  return sectionHeader('PRACTICE QUESTION','Work the problem, then unpack the logic','The shared passage appears separately above the question. Use the question navigator to move through its linked set.')+
  renderQuestionSetPassage(currentSet,q)+'<div class="practice-layout"><div class="card question-card"><div class="question-topline"><span class="badge blue">'+esc(q.type)+' · '+esc(q.difficulty||'Practice')+'</span><span class="badge muted question-source-tag">'+esc(q.sourceLabel||'Curriculum')+'</span><button class="btn ghost small" data-action="bookmark" data-qid="'+esc(q.id)+'">'+(p.bookmarks.includes(q.id)?'★ Bookmarked':'☆ Bookmark')+'</button></div><h2 class="question-heading">'+esc(q.title)+'</h2><div class="question-meta" style="margin-bottom:14px"><span>'+esc(getModule(q.module).title)+'</span><span>· '+esc(q.topic)+'</span>'+(q.sourcePage?'<span>· Source p. '+esc(q.sourcePage)+'</span>':'')+'</div>'+
  
  '<p class="question-stem">'+esc(q.stem)+'</p>'+choiceHTML+
  (!shown?'<div style="display:flex;gap:9px;align-items:center;flex-wrap:wrap"><button class="btn" data-action="submit-answer" data-qid="'+esc(q.id)+'" '+((isConstructed?!String(ui.constructedAnswer||'').trim():!selected)?'disabled':'')+'>Check answer</button><label style="color:var(--muted);font-size:11px">Confidence <select id="confidenceSelect" class="select" style="margin-left:6px;width:auto;padding:7px"><option value="1">Low</option><option value="2" selected>Medium</option><option value="3">High</option></select></label></div>':'')+feedback+
  '</div><aside class="practice-aside"><div class="card side-card"><div class="card-header"><div><h3 class="card-title">Question context</h3><div class="card-subtitle">Use these prompts to structure your reasoning.</div></div></div><div class="detail-pair"><span>Question</span><span>'+esc(q.id.toUpperCase())+'</span></div><div class="detail-pair"><span>Module</span><span>LM '+getModule(q.module).no+'</span></div><div class="detail-pair"><span>Attempts</span><span>'+p.attempts.filter(function(a){return a.qid===q.id;}).length+'</span></div><div class="detail-pair"><span>Latest result</span><span>'+(prior?(prior.correct===null?'Self-review':prior.correct?'Correct':'Review'):'Not attempted')+'</span></div><div class="detail-pair"><span>Saved bookmark</span><span>'+(p.bookmarks.includes(q.id)?'Yes':'No')+'</span></div></div><div class="card side-card"><div class="card-header"><div><h3 class="card-title">Reasoning checklist</h3></div></div><div class="list"><div class="revision-item"><div class="check-dot">1</div><div class="row-main"><div class="row-title">What value is being measured?</div><div class="row-subtitle">Equity value or enterprise value?</div></div></div><div class="revision-item"><div class="check-dot">2</div><div class="row-main"><div class="row-title">Which assumptions matter?</div><div class="row-subtitle">Growth, payout, risk, reinvestment or accounting.</div></div></div><div class="revision-item"><div class="check-dot">3</div><div class="row-main"><div class="row-title">Are units and timing consistent?</div><div class="row-subtitle">Check periods and numerator/denominator alignment.</div></div></div></div></div>'+renderSetQuestionNavigator(currentSet,setQuestions,q.id)+'<div class="card side-card"><h3 class="card-title" style="margin-bottom:9px">Other ways to practice</h3><button class="btn secondary small" style="width:100%;margin-bottom:8px" data-action="nav" data-page="questions">Browse item sets</button><button class="btn secondary small" style="width:100%" data-action="nav" data-page="revision">Review weak areas</button></div></aside></div>';
}
function renderActiveExam() {
  const ex=ui.exam, q=getQuestion(ex.ids[ex.index]), ans=ex.answers[q.id], isConstructed=!Array.isArray(q.options)||q.options.length===0, examSet=getQuestionSet(q);
  const questionInput=isConstructed
    ? '<div class="field-group"><label class="label" for="examConstructedAnswer">Your worked answer</label><textarea class="textarea" id="examConstructedAnswer" style="min-height:140px" placeholder="Work independently. The solution stays hidden until review.">'+esc(ans||'')+'</textarea></div>'
    : '<div class="answer-options">'+q.options.map(function(o){return '<label class="answer-option '+(ans===o.key?'selected':'')+'"><input type="radio" name="examAnswer" value="'+esc(o.key)+'" '+(ans===o.key?'checked':'')+' style="margin-top:5px;accent-color:var(--accent)"><span class="option-letter">'+esc(o.key)+'</span><span>'+esc(o.text)+'</span></label>';}).join('')+'</div>';
  return sectionHeader('TIMED PRACTICE','Mock exam in progress','Question '+(ex.index+1)+' of '+ex.ids.length+' · explanations remain hidden until submission.')+
  renderQuestionSetPassage(examSet,q)+'<div class="card question-card"><div class="question-topline"><span class="badge amber">⏱ <span id="examClock">'+formatSeconds(ex.remainingSeconds)+'</span> remaining</span><span class="badge blue">'+(ex.index+1)+' / '+ex.ids.length+'</span></div><h2 class="question-heading">'+esc(q.title)+'</h2><p class="question-stem">'+esc(q.stem)+'</p>'+questionInput+'<div style="display:flex;justify-content:space-between;gap:9px;flex-wrap:wrap;margin-top:19px"><button class="btn secondary" data-action="exam-prev" '+(ex.index===0?'disabled':'')+'>← Previous</button><div style="display:flex;gap:9px"><button class="btn secondary" data-action="exam-skip">Mark / Skip</button>'+(ex.index===ex.ids.length-1?'<button class="btn" data-action="exam-finish">Submit mock</button>':'<button class="btn" data-action="exam-next">Next →</button>')+'</div></div><div class="progress-track" style="margin-top:20px"><div class="progress-fill" style="width:'+pct(ex.index+1,ex.ids.length)+'%"></div></div></div>';
}
function formatSeconds(s) { s=Math.max(0,Math.floor(s||0)); return String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0'); }
function renderMockResults() {
  const ex=ui.exam;if(!ex||!ex.finished)return '';
  const results=ex.ids.map(function(id){const q=getQuestion(id),answer=ex.answers[id]||null;const unscored=q.responseType==='constructed'||!q.correct||(q.sourceBookQuestion&&q.verificationStatus!=='Verified by learner');return {q:q,answer:answer,correct:unscored?null:answer===q.correct};});
  const scored=results.filter(function(r){return r.correct!==null;}), correctCount=scored.filter(function(r){return r.correct;}).length;
  const score=pct(correctCount,scored.length), selfReview=results.filter(function(r){return r.correct===null;}).length;
  return sectionHeader('MOCK REVIEW','Assessment results','Only verified multiple-choice answer keys are automatically scored. Constructed responses and unverified source items require manual review.')+
  '<div class="grid stats-grid">'+statCard('Score',scored.length?score+'%':'—',scored.length+' automatically scored','✓')+statCard('Correct',correctCount,'of '+scored.length+' scored questions','◈')+statCard('Self-review',selfReview,'constructed / unverified-key items','↻')+statCard('Time remaining',formatSeconds(ex.remainingSeconds),'at submission','◷')+'</div>'+
  '<div class="card"><div class="card-header"><div><h3 class="card-title">Question-by-question review</h3><div class="card-subtitle">Choose a question to open its source solution and teaching notes.</div></div><button class="btn secondary small" data-action="new-mock">Create another mock</button></div><div class="question-list">'+results.map(function(r){const label=r.correct===null?'Self-review':r.correct?'Correct':'Review';return '<div class="question-row" data-action="open-question" data-qid="'+esc(r.q.id)+'"><div class="question-id">'+(r.correct===true?'✓':r.correct===null?'↻':'!')+'</div><div class="question-content"><div class="question-title">'+esc(r.q.title)+'</div><div class="question-meta"><span>Your answer: '+esc(r.answer||'Unanswered')+'</span>'+(r.q.correct?'<span>· Detected key: '+esc(r.q.correct)+(r.q.verificationStatus==='Verified by learner'?'':' (unverified)')+'</span>':'<span>· No verified key</span>')+'</div></div><span class="badge '+(r.correct===true?'green':r.correct===null?'amber':'red')+'">'+label+'</span></div>';}).join('')+'</div></div>';
}
function renderMock() {
  if(ui.exam&&!ui.exam.finished)return renderActiveExam();
  return sectionHeader('MOCK EXAMS','Build a timed practice session','Choose the length, time limit, module scope, and question-selection rule. The active question inventory currently covers Equity Valuation only; this is not yet a full ten-subject mock exam.')+
    '<div class="grid grid-2"><div class="card"><div class="card-header"><div><h3 class="card-title">Mock exam setup</h3><div class="card-subtitle">'+questions().length+' available questions in this browser</div></div><span class="badge blue">Timed</span></div>'+
    '<form id="mockForm"><div class="field-group"><label class="label" for="mockCount">Number of questions</label><select class="select" id="mockCount"><option value="5">5 questions</option><option value="10" selected>10 questions</option><option value="15">15 questions</option><option value="20">20 questions (all if fewer are available)</option></select></div>'+
    '<div class="field-group"><label class="label" for="mockMinutes">Time limit</label><select class="select" id="mockMinutes"><option value="15">15 minutes</option><option value="30" selected>30 minutes</option><option value="45">45 minutes</option><option value="60">60 minutes</option><option value="90">90 minutes</option></select></div>'+
    '<div class="field-group"><label class="label" for="mockModule">Question scope</label><select class="select" id="mockModule"><option value="all">All modules</option>'+MODULES.map(function(m){return '<option value="'+m.id+'">LM '+m.no+' · '+esc(m.title)+'</option>';}).join('')+'</select></div>'+
    '<div class="field-group"><label class="label" for="mockReview">Question selection</label><select class="select" id="mockReview"><option value="all">Mixed practice</option><option value="new">Prioritize unattempted questions</option><option value="weak">Prioritize previous errors</option></select></div>'+
    '<button class="btn" type="submit">Start timed mock →</button></form></div>'+
    '<div class="card"><h3 class="card-title">Before you start</h3><div class="revision-item"><div class="check-dot">1</div><div class="row-main"><div class="row-title">Work without the explanation</div><div class="row-subtitle">Answers and teaching notes stay hidden until the mock is submitted.</div></div></div><div class="revision-item"><div class="check-dot">2</div><div class="row-main"><div class="row-title">Manage the clock</div><div class="row-subtitle">The timer updates while the exam is open. When it reaches zero, the attempt is submitted.</div></div></div><div class="revision-item"><div class="check-dot">3</div><div class="row-main"><div class="row-title">Review with care</div><div class="row-subtitle">Only questions with verified answer keys are automatically scored; others are flagged for self-review.</div></div></div><div class="callout blue" style="margin-top:12px">This is a local practice tool, not an official CFA Institute exam or a representation of exam-level difficulty.</div></div></div>';
}

function renderFormulas() {
  const list=FORMULAS.filter(function(f){const q=(ui.formulaQuery||'').toLowerCase();return !q||(f.name+' '+f.formula+' '+f.topic+' '+f.meaning+' '+f.trap).toLowerCase().includes(q);});
  return sectionHeader('VISUAL RECALL','Formula & Visual Maps','Use the maps to understand the structure of each valuation approach. The graphs are labelled illustrations based on formulas in the supplied curriculum, not reproduced textbook exhibits.')+
  '<div class="visual-map-intro"><div class="eyebrow">THE EQUITY VALUATION MEMORY BOARD</div><h3>Connect the six learning modules</h3><p>Each map starts with the question being answered, shows the model or calculation sequence, and closes with a memory hook. Open only the map you need.</p><div class="visual-cue-strip">'+DEEP_STUDY_VISUAL_CUES.map(function(c){return '<div class="visual-cue"><strong>'+esc(c.title)+'</strong><span>'+esc(c.text)+'</span></div>';}).join('')+'</div></div>'+
  '<div class="visual-maps-grid">'+VISUAL_MAPS.map(renderMapDiagram).join('')+'</div>'+
  '<div class="section-header compact-section-header"><div><div class="eyebrow">GRAPHS</div><h3 class="section-title">See how assumptions move value</h3><p class="section-subtitle">Illustrative curves derived from the valuation relationships; not data copied from a curriculum exhibit.</p></div></div>'+
  '<div class="learning-charts-grid">'+renderGordonSensitivityGraph()+renderGrowthFadeGraph()+'</div>'+
  '<details class="formula-library-accordion"><summary><span>Formula library</span><span class="badge muted">'+list.length+' formulas</span><span class="study-note-chevron">＋</span></summary><div class="formula-library-body"><div class="toolbar"><input class="field" id="formulaSearch" placeholder="Search formula, variable or exam trap…" value="'+esc(ui.formulaQuery||'')+'"></div><div class="grid grid-2">'+list.map(function(f){return '<div class="card formula-learning-card"><div class="card-header"><div><div class="eyebrow">'+esc(f.topic)+'</div><h3 class="card-title">'+esc(f.name)+'</h3></div><button class="btn ghost small" data-action="copy-text" data-text="'+esc(f.formula)+'">Copy</button></div><div class="formula-box">'+esc(f.formula)+'</div><p class="formula-meaning">'+esc(f.meaning)+'</p><div class="formula-trap"><strong>Watch for</strong><span>'+esc(f.trap)+'</span></div><button class="link-button" data-action="formula-to-note" data-index="'+FORMULAS.indexOf(f)+'">Add to personal notes ↗</button></div>';}).join('')+'</div></div></details>';
}

function renderFlashcards() {
  const p=profile(), list=FLASHCARDS.concat(p.notes.filter(function(n){return n.type==='flashcard';}).map(function(n){return {id:n.id,front:n.front,back:n.back};}));
  if(ui.flashIndex>=list.length)ui.flashIndex=0;
  const f=list[ui.flashIndex], score=p.flashcardScores[f.id]||{};
  return sectionHeader('ACTIVE RECALL','Flashcards','Reveal the back only after trying to recall the concept. Recall ratings feed the revision queue for this browser profile.')+
  '<div style="max-width:820px;margin:0 auto"><div style="display:flex;justify-content:space-between;align-items:center;color:var(--muted);font-size:11px;margin-bottom:10px"><span>Card '+(ui.flashIndex+1)+' of '+list.length+'</span><span>'+esc(f.id.toUpperCase())+'</span></div><div class="progress-track" style="margin-bottom:17px"><div class="progress-fill" style="width:'+pct(ui.flashIndex+1,list.length)+'%"></div></div><div class="flashcard" data-action="flash-reveal"><div class="flash-label">'+(ui.flashRevealed?'THE ANSWER':'PROMPT · THINK FIRST')+'</div><div class="flash-content">'+esc(ui.flashRevealed?f.back:f.front)+'</div><div class="flash-hint">'+(ui.flashRevealed?'Choose a recall rating below':'Tap the card to reveal the back')+'</div></div><div class="flashcard-controls"><button class="btn secondary" data-action="flash-prev">← Previous</button><button class="btn secondary" data-action="flash-reveal">'+(ui.flashRevealed?'Hide answer':'Reveal answer')+'</button><button class="btn secondary" data-action="flash-next">Next →</button></div>'+(ui.flashRevealed?'<div class="card" style="margin-top:17px;text-align:center"><div class="card-title" style="margin-bottom:12px">How well did you recall it?</div><div class="flashcard-controls"><button class="btn danger" data-action="flash-rate" data-rating="again" data-id="'+esc(f.id)+'">Again · review soon</button><button class="btn secondary" data-action="flash-rate" data-rating="hard" data-id="'+esc(f.id)+'">Hard</button><button class="btn" data-action="flash-rate" data-rating="good" data-id="'+esc(f.id)+'">Good · got it</button></div><div class="card-subtitle" style="margin-top:12px">Last rating: '+esc(score.rating||'Not rated')+' · Due: '+esc(score.due?relativeDate(score.due):'Not scheduled')+'</div></div>':'')+'<div class="card" style="margin-top:17px"><div class="card-header"><div><h3 class="card-title">Create your own card</h3><div class="card-subtitle">Add a private concept card to your profile.</div></div></div><form id="flashcardForm"><div class="form-grid"><div class="field-group"><label class="label" for="flashFront">Front / prompt</label><input class="field" id="flashFront" required placeholder="What do you want to remember?"></div><div class="field-group"><label class="label" for="flashBack">Back / explanation</label><input class="field" id="flashBack" required placeholder="Answer in your own words"></div></div><button class="btn secondary" type="submit">Save flashcard</button></form></div></div>';
}
function getRevisionItems(p) {
  const all=questions(), rows=[];
  all.forEach(function(q){const last=latestFor(p,q.id), bookmarked=p.bookmarks.includes(q.id); if((last&&!last.correct)||bookmarked){rows.push({q:q,reason:!last?'Bookmarked':(!last.correct?'Last attempt incorrect':'Bookmarked'),at:last?last.at:null});}});
  Object.keys(p.flashcardScores).forEach(function(id){const s=p.flashcardScores[id];if(s.due&&new Date(s.due).getTime()<=Date.now()){const f=FLASHCARDS.find(function(x){return x.id===id;});if(f)rows.push({flash:f,reason:'Flashcard due',at:s.due});}});
  return rows;
}
function renderRevision() {
  const p=profile(), items=getRevisionItems(p);
  return sectionHeader('SPACED REVISION','Revision centre','Prioritize incorrect questions, bookmarks, and flashcards due for another retrieval attempt.')+
  '<div class="grid stats-grid">'+statCard('Revision items',items.length,'questions and due cards','↻')+statCard('Incorrect latest answers',questions().filter(function(q){const a=latestFor(p,q.id);return a&&!a.correct;}).length,'across the current question bank','!')+statCard('Bookmarked',p.bookmarks.length,'saved for later review','☆')+statCard('Flashcards rated',Object.keys(p.flashcardScores).length,'recall history stored','▧')+'</div>'+
  '<div class="card"><div class="card-header"><div><h3 class="card-title">Your queue</h3><div class="card-subtitle">No fictional due dates are added; items are based on your saved activity.</div></div><button class="btn secondary small" data-action="nav" data-page="flashcards">Review flashcards ↗</button></div>'+
  (items.length?items.map(function(item){if(item.q)return '<div class="revision-item"><div class="check-dot">↻</div><div class="row-main"><div class="row-title">'+esc(item.q.title)+'</div><div class="row-subtitle">'+esc(item.reason)+' · '+esc(item.q.topic)+'</div></div><button class="btn secondary small" data-action="open-question" data-qid="'+item.q.id+'">Review →</button></div>';return '<div class="revision-item"><div class="check-dot">▧</div><div class="row-main"><div class="row-title">'+esc(item.flash.front)+'</div><div class="row-subtitle">'+esc(item.reason)+'</div></div><button class="btn secondary small" data-action="nav" data-page="flashcards">Review →</button></div>';}).join(''):'<div class="empty-state"><div class="empty-icon">✓</div><h3>Your queue is clear</h3><p>Incorrect answers, bookmarks, or flashcards marked for review will appear here.</p><button class="btn" data-action="nav" data-page="practice">Try a practice question</button></div>')+'</div>';
}
function renderAnalytics() {
  const p=profile(), attempts=p.attempts, latest={}; attempts.forEach(function(a){latest[a.qid]=a;}); const vals=Object.values(latest), correct=vals.filter(function(a){return a.correct;}).length;
  const rows=MODULES.map(function(m){const qs=questions().filter(function(q){return q.module===m.id;});const answered=qs.filter(function(q){return !!latest[q.id];});const c=answered.filter(function(q){return latest[q.id].correct;}).length;return {m:m,answered:answered.length,acc:pct(c,answered.length),covered:pct(answered.length,qs.length)};});
  const last7=[]; for(let i=6;i>=0;i--){const d=new Date();d.setDate(d.getDate()-i);const key=d.toDateString();const n=attempts.filter(function(a){return new Date(a.at).toDateString()===key;}).length;last7.push({label:d.toLocaleDateString(undefined,{weekday:'short'}),n:n});}
  const maxDaily=Math.max(1,...last7.map(function(x){return x.n;}));
  return sectionHeader('PERFORMANCE INTELLIGENCE','Performance analytics','All metrics are calculated from genuine attempts saved under '+state.activeProfile+'. Unattempted topics are shown as not yet measured—not as zero competence.')+
  '<div class="grid stats-grid">'+statCard('Attempt records',attempts.length,'all submissions, including repeats','◈')+statCard('Unique questions',Object.keys(latest).length,'latest result per question','▦')+statCard('Latest-answer accuracy',pct(correct,vals.length)+'%','unattempted questions excluded','↗')+statCard('Study time',formatMin(studyMinutes(p)),'manually logged minutes','◷')+'</div>'+
  '<div class="grid grid-2"><div class="card"><div class="card-header"><div><h3 class="card-title">Accuracy by learning module</h3><div class="card-subtitle">Only modules with attempted questions have a measured score.</div></div></div><div class="chart-bars">'+rows.map(function(r){return '<div class="chart-row"><div class="chart-label" title="'+esc(r.m.title)+'">LM '+r.m.no+' · '+esc(r.m.title.split(':')[0])+'</div><div class="progress-track"><div class="progress-fill" style="width:'+r.acc+'%;opacity:'+(r.answered?1:.22)+'"></div></div><div class="chart-value">'+(r.answered?r.acc+'%':'—')+'</div></div>';}).join('')+'</div><div class="legend" style="margin-top:17px"><span><i class="legend-dot"></i>Latest correctness among attempted questions</span></div></div><div class="card"><div class="card-header"><div><h3 class="card-title">Activity · last 7 days</h3><div class="card-subtitle">Number of submitted attempts, by calendar day.</div></div></div><div style="height:165px;display:flex;align-items:flex-end;gap:12px;padding:8px 3px 0">'+last7.map(function(x){const height=x.n?Math.max(5,pct(x.n,maxDaily)):0;return '<div style="display:flex;flex-direction:column;align-items:center;gap:8px;flex:1;height:100%;justify-content:flex-end"><span style="font-size:10px;color:var(--muted)">'+x.n+'</span><div style="width:100%;max-width:35px;height:'+height+'%;min-height:'+(x.n?4:0)+'px;background:linear-gradient(180deg,#54d6b3,#148b7b);border-radius:7px 7px 2px 2px"></div><span style="font-size:9px;color:var(--muted)">'+x.label+'</span></div>';}).join('')+'</div></div></div>'+
  '<div class="card" style="margin-top:17px"><div class="card-header"><div><h3 class="card-title">Module-level detail</h3><div class="card-subtitle">Coverage means at least one saved attempt for a question currently available in that module.</div></div><button class="btn secondary small" data-action="export-data">Export my data</button></div><div class="table-wrap"><table><thead><tr><th>Learning module</th><th>Attempted</th><th>Question coverage</th><th>Latest accuracy</th><th>Next action</th></tr></thead><tbody>'+rows.map(function(r){return '<tr><td>LM '+r.m.no+' · '+esc(r.m.title)+'</td><td>'+r.answered+' / '+questions().filter(function(q){return q.module===r.m.id;}).length+'</td><td>'+r.covered+'%</td><td>'+(r.answered?r.acc+'%':'Not measured')+'</td><td><button class="link-button" data-action="study-module" data-module="'+r.m.id+'">Open module ↗</button></td></tr>';}).join('')+'</tbody></table></div></div>';
}



const INTEGRATED_TEACHING_GUIDES = [
{id:'guide-m1-1',module:'m1',title:'1.1 · Intrinsic value, market price and estimation error',core:'Intrinsic value is a reasoned estimate rather than an observable fact; market price is observable, but it may or may not reflect the asset’s true economic value. A perceived price/value gap can contain true mispricing and the analyst’s own estimation error. Therefore an analyst should test forecasts and risk assumptions, compare them with the market expectations implied by price, and consider the time horizon over which a catalyst might change the market’s view.',steps:['Define the valuation date, purpose, perspective and value premise.','Forecast the economic benefits relevant to the asset using explicit assumptions.','Compare your growth, margin, reinvestment and risk assumptions with what the market price appears to imply.','Challenge the estimate with sensitivity analysis and independent evidence.','Identify catalysts and the risk that value will not be recognized within the investor’s horizon.'],example:'If estimated value is $82 and price is $70, the $12 gap is only perceived mispricing. If the estimate is too high because the forecast is optimistic, the true opportunity may be smaller or absent.',formula:'Estimated value − price = (estimated value − true value) + (true value − price)',trap:'A correct valuation thesis can still fail if convergence takes longer than the portfolio’s investment horizon.',memory:'Estimate value, compare with price, then challenge your own estimate.'},
{id:'guide-m1-2',module:'m1',title:'1.2 · Business analysis, report quality and model selection',core:'A model is only as credible as the business understanding, accounting inputs and purpose behind it. Start with how the firm makes money, its competitive position, management, resources and risk. Translate this information into forecast drivers before choosing among absolute, relative, asset-based or sum-of-the-parts approaches. Warning signs such as unusual one-off gains, aggressive revenue timing or cash-flow/earnings divergence should trigger investigation, not an unsupported accusation.',steps:['Understand customers, products, pricing power, suppliers, competitors and barriers to entry.','Assess whether reported earnings and assets represent maintainable economics.','Choose a model compatible with company characteristics, available information and the valuation purpose.','Cross-check the result with another appropriate method and stress-test key assumptions.','Communicate assumptions, uncertainty and limitations alongside the conclusion.'],example:'A company with negative earnings, no expected dividends for years and meaningful future cash-generation potential may be unsuitable for P/E or DDM now. An FCFF model may fit better if operating cash flows can be forecast credibly.',formula:'Business analysis → data quality → forecast → model selection → value → communication',trap:'A low peer multiple alone does not prove undervaluation; a financial-reporting red flag is not proof of manipulation.',memory:'Understand first; pick the formula second.'},
{id:'guide-m2-1',module:'m2',title:'2.1 · Dividend discount models and timing',core:'The value of common equity under a dividend discount model is the present value of expected shareholder distributions. A single-period holding model includes both the next dividend and the expected sale price at the end of the holding period. A multiyear DDM discounts each dividend and a terminal value for distributions beyond the explicit forecast. The valuation date, dividend date and terminal date must be explicit.',steps:['Identify whether the latest dividend is D0 or the next expected dividend is D1.','Choose the growth pattern: stable, high-then-stable, gradual fade or multiple stages.','Forecast each explicit-period dividend, then estimate a defensible terminal value.','Discount each cash flow the correct number of periods at the required return on equity.','Check that payout, growth and required return are consistent with the business outlook.'],example:'If D0 = $2.00 and growth is 5%, then D1 = $2.10. With r = 11% and stable g = 5%, the Gordon value is $2.10 / (0.11 − 0.05) = $35.00.',formula:'P0 = D1 / (r − g), where r > g',trap:'Do not substitute D0 for D1 or use stable growth for a company that is still in a distinct growth phase.',memory:'Date first; use D1; require r > g.'},
{id:'guide-m2-2',module:'m2',title:'2.2 · Growth, payout, ROE and terminal value',core:'Sustainable growth is tied to profitability and reinvestment. Under stable assumptions, g is often estimated as ROE multiplied by the retention ratio. DuPont analysis explains what drives ROE through margins, asset turnover and leverage. A high growth rate is not necessarily valuable if reinvestment earns below the required return. Terminal value is measured at a specific forecast date and uses the cash flow or dividend for the following period.',steps:['Link growth assumptions to profitability, retention, capital requirements and returns on incremental investment.','Use a single-stage model only when stable growth is credible; otherwise forecast the transition explicitly.','Choose a two-stage, H-model or three-stage approach that matches the expected growth path.','At the terminal date, use next-period cash flow and a stable growth assumption.','Test sensitivity to r, g, payout and the length of the high-growth phase.'],example:'ROE of 16% and retention of 40% imply a stable sustainable-growth estimate of 6.4%. This estimate is not independent of the assumptions that ROE and financing remain stable.',formula:'g ≈ ROE × retention ratio; TVn = CF(n+1) / (r − g)',trap:'A Year 4 terminal value uses Year 5 cash flow. Perpetual growth cannot equal or exceed the applicable discount rate.',memory:'Growth needs retention and returns; terminal value uses next-period cash flow.'},
{id:'guide-m3-1',module:'m3',title:'3.1 · FCFF, FCFE and the cash-flow bridge',core:'FCFF represents cash available to debt and equity providers; discounted at WACC it estimates enterprise value. FCFE represents cash available to common equity after financing flows; discounted at the required return on equity it estimates equity value. The distinction is not cosmetic: starting points and financing adjustments determine which claimholders the cash flow serves.',steps:['Identify the starting measure—net income, EBIT, EBITDA or operating cash flow—and note what it already includes.','From net income, add non-cash charges and after-tax interest, then subtract fixed-capital and working-capital investment to estimate FCFF.','Convert FCFF to FCFE by subtracting after-tax interest and adding net borrowing.','Define net borrowing as new debt issued less debt repaid; net repayment is negative borrowing.','Match FCFF with WACC and enterprise value; match FCFE with cost of equity and equity value.'],example:'NI $80m + NCC $12m + after-tax interest $7.5m − capex $22m − working-capital investment $5m = FCFF $72.5m, given those stated inputs.',formula:'FCFF = NI + NCC + Int(1 − T) − FCInv − WCInv; FCFE = FCFF − Int(1 − T) + net borrowing',trap:'Do not pair FCFF with the cost of equity or reverse the sign of net borrowing.',memory:'Cash flow available to whom determines the discount rate and value type.'},
{id:'guide-m3-2',module:'m3',title:'3.2 · Forecast construction, terminal value and sensitivity',core:'Forecast cash flow from operational drivers—revenue, margins, taxes, non-cash charges, capital expenditures and working capital—rather than projecting a headline growth rate alone. Growth requires reinvestment, so the forecast should explain how the firm funds its expansion. A stable terminal state is appropriate only after unusual growth and investment patterns have faded or can be reasonably normalized.',steps:['Build a driver-based forecast and explain material changes in each input.','Use explicit stages for growth, leverage or reinvestment transitions.','Set the terminal valuation date before selecting the cash flow for the terminal formula.','Use a discount rate and perpetual growth assumption consistent with the cash flow and stable state.','Stress-test assumptions that drive value and avoid double-counting a risk in both forecast cash flow and discount rate.'],example:'With terminal date at Year 3, Year 4 FCFF of $24m, WACC of 9% and stable growth of 3%, TV at Year 3 is $24m / (0.09 − 0.03) = $400m. This value must still be discounted to today.',formula:'TVn = FCFF(n+1) / (WACC − g), assuming WACC > g',trap:'Terminal value is a value at the terminal date—not a time-zero cash flow.',memory:'Forecast the operating engine, then value the post-forecast cash flow.'},
{id:'guide-m4-1',module:'m4',title:'4.1 · Relative valuation and comparable-company multiples',core:'A multiple compares a value numerator with a financial denominator. Equity-value multiples pair with equity measures; enterprise-value multiples pair with operating measures available to capital providers. A peer comparison is meaningful only after accounting definitions, growth, risk, profitability, payout and capital intensity have been assessed. Multiples summarize assumptions; they do not remove the need for analysis.',steps:['Choose peers with similar economics and explain remaining differences.','Normalize denominators for one-off items, cycle conditions and accounting policy.','Use P/E, P/B, P/S, price-to-cash-flow or EV/EBITDA only when its denominator is meaningful for the firm.','Interpret the premium or discount through growth, margins, risk and reinvestment, not by rank alone.','Cross-check an implied value against a fundamental model.'],example:'A firm at 8× EV/EBITDA versus a peer at 6× is not automatically overvalued. Higher expected growth, better margins or lower risk might justify part of the premium; accounting and capital intensity might explain the rest.',formula:'Equity value ≈ P/E × earnings; enterprise value ≈ EV/EBITDA × EBITDA',trap:'EBITDA is not free cash flow because it excludes taxes, capital expenditures and working-capital investment.',memory:'Comparable numerator, denominator and economics.'},
{id:'guide-m4-2',module:'m4',title:'4.2 · Justified multiples, cyclical earnings and quality',core:'Justified multiples link price to fundamental drivers such as payout, growth, required return and profitability. Peer multiples describe market pricing of a reference group. Cyclical earnings can reverse the intuitive P/E signal: a trough can make P/E high because earnings are depressed, while a peak can make P/E low because earnings are temporarily elevated. Normalize earnings and inspect accounting quality before interpreting a multiple.',steps:['Identify trailing, leading or normalized earnings in the denominator.','Use justified multiples only when the model’s stable-state assumptions fit the firm.','Normalize cyclical earnings before comparing P/E across time or peers.','Investigate revenue recognition, principal-versus-agent presentation and unusual accounting.','Use several indicators as cross-checks, not as a mechanical average.'],example:'Payout of 40%, required return of 10% and stable growth of 4% imply a simple justified leading P/E of 0.40 / (0.10 − 0.04) = 6.67×. The interpretation depends on whether a stable state is defensible.',formula:'Leading P/E = payout / (r − g); stable P/B = (ROE − g) / (r − g)',trap:'A multiple derived from stable assumptions is not reliable if earnings and growth are volatile or inconsistent.',memory:'Normalize first, model second, compare third.'},
{id:'guide-m5-1',module:'m5',title:'5.1 · Residual income and the equity capital charge',core:'Accounting profit is not automatically economic profit to shareholders. Residual income subtracts the required return on beginning book equity from net income. Positive residual income means accounting earnings exceed the equity capital charge; zero means they just cover it. Residual-income valuation adds the present value of future residual income to current book value.',steps:['Start with beginning common book equity for the period.','Compute capital charge = required return on equity × beginning book equity.','Subtract the charge from net income to get residual income.','Forecast and discount future residual income at the required return on equity.','Add the present value of future residual income to current book value and check accounting consistency.'],example:'Net income $18m minus a 10% capital charge on beginning BVE of $120m ($12m) yields residual income of $6m.',formula:'RI = NI − (r × beginning BVE); V0 = B0 + PV(future RI)',trap:'Do not use ending book equity for the standard beginning-period charge or confuse residual income with FCFE.',memory:'Residual income is earnings after charging for equity capital.'},
{id:'guide-m5-2',module:'m5',title:'5.2 · Clean surplus, book value and accounting adjustments',core:'The basic clean-surplus relationship says ending book equity equals beginning book equity plus net income less dividends. This links the income statement to changes in the balance sheet and supports residual-income valuation. Other comprehensive income and direct-to-equity entries can change book equity without passing through net income, so any apparent mismatch must be reconciled before applying the simple relationship.',steps:['Reconcile beginning and ending common book value.','Identify dividends, share issuance, repurchases and direct-to-equity entries.','Investigate accounting policy changes and unusual items affecting earnings or book value.','Normalize only with evidence and an economic reason.','Ensure the book-value baseline and forecast residual income are internally consistent.'],example:'Beginning BVE $100m + NI $15m − dividends $4m = $111m before direct-to-equity changes. A separate $3m gain in OCI would add $3m to ending equity, all else equal.',formula:'BVE(end) = BVE(begin) + NI − dividends',trap:'Residual-income valuation depends on reliable accounting inputs and clean-surplus consistency.',memory:'Reconcile earnings and distributions, then account for what bypasses earnings.'},
{id:'guide-m6-1',module:'m6',title:'6.1 · Private-company valuation and maintainable earnings',core:'Owner compensation, related-party transactions, one-off costs and non-operating activities can make private-company reported earnings differ from maintainable economics. Normalization is not a way to maximize the valuation; it estimates the earnings a market participant could reasonably expect to continue. Every adjustment should be supported, classified and considered from the viewpoint of the valuation premise.',steps:['Separate operating activity from non-operating assets, income and costs.','Identify genuinely non-recurring items and determine whether they affect maintainable results.','Compare owner-manager compensation with a suitable replacement cost.','Normalize accounting definitions before applying comparable multiples.','Reflect customer concentration, founder dependence and forecast uncertainty explicitly.'],example:'Reported earnings are $750,000 after paying the owner-manager $90,000. If replacement compensation is $160,000, normalized earnings fall by $70,000 to $680,000, all else equal. The compensation gap reduces maintainable earnings; it is not an add-back.',formula:'Maintainable earnings = reported earnings ± supported, economically justified adjustments',trap:'Do not remove recurring expenses or costs necessary to operate the business.',memory:'Normalize to sustainable market-participant economics.'},
{id:'guide-m6-2',module:'m6',title:'6.2 · Private-company methods, control and marketability',core:'Income approaches value expected economic benefits, market approaches use relevant comparable companies or transactions, and asset-based approaches may fit selected valuation premises. The method depends on available information and purpose. Control and marketability describe different attributes: control concerns decision rights; marketability concerns the ability to sell the interest efficiently. They must be analysed separately and supported by evidence.',steps:['Clarify valuation premise and whether the subject interest is controlling or non-controlling.','Use an income method when maintainable forecasts and discount rates are defensible.','Apply market multiples only after assessing comparability and normalizing results.','For a diversified parent, value divisions separately when appropriate and reconcile cash, debt and corporate costs.','Support any premium or discount with evidence about the interest and avoid double-counting benefits.'],example:'A controlling block may transfer the ability to direct decisions. A minority stake with no readily available market raises a separate marketability question. One adjustment does not automatically justify the other.',formula:'Sum-of-parts equity value = Σ business values + non-operating assets − debt-like claims and other relevant adjustments',trap:'Do not apply control premiums or marketability discounts automatically.',memory:'Separate method, rights and ability to sell.'}
];
function renderIntegratedGuide(g) {
  return '<details class="integrated-guide-card" data-search="'+esc((g.title+' '+g.core+' '+g.steps.join(' ')+' '+g.example+' '+g.formula+' '+g.trap+' '+g.memory).toLowerCase())+'"><summary><span class="notes-module-number">LM '+getModule(g.module).no+'</span><span class="integrated-guide-title">'+esc(g.title)+'</span><span class="study-note-chevron">＋</span></summary><div class="integrated-guide-body"><div class="integrated-guide-section"><h4>Concept explained</h4><p>'+esc(g.core)+'</p></div><div class="integrated-guide-section"><h4>How to approach the problem</h4><ol>'+g.steps.map(function(s){return '<li>'+esc(s)+'</li>';}).join('')+'</ol></div><div class="integrated-guide-example"><div class="eyebrow">WORKED / INTERPRETIVE EXAMPLE</div><p>'+esc(g.example)+'</p></div><div class="integrated-guide-formula"><strong>Relationship to remember</strong><code>'+esc(g.formula)+'</code></div><div class="note-exam-trap"><strong>Common exam trap</strong><span>'+esc(g.trap)+'</span></div><div class="note-memory"><strong>Memory hook</strong><span>'+esc(g.memory)+'</span></div><div class="integrated-guide-source">Teaching synthesis aligned with this learning module. Examples are illustrative, not reproduced curriculum questions.</div></div></details>';
}
function renderUnifiedFormulaCard(f) {
 const extras={
 'Gordon growth model':['P0 = today’s value; D1 = next expected dividend; r = required return on equity; g = stable perpetual growth.','Use when long-run dividend growth is stable and meaningful; require r > g.','D1 $2.10, r 11%, g 5% → P0 = $2.10 / 6% = $35.00.'],
 'Implied required return from Gordon model':['r = implied required return; D1/P0 = forward dividend yield; g = stable growth.','Infer return implied by the market price and explicit dividend-growth assumptions.','P0 $50, D1 $2.50, g 3% → r = 5% + 3% = 8%.'],
 'Sustainable growth rate':['ROE = return on equity; retention = share of earnings retained.','Use under stable financing and when retained capital can earn the stated ROE.','ROE 16%, retention 40% → growth = 6.4%.'],
 'FCFF from net income':['NI = net income; NCC = net non-cash charges; Int = interest; T = tax rate; FCInv and WCInv = fixed-capital and working-capital investment.','Use to estimate cash available to all capital providers when starting from net income.','NI $80m + NCC $12m + after-tax interest $7.5m − capex $22m − WC investment $5m = FCFF $72.5m.'],
 'FCFE from FCFF':['After-tax interest = Int(1 − T); net borrowing = new debt issued less debt repaid.','Convert total-provider free cash flow to common-equity cash flow after financing.','FCFF $150m − after-tax interest $12m + net borrowing $8m = FCFE $146m.'],
 'Stable-growth terminal value':['CF(n+1) = cash flow one period after the terminal date; discount rate must match that cash flow.','Use only after the company reaches a defensible stable state.','Terminal date Year 3; Year 4 CF $24m, WACC 9%, g 3% → TV $400m.'],
 'Justified leading P/E':['Price divided by next-period earnings; payout = proportion distributed; r = required return; g = stable growth.','Use when stable-growth assumptions are defensible and the denominator is forward earnings.','Payout 40%, r 10%, g 4% → leading P/E ≈ 6.67×.'],
 'Stable-growth P/B':['P/B = price to current book value; ROE = sustainable return on equity; r = required return; g = growth.','Use when book equity and stable profitability assumptions are meaningful.','ROE 15%, g 4%, r 10% → P/B ≈ 1.83×.'],
 'Residual income':['RI = residual income; NI = net income; r = required return on equity; beginning BVE = beginning book equity.','Measures accounting earnings above the equity capital charge.','NI $18m − 10% × beginning BVE $120m = RI $6m.'],
 'Residual-income equity value':['B0 = current book value; PV = present value of expected future residual income.','Use when book value and future residual-income forecasts are reliable and consistent.','Book value $80/share + PV future RI $18/share = indicated value $98/share.'],
 'Clean-surplus relationship':['BVE(end) = ending equity; BVE(begin) = beginning equity; NI = net income; dividends = distributions.','Use to reconcile book value movement; inspect direct-to-equity items separately.','Beginning equity $100m + NI $15m − dividends $4m = $111m before direct-to-equity entries.'],
 'Normalized earnings':['Adjustments can involve substantiated one-offs, owner-specific costs, related-party transactions and non-operating activity.','Estimate maintainable earnings when reported results are not representative.','Replacement pay $160k versus owner pay $90k reduces normalized earnings by $70k, all else equal.'],
 'FCFF enterprise value to equity value':['Enterprise value covers operating assets available to debt and equity; common equity is residual after senior claims.','Reconcile an FCFF-derived enterprise value to the value belonging to common shareholders.','EV $980m + excess cash $35m − debt $245m − preferred $10m − NCI $20m = common equity $740m.']
 }[f.name]||[f.meaning,f.meaning,'Check units, timing, claimant group and assumptions before substituting inputs.'];
 return '<article class="card formula-learning-card unified-formula-card" data-search="'+esc((f.name+' '+f.formula+' '+f.topic+' '+f.meaning+' '+f.trap+' '+extras.join(' ')).toLowerCase())+'"><div class="card-header"><div><div class="eyebrow">'+esc(f.topic)+'</div><h3 class="card-title">'+esc(f.name)+'</h3></div><button class="btn ghost small" data-action="copy-text" data-text="'+esc(f.formula)+'">Copy formula</button></div><div class="formula-box">'+esc(f.formula)+'</div><div class="formula-explanation-grid"><div><h4>Variables and meaning</h4><p>'+esc(extras[0])+'</p></div><div><h4>When to use it</h4><p>'+esc(extras[1])+'</p></div><div><h4>Worked illustration</h4><p>'+esc(extras[2])+'</p></div><div><h4>Common trap</h4><p>'+esc(f.trap)+'</p></div></div></article>';
}
function renderUnifiedMap(map) {
 const rows=map.rows.map(function(row,i){const nodes=row.map(function(n,j){return '<div class="memory-node"><div class="memory-node-title">'+esc(n.title)+'</div><div class="memory-node-sub">'+esc(n.sub)+'</div></div>'+(j<row.length-1?'<span class="memory-branch" aria-hidden="true">↔</span>':'');}).join('');return '<div class="memory-map-row '+(row.length>1?'memory-map-fork':'')+'">'+nodes+'</div>'+(i<map.rows.length-1?'<div class="memory-down" aria-hidden="true">↓</div>':'');}).join('');
 return '<details class="visual-map-card unified-visual-map" data-search="'+esc((map.title+' '+map.strap+' '+map.memory+' '+map.takeaway+' '+map.rows.flat().map(function(n){return n.title+' '+n.sub;}).join(' ')).toLowerCase())+'"><summary class="visual-map-summary"><span class="visual-map-module">LM '+getModule(map.module).no+'</span><span class="visual-map-heading">'+esc(map.title)+'</span><span class="visual-map-strap">'+esc(map.strap)+'</span><span class="visual-map-chevron">＋</span></summary><div class="visual-map-body"><div class="memory-map-diagram">'+rows+'</div><div class="memory-takeaway"><strong>Memory hook</strong><span>'+esc(map.memory)+'</span></div><p class="map-takeaway-text">'+esc(map.takeaway)+'</p></div></details>';
}

function renderStudyNoteCard(n) {
  const paragraphs=String(n.body||'').split(/\n\s*\n/).flatMap(function(part){const sentences=part.match(/[^.!?]+[.!?]+(?:\s|$)|[^.!?]+$/g)||[part];const groups=[];for(let i=0;i<sentences.length;i+=3)groups.push(sentences.slice(i,i+3).join(' ').trim());return groups.filter(Boolean);});
  return '<details class="study-note-card" data-search="'+esc((n.title+' '+n.body+' '+n.sourceRef+' '+n.source).toLowerCase())+'"><summary class="study-note-summary"><span class="badge '+(n.source==='SSEI'?'blue':'muted')+'">'+esc(n.source)+'</span><span class="study-note-title">'+esc(n.title)+'</span><span class="study-note-meta">'+esc(n.sourceRef)+'</span><span class="study-note-chevron">＋</span></summary><div class="study-note-body"><div class="study-note-topic">'+esc(getModule(n.module).title)+'</div><h4 class="study-note-section-label">Detailed explanation</h4>'+paragraphs.map(function(part){return '<p>'+esc(part)+'</p>';}).join('')+(n.memory?'<div class="note-memory"><strong>Memory hook</strong><span>'+esc(n.memory)+'</span></div>':'')+(n.examTrap?'<div class="note-exam-trap"><strong>Exam trap</strong><span>'+esc(n.examTrap)+'</span></div>':'')+'</div></details>';
}

function buildCurriculumInventory() {
  const pages=ui.sourcePages||[],meta=state.shared.sourceMeta||{};
  const signature=pages.length+'|'+(meta.importedAt||'')+'|'+(meta.fileName||'');
  if(ui.curriculumInventoryCache&&ui.curriculumInventoryCache.signature===signature)return ui.curriculumInventoryCache.data;
  const textPages=pages.filter(function(p){return p.type==='Curriculum text';}),examples=[],exhibits=[],seen=new Set();
  const tidy=function(s){return String(s||'').replace(/\s+/g,' ').trim();};
  textPages.forEach(function(p){
    const lines=String(p.text||'').split('\n');
    for(let i=0;i<lines.length;i++){
      const example=lines[i].match(/^\s*EXAMPLE\s+(\d+)\s*$/i);
      if(example){
        const next=[];
        for(let j=i+1;j<lines.length&&next.length<2;j++){
          const value=tidy(lines[j]);if(!value)continue;
          if(/^(?:EXAMPLE|EXHIBIT)\s+\d+/i.test(value)||/^LEARNING MODULE\s+\d+/i.test(value))break;
          if(/^(?:Learning Module \d+|Equity Valuation|Practice Problems|Solutions)$/i.test(value))continue;
          next.push(value);
        }
        const isSubtitle=/^(?:Historical|Illustrative|Numerical|Hypothetical)\s+Example/i.test(next[0]||'');
        const title=next.length>1&&isSubtitle?next.slice(0,2).join(' — '):(next[0]||('Example '+example[1]));
        const id='example-'+p.module+'-'+example[1]+'-'+p.printedPage;
        if(!seen.has(id)){seen.add(id);examples.push({id:id,kind:'Example',number:Number(example[1]),title:title,module:p.module,printedPage:p.printedPage,pdfPage:p.pdfPage,pageId:p.id});}
        continue;
      }
      const exhibit=lines[i].match(/^\s*EXHIBIT\s+(\d+)\s*:\s*(.*?)\s*$/i)||lines[i].match(/^\s*EXHIBIT\s+(\d+)\s*$/i);
      if(exhibit){
        const number=Number(exhibit[1]);let title=tidy(exhibit[2]||'');
        if(!title)for(let j=i+1;j<lines.length&&j<=i+3;j++){
          const value=tidy(lines[j]);if(!value)continue;
          if(/^(?:EXAMPLE|EXHIBIT)\s+\d+/i.test(value)||/^(?:PRACTICE PROBLEMS|SOLUTIONS)$/i.test(value))break;
          title=value;break;
        }
        const id='exhibit-'+p.module+'-'+number+'-'+p.printedPage;
        if(!seen.has(id)){seen.add(id);exhibits.push({id:id,kind:'Exhibit',number:number,title:title||('Exhibit '+number),module:p.module,printedPage:p.printedPage,pdfPage:p.pdfPage,pageId:p.id});}
      }
    }
  });
  const index=buildSourceQuestionBlockIndex(),blocks=Object.keys(index).map(function(k){return index[k];}),groupMap=new Map();
  blocks.forEach(function(b){
    if(b.sourceSetId&&!groupMap.has(b.sourceSetId))groupMap.set(b.sourceSetId,{
      id:b.sourceSetId,title:b.sourceSetTitle||('LM '+getModule(b.module).no+' · Questions '+b.sourceGroupFrom+'–'+b.sourceGroupTo),
      module:b.module,from:b.sourceGroupFrom,to:b.sourceGroupTo,printedPage:b.passagePage??b.page,
      pdfPage:b.passagePdfPage??((b.passagePage??b.page)+10),passageAvailable:!!b.passageText,
      questionCount:Number(b.sourceGroupTo)-Number(b.sourceGroupFrom)+1
    });
  });
  const sets=Array.from(groupMap.values()).sort(function(a,b){return getModule(a.module).no-getModule(b.module).no||a.from-b.from;});
  const standalone=blocks.filter(function(b){return !b.sourceSetId;}).map(function(b){return {id:'standalone-'+b.module+'-'+b.num,title:'LM '+getModule(b.module).no+' · Question '+b.num,module:b.module,number:b.num,printedPage:b.page,pdfPage:b.page+10};});
  const data={indexed:textPages.length>0,pages:pages.length,textPages:textPages.length,examples:examples,exhibits:exhibits,sets:sets,standalone:standalone,questionCount:blocks.length,expectedQuestionCount:MODULES.reduce(function(sum,m){return sum+(m.questionCount||0);},0),passageAvailableSets:sets.filter(function(s){return s.passageAvailable;}).length};
  ui.curriculumInventoryCache={signature:signature,data:data};
  return data;
}
