        stem:parsed.stem||block.text,options:parsed.options,correct:key,responseType:parsed.options.length>=2?'mcq':'constructed',
        sourceBookQuestion:true,bookImported:true,sourceMappingVersion:2,sourceSetId:block.sourceSetId||null,sourceSetTitle:block.sourceSetTitle||'',sourceGroupFrom:block.sourceGroupFrom??null,sourceGroupTo:block.sourceGroupTo??null,passagePage:block.passagePage??null,passagePdfPage:block.passagePdfPage??null,sourcePage:block.page===block.endPage?String(block.page):String(block.page)+'–'+String(block.endPage),
