    merged.stem=candidate.stem;merged.options=candidate.options;merged.responseType=candidate.responseType;merged.sourceSetId=candidate.sourceSetId||null;merged.sourceSetTitle=candidate.sourceSetTitle||'';merged.sourceGroupFrom=candidate.sourceGroupFrom??null;merged.sourceGroupTo=candidate.sourceGroupTo??null;merged.sourcePage=candidate.sourcePage;merged.sourcePdfPage=candidate.sourcePdfPage;merged.sourceSolution=candidate.sourceSolution||'';
