function renderApp() {
  if(state.theme==='light')document.body.classList.add('light-mode');else document.body.classList.remove('light-mode');
  const content=ui.page==='source'?renderSource():ui.page==='dashboard'?renderDashboard():ui.page==='subjects'?renderSubjects():ui.page==='subjectdetail'?renderSubjectDetail():ui.page==='learn'?(ui.studyModule?renderModuleDetail(getModule(ui.studyModule)):renderLearn()):ui.page==='curriculum'?renderCurriculum():ui.page==='questions'?renderQuestionBank():ui.page==='practice'?(ui.practiceMode?renderPractice():renderPracticeHub()):ui.page==='itemset'?renderItemSet():ui.page==='mock'?(ui.exam&&ui.exam.finished?renderMockResults():renderMock()):ui.page==='formulas'?renderFormulas():ui.page==='flashcards'?renderFlashcards():ui.page==='revision'?renderRevision():ui.page==='analytics'?renderAnalytics():ui.page==='notes'?renderNotes():ui.page==='questionbuilder'?renderQuestionBuilder():renderSettings();
  document.getElementById('app').innerHTML='<div class="app-shell">'+renderSidebar()+'<div class="main-area">'+renderTopbar()+'<main class="content">'+content+'</main></div></div>';
  if(ui.page==='mock'&&ui.exam&&!ui.exam.finished)startExamClock();
}
function navigate(page,extra) {
  ui.page=page;ui.selectedAnswer=null;ui.answerShown=false;if(page==='practice')ui.practiceMode=!!(extra&&extra.qid);ui.studyModule=extra&&extra.module?extra.module:(page==='learn'?null:ui.studyModule);
  if(extra&&extra.qid){ui.currentQuestion=extra.qid;ui.practiceStartedAt=Date.now();}
  if(page==='practice'&&!extra?.qid){const qs=questions().filter(function(q){return !extra?.module||q.module===extra.module;});const candidate=qs.find(function(q){return questionStatus(profile(),q)==='unattempted';})||qs[0];if(candidate)ui.currentQuestion=candidate.id;ui.practiceStartedAt=Date.now();}
  if(page==='learn'&&!extra?.module)ui.studyModule=null;
  if(page==='questions'&&extra?.module){ui.filterModule=extra.module;ui.questionQuery='';}
  if(page!=='mock'){stopExamClock();}
  renderApp();window.scrollTo(0,0);
}
function openQuestion(id) { ui.currentQuestion=id;ui.selectedAnswer=null;ui.answerShown=false;ui.practiceStartedAt=Date.now();navigate('practice',{qid:id}); }
function recordAttempt(q,answer,confidence,mode,selfAssessment) {
  const p=profile();
  const unscored=q.responseType==='constructed'||!q.correct||(q.sourceBookQuestion&&q.verificationStatus!=='Verified by learner');
  const correct=unscored?null:answer===q.correct;
  p.attempts.push({qid:q.id,answer:answer,correct:correct,selfAssessment:selfAssessment||null,confidence:Number(confidence||2),mode:mode||'practice',at:new Date().toISOString(),durationSeconds:Math.max(1,Math.round((Date.now()-ui.practiceStartedAt)/1000))});
  p.confidence[q.id]=Number(confidence||2);p.lastVisit=new Date().toISOString();saveState();
  return correct;
}
function stopExamClock(){if(examInterval){clearInterval(examInterval);examInterval=null;}}
function startExamClock() {
  stopExamClock();if(!ui.exam||ui.exam.finished)return;
  examInterval=setInterval(function(){if(!ui.exam||ui.exam.finished){stopExamClock();return;}ui.exam.remainingSeconds-=1;const el=document.getElementById('examClock');if(el)el.textContent=formatSeconds(ui.exam.remainingSeconds);if(ui.exam.remainingSeconds<=0){finishExam(true);}},1000);
}
function startExam(config) {
  let list=questions().filter(function(q){return !config.module||config.module==='all'||q.module===config.module;});
  if(config.review==='new')list.sort(function(a,b){return (latestFor(profile(),a.id)?1:0)-(latestFor(profile(),b.id)?1:0);});
  if(config.review==='weak')list.sort(function(a,b){return (questionStatus(profile(),a)==='incorrect'?-1:0)-(questionStatus(profile(),b)==='incorrect'?-1:0);});
  list=list.sort(function(a,b){if(config.review==='new' || config.review==='weak')return 0;return Math.random()-.5;});
  const count=Math.min(config.count,list.length);
  ui.exam={ids:list.slice(0,count).map(function(q){return q.id;}),answers:{},index:0,remainingSeconds:config.minutes*60,finished:false,startedAt:Date.now(),forcedTimeout:false};
  ui.page='mock';ui.selectedAnswer=null;ui.answerShown=false;renderApp();
}
function finishExam(timeout) {
  if(!ui.exam||ui.exam.finished)return;
  stopExamClock();const ex=ui.exam;ex.finished=true;ex.forcedTimeout=!!timeout;
  ex.ids.forEach(function(id){const q=getQuestion(id);const ans=ex.answers[id]||null;recordAttempt(q,ans,2,'mock');});
  profile().studyLog.push({at:new Date().toISOString(),minutes:Math.max(1,Math.round((Date.now()-ex.startedAt)/60000)),kind:'mock'});saveState();renderApp();
}
function getWeakQuestions(p) {
  const all=questions(), p2=p||profile();
  return all.slice().sort(function(a,b){const aa=latestFor(p2,a.id),bb=latestFor(p2,b.id);const va=aa?(aa.correct?0:3):1,vb=bb?(bb.correct?0:3):1;return vb-va;});
}
function renderAppSafe() { try{renderApp();}catch(e){console.error(e);document.getElementById('app').innerHTML='<div style="padding:40px;color:#fff;font-family:system-ui"><h1>Dashboard could not render</h1><p>Please refresh the page. If the issue persists, export your local data if possible and report the console error.</p><pre>'+esc(e.stack||e.message||e)+'</pre></div>';}}
function exportJSON(obj,filename) {
  const blob=new Blob([JSON.stringify(obj,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(function(){URL.revokeObjectURL(url);},1000);
}
function buildQuestionTutorPrompt(title,stem,correct,source,solution) {
  return 'You are a precise CFA Level II Equity Valuation tutor. Use the learner-provided question and solution below as source material. Do not invent facts, an official answer, or page references. If a calculation or answer appears inconsistent, flag it explicitly and show the independent check. Distinguish source-supported statements from your own teaching example.\n\nTASK\nExplain this question much better than a bookish answer key. Teach the first principles and solve it so the learner can apply the method to a new problem.\n\nREQUIRED OUTPUT\n1. Restate the tested concept in plain language.\n2. Give an intuition-first explanation.\n3. List the relevant inputs and what is being asked.\n4. Show the formula, define variables and assumptions, then work through every calculation step.\n5. Explain the financial interpretation.\n6. For every answer choice, explain why it is correct or wrong, the misconception behind each distractor, and when a distractor would become plausible.\n7. Highlight question-specific exam traps and a memory aid.\n8. Create one original transfer question with different inputs and give its answer separately.\n9. List uncertainties and source references without guessing.\n\nQUESTION TITLE / TOPIC\n'+title+'\n\nQUESTION AND CHOICES\n'+stem+'\n\nANSWER GIVEN BY SOURCE (MAY BE UNKNOWN)\n'+(correct||'Not supplied')+'\n\nSOURCE LOCATION\n'+(source||'Not supplied')+'\n\nSOURCE SOLUTION OR LEARNER WORK\n'+(solution||'Not supplied')+'\n\nKeep the explanation mathematically rigorous, explicit, and pedagogically clear.';
}
async function importPDF(file) {
  ui.importing=true;ui.importPercent=0;ui.importStatus='Loading PDF parser…';renderApp();
  try {
    const pdfjsLib=await import('https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.10.38/pdf.min.mjs');
    pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.10.38/pdf.worker.min.mjs';
    const pdf=await pdfjsLib.getDocument({data:new Uint8Array(await file.arrayBuffer())}).promise;
    const plan=sourcePlan(pdf.numPages), pages=[];
    if(pdf.numPages!==473) notify('This PDF has '+pdf.numPages+' pages; the page mapping assumes a ten-page front-matter offset. Review printed and PDF page labels in the source vault.',true);
    for(let i=0;i<plan.length;i++) {
      const p=plan[i], pdfPage=p.pdfPage;
      if(pdfPage<1||pdfPage>pdf.numPages)continue;
      ui.importStatus='Extracting printed page '+p.printedPage+' ('+(i+1)+' of '+plan.length+')…';ui.importPercent=Math.round((i/plan.length)*100);
      const page=await pdf.getPage(pdfPage), text=await page.getTextContent();
      pages.push({id:p.module+'-'+p.type.replace(/\W/g,'').toLowerCase()+'-'+p.printedPage,module:p.module,printedPage:p.printedPage,pdfPage:pdfPage,type:p.type,text:linesFromItems(text.items)});
      if(i%4===0) {const status=document.getElementById('importStatus'), percent=document.getElementById('importPercent'),bar=document.getElementById('importBar');if(status)status.textContent=ui.importStatus;if(percent)percent.textContent=ui.importPercent+'%';if(bar)bar.style.width=ui.importPercent+'%';await new Promise(function(resolve){setTimeout(resolve,0);});}
    }
    await saveSourcePages(pages);ui.sourcePages=pages;ui.sourceBlockIndex=null;ui.curriculumInventoryCache=null;ui.sourcePageIndex=0;ui.notesSourceIndex=0;
    const parsed=buildBookQuestionCandidates(pages);mergeImportedBookQuestions(parsed);
    state.shared.sourceMeta=sourceArchiveMeta(file.name,pdf.numPages,pages,parsed.stats,new Date().toISOString());
    saveState();ui.importPercent=100;ui.importStatus='Import complete';notify('Indexed '+pages.length+' curriculum pages, including practice problems and solutions. Parsed '+parsed.stats.extracted+' of '+parsed.stats.expected+' question candidates; all source items remain flagged for review.'); 
  } catch(e) {console.error(e);notify('PDF import failed. Check internet access for the PDF.js parser and try again.',true);ui.importStatus='Import failed: '+(e.message||'unknown error');}
  ui.importing=false;renderAppSafe();
}
function exportSource() { exportJSON({sourceMeta:state.shared.sourceMeta,pages:ui.sourcePages},'cfa-equity-source-pages-local.json'); }
function makeQuestionFromBuilder(formData) {
  const opts=formData.options.split('\n').map(function(line){const bits=line.split('|');return {key:(bits[0]||'').trim().toUpperCase(),text:(bits.slice(1).join('|')||'').trim()};}).filter(function(o){return o.key&&o.text;});
  if(opts.length<2)throw new Error('Enter at least two options, one per line in the format A|Answer text.');
  const correct=formData.correct.trim().toUpperCase();
  if(!opts.some(function(o){return o.key===correct;}))throw new Error('The correct-answer key must match one of the option letters.');
  let rationales=[];
  if((formData.rationales||'').trim()){
    rationales=JSON.parse(formData.rationales);
    if(!Array.isArray(rationales))throw new Error('Answer-choice explanations must be a JSON array.');
    const keys=new Set(rationales.map(function(x){return String(x.key||'').toUpperCase();}));
    if(opts.some(function(o){return !keys.has(o.key);}))throw new Error('Provide a rationale for every answer choice in the JSON array.');
    rationales=rationales.map(function(x){return {key:String(x.key).toUpperCase(),text:String(x.text||'').trim()};});
    if(rationales.some(function(x){return !x.text;}))throw new Error('Each answer-choice rationale needs explanatory text.');
  } else {
    rationales=opts.map(function(o){return {key:o.key,text:o.key===correct?'Marked as the source answer. Independently verify the reasoning before relying on it.':'Add a verified explanation of this distractor before treating this item as complete.'};});
  }
  const id='custom-'+Date.now();
  const passage=String(formData.sourcePassage||'').trim();const itemSetId=passage?'manual-'+formData.module+'-'+passage.toLowerCase().replace(/[^a-z0-9]+/g,'-').slice(0,36):null;
  return {id:id,module:formData.module,topic:formData.title,type:formData.type||'Source question',difficulty:formData.difficulty||'Review',title:formData.title,stem:formData.stem,options:opts,correct:correct,sourcePassage:passage,itemSetId:itemSetId,itemSetTitle:passage?formData.title+' · Shared passage':'',sourcePage:formData.sourcePage,sourceBookQuestion:true,explain:{intuition:formData.intuition||'Use the question’s assumptions to identify the relevant valuation relationship.',steps:(formData.steps||'Review the source solution and confirm each step.').split('\n').filter(Boolean),formula:formData.formula||'',rationales:rationales,trap:formData.trap||'Check that the formula, timing, units and assumptions match the question.',memory:formData.memory||'',transfer:formData.transfer||'Create an original variant with different facts and independently verify its answer.',transferAnswer:formData.transferAnswer||'Not supplied; build and verify a new variant before using it for assessment.'},verificationStatus:'Needs explanation review'};
}
function renderSourcePagePrompt(id) {
  const p=ui.sourcePages.find(function(x){return x.id===id;}); if(!p)return;
  ui.page='source';ui.tutorPrompt=buildQuestionTutorPrompt('CFA Level II Equity Valuation — '+p.type+' page '+p.printedPage,'Source page text (may contain one or more questions or a continuation):\n'+p.text,'Not reliably parsed from page text','LM '+getModule(p.module).no+', printed p. '+p.printedPage,'Use the page text as context, identify questions and solutions carefully, and flag incomplete statements or page continuations.');
  renderApp();setTimeout(function(){const out=document.getElementById('tutorPromptOutput'),txt=document.getElementById('generatedTutorPrompt');if(out)out.classList.remove('hidden');if(txt)txt.value=ui.tutorPrompt;},20);
}
function handleClick(e) {
  const target=e.target.closest('[data-action]');if(!target)return;
  const a=target.dataset.action, d=target.dataset;
  if(a==='nav'){ui.query='';if(d.page==='questions'&&d.module){ui.filterModule=d.module;ui.questionQuery='';}navigate(d.page,{module:d.module||null});if(d.page==='questions'&&d.module){ui.filterModule=d.module;renderApp();}return;}
  if(a==='open-source-location'){
    const page=ui.sourcePages.find(function(p){return p.module===d.module&&Number(p.printedPage)===Number(d.printedPage)&&p.type==='Curriculum text';});
    ui.page='source';ui.sourceType='all';ui.sourceSearch='';ui.sourcePageIndex=page?Math.max(0,Math.floor(ui.sourcePages.filter(function(p){return true;}).findIndex(function(p){return p.id===page.id;})/8)):0;ui.sourceExpanded=page?page.id:null;renderApp();
    if(!page)notify('The original page text is not indexed in this browser. Open Source Vault and import the supplied PDF.',true);
    else setTimeout(function(){document.querySelector('.source-page-text')?.scrollIntoView({behavior:'smooth',block:'start'});},0);
    return;
  }
  if(a==='find-item-set'){
    ui.page='questions';ui.query='';ui.questionQuery=d.setTitle||d.setId||'';ui.filterModule='all';ui.filterType='all';ui.filterStatus='all';ui.onlyWeak=false;renderApp();window.scrollTo(0,0);return;
  }
  if(a==='subject-detail'){ui.currentSubject=d.subject||'equity';ui.page='subjectdetail';renderAppSafe();window.scrollTo(0,0);return;}
  if(a==='menu'){document.getElementById('sidebar')?.classList.toggle('open');return;}
  if(a==='clear-note-search'){ui.noteSearch='';ui.notesSourceIndex=0;renderApp();return;}
  if(a==='theme'){state.theme=state.theme==='dark'?'light':'dark';saveState();renderApp();return;}
  if(a==='open-question'){ui.constructedAnswer='';ui.constructedAssessmentSaved=false;openQuestion(d.qid);return;}
  if(a==='study-module'){ui.studyModule=d.module;ui.page='learn';ui.selectedAnswer=null;ui.answerShown=false;renderApp();return;}
  if(a==='toggle-topic'){const el=document.getElementById('topic-'+d.topicIndex);if(el)el.classList.toggle('hidden');return;}
  if(a==='submit-answer'){const q=getQuestion(d.qid),constructed=!Array.isArray(q.options)||q.options.length===0;
    if(constructed){ui.constructedAnswer=(document.getElementById('constructedAnswer')?.value||ui.constructedAnswer||'').trim();if(!ui.constructedAnswer){notify('Write your working before submitting.',true);return;}ui.answerShown=true;ui.constructedAssessmentSaved=false;renderApp();return;}
    if(!ui.selectedAnswer)return;
    if(q.sourceBookQuestion&&q.verificationStatus!=='Verified by learner'){ui.answerShown=true;ui.constructedAssessmentSaved=false;renderApp();return;}
    recordAttempt(q,ui.selectedAnswer,document.getElementById('confidenceSelect')?.value||2,'practice');ui.answerShown=true;renderApp();return;}
  if(a==='next-question'||a==='previous-question'){const current=getQuestion(ui.currentQuestion),set=getQuestionSet(current),arr=questions().filter(function(item){return getQuestionSet(item).id===set.id;}),idx=arr.findIndex(function(item){return item.id===current.id;}),step=a==='next-question'?1:-1,next=idx+step;if(next>=0&&next<arr.length)openQuestion(arr[next].id);else notify(next<0?'You are at the first question in this set.':'You have reached the last question in this set.');return;}
  if(a==='bookmark'){const p=profile(),id=d.qid;const i=p.bookmarks.indexOf(id);if(i>=0)p.bookmarks.splice(i,1);else p.bookmarks.push(id);saveState();renderApp();notify(i>=0?'Bookmark removed':'Question bookmarked');return;}
  if(a==='reset-filters'){ui.questionQuery='';ui.query='';ui.filterModule='all';ui.filterType='all';ui.filterStatus='all';ui.onlyWeak=false;renderApp();return;}
  if(a==='toggle-source'){ui.sourceExpanded=ui.sourceExpanded===d.id?null:d.id;renderApp();return;}
  if(a==='notes-source-prev'){ui.notesSourceIndex=Math.max(0,(ui.notesSourceIndex||0)-1);renderApp();document.getElementById('notes-source-pages')?.scrollIntoView({block:'start'});return;}
  if(a==='notes-source-next'){ui.notesSourceIndex=(ui.notesSourceIndex||0)+1;renderApp();document.getElementById('notes-source-pages')?.scrollIntoView({block:'start'});return;}
  if(a==='source-prev'){ui.sourcePageIndex=Math.max(0,ui.sourcePageIndex-1);renderApp();return;}
  if(a==='source-next'){ui.sourcePageIndex+=1;renderApp();return;}
  if(a==='clear-source'){if(confirm('Delete extracted source-page text from this browser? This does not delete the original PDF on your device.'))clearSourcePages().then(function(){ui.sourcePages=[];ui.sourceBlockIndex=null;ui.curriculumInventoryCache=null;state.shared.sourceMeta=null;saveState();renderApp();notify('Local source text cleared');});return;}
  if(a==='export-source'){exportSource();return;}
  if(a==='export-data'){exportJSON({profileName:state.activeProfile,exportedAt:new Date().toISOString(),profile:profile()},'cfa-equity-'+state.activeProfile.toLowerCase().replace(/\s+/g,'-')+'-backup.json');notify('Learner backup exported');return;}
  if(a==='copy-text'){copyToClipboard(d.text||'').then(function(){notify('Copied to clipboard');}).catch(function(err){notify(err.message||'Could not copy text. Select and copy it manually.',true);});return;}
  if(a==='copy-prompt'){const txt=document.getElementById('generatedTutorPrompt');if(txt){copyToClipboard(txt.value).then(function(){notify('Teaching prompt copied');}).catch(function(err){notify(err.message||'Select the prompt and copy it manually.',true);});}return;}
  if(a==='save-constructed-review'){
    const q=getQuestion(d.qid),assessment=document.getElementById('constructedAssessment')?.value||'needs-review';
    const raw=document.getElementById('constructedAnswer')?.value;
    const answer=(raw||ui.constructedAnswer||ui.selectedAnswer||'').trim();
    recordAttempt(q,answer||null,document.getElementById('confidenceSelect')?.value||2,'practice',assessment);
    ui.constructedAssessmentSaved=true;saveState();renderApp();notify('Self-review saved. This response is excluded from automatic accuracy scoring.');return;
  }
  if(a==='verify-source-question'){
    const item=(state.shared.customQuestions||[]).find(function(q){return q.id===d.qid;});
    if(!item)return;
    if(confirm('Confirm that you checked the answer key, calculations, and explanation against your source copy? This records your review, not an official CFA Institute verification.')){
      item.verificationStatus='Verified by learner';item.verifiedAt=new Date().toISOString();item.verifiedBy=state.activeProfile;saveState();renderApp();notify('Marked as reviewed by '+state.activeProfile+'.');
    }
    return;
  }
  if(a==='build-ai-prompt'){const q=getQuestion(d.qid);ui.page='source';ui.tutorPrompt=buildQuestionTutorPrompt(q.title,q.stem+'\n'+q.options.map(function(o){return o.key+'. '+o.text;}).join('\n'),q.correct,'Original in-app practice question; module: '+getModule(q.module).title,q.explain?.steps?.join('\n')||'');renderApp();setTimeout(function(){const out=document.getElementById('tutorPromptOutput'),txt=document.getElementById('generatedTutorPrompt');if(out)out.classList.remove('hidden');if(txt)txt.value=ui.tutorPrompt;},20);return;}
  if(a==='build-source-prompt'){renderSourcePagePrompt(d.id);return;}
  if(a==='import-instructions'){alert('1. Select the supplied local PDF. 2. The app indexes the full printed curriculum, including learning text, examples, exhibits, practice problems and solutions. 3. It stores extracted page text in this browser’s IndexedDB. 4. It does not identify or verify every individual question automatically. 5. Use the teaching-prompt builder on each question and verify answer keys before relying on it.');return;}
  if(a==='create-question-from-page'){const p=ui.sourcePages.find(function(x){return x.id===d.id;});if(!p)return;ui.page='source';ui.sourceQuestionDraft=p;renderApp();setTimeout(function(){const title=document.getElementById('tutorTitle'),question=document.getElementById('tutorQuestion'),source=document.getElementById('tutorSource');if(title)title.value='LM '+getModule(p.module).no+' '+p.type+' — printed page '+p.printedPage;if(question)question.value=p.text;if(source)source.value='LM '+getModule(p.module).no+', printed p. '+p.printedPage+' (PDF p. '+p.pdfPage+')';document.getElementById('tutorPromptForm')?.scrollIntoView({behavior:'smooth',block:'start'});document.getElementById('tutorQuestion')?.focus();notify('Source page text prefilled. Check if the question continues on another page.');},30);return;}
  if(a==='flash-reveal'){ui.flashRevealed=!ui.flashRevealed;renderApp();return;}
  if(a==='flash-prev'){ui.flashIndex=Math.max(0,ui.flashIndex-1);ui.flashRevealed=false;renderApp();return;}
  if(a==='flash-next'){ui.flashIndex=(ui.flashIndex+1)% (FLASHCARDS.length+profile().notes.filter(function(n){return n.type==='flashcard';}).length);ui.flashRevealed=false;renderApp();return;}
  if(a==='flash-rate'){const p=profile(),rating=d.rating,days=rating==='again'?1:rating==='hard'?2:6;p.flashcardScores[d.id]={rating:rating,due:new Date(Date.now()+days*86400000).toISOString(),lastReviewed:new Date().toISOString()};saveState();ui.flashIndex=(ui.flashIndex+1)% (FLASHCARDS.length+profile().notes.filter(function(n){return n.type==='flashcard';}).length);ui.flashRevealed=false;renderApp();notify('Recall rating saved; next review in '+days+' day(s).');return;}
  if(a==='formula-to-note'){const f=FORMULAS[Number(d.index)];profile().notes.push({id:'note-'+Date.now(),title:f.name,module:MODULES.find(function(m){return f.topic.includes(m.title.split(':')[0])||m.title.includes(f.topic);})?.id||'m1',text:f.formula+'\n\n'+f.meaning+'\n\nExam trap: '+f.trap,createdAt:new Date().toISOString()});saveState();notify('Formula added to personal notes');return;}
  if(a==='exam-prev'){if(ui.exam.index>0)ui.exam.index--;renderApp();return;}
  if(a==='exam-next'){if(ui.exam.index<ui.exam.ids.length-1)ui.exam.index++;renderApp();return;}
  if(a==='exam-skip'){if(ui.exam.index<ui.exam.ids.length-1)ui.exam.index++;else finishExam(false);renderApp();return;}
  if(a==='exam-finish'){if(confirm('Submit the mock exam and reveal explanations?'))finishExam(false);return;}
  if(a==='new-mock'){ui.exam=null;renderApp();return;}
  if(a==='log-study'){
    const raw=prompt('How many minutes did you study? Enter a whole number from 1 to 600.');
    if(raw===null)return;
    const mins=Number(raw);
    if(!Number.isInteger(mins)||mins<1||mins>600){notify('Enter a whole number between 1 and 600.',true);return;}
    startStudy(mins);notify('Logged '+mins+' study minutes for '+state.activeProfile+'.');renderApp();return;
  }
  if(a==='save-settings'){const val=Number(document.getElementById('dailyGoal')?.value||45);profile().dailyGoal=Math.max(5,Math.min(600,val));saveState();renderApp();notify('Study goal saved');return;}
  if(a==='reset-profile'){if(confirm('Reset all saved progress, notes, bookmarks and flashcard ratings for '+state.activeProfile+'? Export a backup first if needed.')){const name=state.activeProfile;state.profiles[name]=freshProfile(name);saveState();renderApp();notify(name+' progress reset');}return;}
  if(a==='delete-note'){if(confirm('Delete this personal note?')){profile().notes=profile().notes.filter(function(n){return n.id!==d.id;});saveState();renderApp();}return;}
}
document.addEventListener('click',handleClick);
document.addEventListener('change',function(e){
  if(e.target.id==='profileSelect'||e.target.id==='settingsProfile'){state.activeProfile=e.target.value;ui.selectedAnswer=null;ui.answerShown=false;saveState();renderApp();notify('Switched to '+state.activeProfile+' profile');return;}
  if(e.target.id==='sourceFile'&&e.target.files&&e.target.files[0]){importPDF(e.target.files[0]);return;}
  if(e.target.dataset.topicStatus){const id=e.target.dataset.topicStatus;profile().topicStatus=profile().topicStatus||emptyTopicStatus();profile().topicStatus[id]=e.target.value;saveState();renderAppSafe();notify(getTopic(id).title+' status: '+topicStatusLabel(e.target.value));return;}

  if(e.target.id==='filterModule'){ui.filterModule=e.target.value;renderApp();return;}
  if(e.target.id==='filterType'){ui.filterType=e.target.value;renderApp();return;}
  if(e.target.id==='filterStatus'){ui.filterStatus=e.target.value;renderApp();return;}
  if(e.target.id==='sourceType'){ui.sourceType=e.target.value;ui.sourcePageIndex=0;renderApp();return;}
  if(e.target.id==='notesSourceType'){ui.notesSourceType=e.target.value;ui.notesSourceIndex=0;renderApp();return;}
  if(e.target.id==='curriculumInventoryType'){ui.curriculumInventoryType=e.target.value;renderApp();return;}
  if(e.target.id==='curriculumStatus'){ui.curriculumStatus=e.target.value;renderApp();return;}
  if(e.target.name==='answer'){ui.selectedAnswer=e.target.value;document.querySelectorAll('.answer-option').forEach(function(n){n.classList.toggle('selected',n.querySelector('input')?.checked);});const btn=document.querySelector('[data-action="submit-answer"]');if(btn)btn.disabled=false;return;} if(e.target.id==='constructedAnswer'){ui.constructedAnswer=e.target.value;const btn=document.querySelector('[data-action="submit-answer"]');if(btn)btn.disabled=!e.target.value.trim();return;} if(e.target.id==='examConstructedAnswer'){if(ui.exam){const q=getQuestion(ui.exam.ids[ui.exam.index]);ui.exam.answers[q.id]=e.target.value;}return;}
  if(e.target.name==='examAnswer'){if(ui.exam){const q=getQuestion(ui.exam.ids[ui.exam.index]);ui.exam.answers[q.id]=e.target.value;renderApp();}return;}
  if(e.target.id==='backupFile'&&e.target.files&&e.target.files[0]){restoreBackup(e.target.files[0]);return;}
});
document.addEventListener('input',function(e){
  if(e.target.id==='questionSearch'){ui.questionQuery=e.target.value;ui.query='';const node=document.querySelector('[data-live-question-list]');renderApp();const inp=document.getElementById('questionSearch');if(inp){inp.focus();inp.setSelectionRange(ui.questionQuery.length,ui.questionQuery.length);}return;}
  if(e.target.id==='sourceSearch'){ui.sourceSearch=e.target.value;ui.sourcePageIndex=0;const pos=e.target.selectionStart;renderApp();const inp=document.getElementById('sourceSearch');if(inp){inp.focus();inp.setSelectionRange(pos,pos);}return;}
  if(e.target.id==='formulaSearch'){ui.formulaQuery=e.target.value;const pos=e.target.selectionStart;renderApp();const inp=document.getElementById('formulaSearch');if(inp){inp.focus();inp.setSelectionRange(pos,pos);}return;}
  if(e.target.id==='studyNoteSearch'){ui.noteSearch=e.target.value;ui.notesSourceIndex=0;const pos=e.target.selectionStart;renderApp();const inp=document.getElementById('studyNoteSearch');if(inp){inp.focus();inp.setSelectionRange(pos,pos);}return;}
  if(e.target.id==='curriculumInventorySearch'){ui.curriculumInventorySearch=e.target.value;renderApp();const inp=document.getElementById('curriculumInventorySearch');if(inp){inp.focus();inp.setSelectionRange(ui.curriculumInventorySearch.length,ui.curriculumInventorySearch.length);}return;}
  if(e.target.id==='curriculumSearch'){ui.curriculumQuery=e.target.value;const pos=e.target.selectionStart;renderApp();const inp=document.getElementById('curriculumSearch');if(inp){inp.focus();inp.setSelectionRange(pos,pos);}return;}
});
document.addEventListener('keydown',function(e){
  if(e.target.id==='globalSearch'&&e.key==='Enter'){ui.query=e.target.value;ui.questionQuery=e.target.value;ui.page='questions';renderApp();return;}
  if(e.key==='Escape'){document.getElementById('sidebar')?.classList.remove('open');}
});
document.addEventListener('submit',function(e){
  if(e.target.id==='noteForm'){e.preventDefault();const p=profile();p.notes.push({id:'note-'+Date.now(),title:document.getElementById('noteTitle').value.trim(),module:document.getElementById('noteTopic').value,text:document.getElementById('noteText').value.trim(),createdAt:new Date().toISOString()});saveState();renderApp();notify('Personal note saved');return;}
  if(e.target.id==='flashcardForm'){e.preventDefault();const p=profile();p.notes.push({id:'custom-flash-'+Date.now(),type:'flashcard',front:document.getElementById('flashFront').value.trim(),back:document.getElementById('flashBack').value.trim(),createdAt:new Date().toISOString()});saveState();renderApp();notify('Custom flashcard saved');return;}
  if(e.target.id==='mockForm'){e.preventDefault();startExam({count:Number(document.getElementById('mockCount').value),minutes:Number(document.getElementById('mockMinutes').value),module:document.getElementById('mockModule').value,review:document.getElementById('mockReview').value});return;}
  if(e.target.id==='sourceQuestionForm'){
    e.preventDefault();
    try {
      const formData={module:document.getElementById('sqModule').value,title:document.getElementById('sqTitle').value.trim(),sourcePassage:(document.getElementById('sqPassage')?.value||'').trim(),sourcePage:document.getElementById('sqSourcePage').value.trim(),type:document.getElementById('sqType').value,difficulty:document.getElementById('sqDifficulty').value,correct:document.getElementById('sqCorrect').value.trim(),stem:document.getElementById('sqStem').value.trim(),options:document.getElementById('sqOptions').value,rationales:document.getElementById('sqRationales').value,intuition:document.getElementById('sqIntuition').value.trim(),steps:document.getElementById('sqSteps').value,formula:document.getElementById('sqFormula').value.trim(),trap:document.getElementById('sqTrap').value.trim(),memory:document.getElementById('sqMemory').value.trim(),transfer:document.getElementById('sqTransfer').value.trim(),transferAnswer:document.getElementById('sqTransferAnswer').value.trim()};
      const item=makeQuestionFromBuilder(formData);
      state.shared.customQuestions.push(item);saveState();ui.questionQuery='';ui.query='';ui.filterModule='all';ui.filterType='all';ui.filterStatus='all';ui.page='questions';renderApp();notify('Question saved. Verification status: Needs explanation review.');
    } catch(err) { notify(err.message||'Could not save the source question.',true); }
    return;
  }
  if(e.target.id==='tutorPromptForm'){e.preventDefault();const data={title:document.getElementById('tutorTitle').value.trim(),stem:document.getElementById('tutorQuestion').value.trim(),correct:document.getElementById('tutorCorrect').value.trim(),source:document.getElementById('tutorSource').value.trim(),solution:document.getElementById('tutorSolution').value.trim()};ui.tutorPrompt=buildQuestionTutorPrompt(data.title,data.stem,data.correct,data.source,data.solution);const out=document.getElementById('tutorPromptOutput'),txt=document.getElementById('generatedTutorPrompt');if(out)out.classList.remove('hidden');if(txt)txt.value=ui.tutorPrompt;return;}
});
async function restoreBackup(file) {
  try {const data=JSON.parse(await file.text());if(!data.profile||!data.profileName)throw new Error('This is not a compatible learner backup.');if(!confirm('Replace saved progress for active profile '+state.activeProfile+' with the backup named '+data.profileName+'?'))return;const name=state.activeProfile;state.profiles[name]=Object.assign(freshProfile(name),data.profile,{name:name});saveState();renderApp();notify('Backup restored for '+name);}catch(e){notify(e.message||'Could not restore this backup.',true);}
}
(async function init(){
  if(state.theme==='light')document.body.classList.add('light-mode');
  ui.sourcePages=await loadSourcePages();ui.sourceBlockIndex=null;
  if(reconcileImportedBookQuestions())saveState();
  profile().lastVisit=new Date().toISOString();saveState();
  renderAppSafe();
})();
